"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

/* ═══════════════════════════════════════════════════════════════
   NYUCHI DATA BRIDGE

   The multi-node architecture means data arrives at different speeds
   from different sources. This module standardizes how the UI
   requests, receives, and displays data regardless of which
   layer it comes from.

   FETCH STRATEGY (cascade):
   1. Local cache (SQLite/IndexedDB via RxDB) → instant
   2. Edge (Cloudflare D1/KV) → fast
   3. Cloud (Supabase PostgreSQL) → reliable
   4. Background sync reconciles all layers

   Exports:
   - useNyuchiQuery: local-first data hook
   - NyuchiListView: declarative feed composition
   - NyuchiSearchView: standard search experience
   - optimistic update utilities
   ═══════════════════════════════════════════════════════════════ */

// ─── Data Source Tracking ──────────────────────────────────
export type DataSource = "local" | "edge" | "cloud" | "unknown"
export type FetchStatus = "idle" | "loading" | "success" | "error" | "stale"

interface QueryResult<T> {
  data: T | null
  status: FetchStatus
  source: DataSource
  error: Error | null
  isLoading: boolean
  isStale: boolean
  /** Time of last successful fetch */
  lastFetchedAt: Date | null
  /** Manually refetch */
  refetch: () => Promise<void>
  /** Optimistically set data (reverts on error) */
  setOptimistic: (updater: (current: T | null) => T) => void
}

interface QueryOptions<T> {
  /** Unique key for caching */
  key: string
  /** The fetch function — receives the preferred source */
  fetcher: (source: DataSource) => Promise<T>
  /** Stale time in ms (default 30s) */
  staleTime?: number
  /** Whether to enable the query */
  enabled?: boolean
  /** Callback on success */
  onSuccess?: (data: T, source: DataSource) => void
  /** Callback on error */
  onError?: (error: Error) => void
}

export function useNyuchiQuery<T>({
  key,
  fetcher,
  staleTime = 30_000,
  enabled = true,
  onSuccess,
  onError,
}: QueryOptions<T>): QueryResult<T> {
  const [data, setData] = React.useState<T | null>(null)
  const [status, setStatus] = React.useState<FetchStatus>("idle")
  const [source, setSource] = React.useState<DataSource>("unknown")
  const [error, setError] = React.useState<Error | null>(null)
  const [lastFetchedAt, setLastFetchedAt] = React.useState<Date | null>(null)
  const previousDataRef = React.useRef<T | null>(null)

  const fetchData = React.useCallback(async () => {
    if (!enabled) return
    setStatus("loading")
    setError(null)

    // Try sources in cascade order
    const sources: DataSource[] = ["local", "edge", "cloud"]
    for (const src of sources) {
      try {
        const result = await fetcher(src)
        setData(result)
        setSource(src)
        setStatus("success")
        setLastFetchedAt(new Date())
        previousDataRef.current = result
        onSuccess?.(result, src)

        // If we got local data, still try to sync from cloud in background
        if (src === "local") {
          fetcher("cloud")
            .then((cloudResult) => {
              setData(cloudResult)
              setSource("cloud")
              setLastFetchedAt(new Date())
              previousDataRef.current = cloudResult
            })
            .catch(() => {
              /* silent — local data is good enough */
            })
        }
        return
      } catch {
        continue // Try next source
      }
    }

    // All sources failed
    const err = new Error(`Failed to fetch: ${key}`)
    setError(err)
    setStatus("error")
    onError?.(err)
  }, [key, fetcher, enabled, onSuccess, onError])

  // Staleness check
  const isStale = React.useMemo(() => {
    if (!lastFetchedAt) return true
    return Date.now() - lastFetchedAt.getTime() > staleTime
  }, [lastFetchedAt, staleTime])

  React.useEffect(() => {
    fetchData()
  }, [fetchData])

  // Optimistic update
  const setOptimistic = React.useCallback(
    (updater: (current: T | null) => T) => {
      previousDataRef.current = data
      setData(updater(data))
    },
    [data]
  )

  return {
    data,
    status,
    source,
    error,
    isLoading: status === "loading",
    isStale: status === "success" && isStale,
    lastFetchedAt,
    refetch: fetchData,
    setOptimistic,
  }
}

// ─── NyuchiListView ────────────────────────────────────────
// Declarative feed composition. Every list screen uses this.

interface NyuchiListViewProps<T> {
  /** Items to display */
  items: T[]
  /** Render function for each item */
  renderItem: (item: T, index: number) => React.ReactNode
  /** Loading state — shows skeleton */
  loading?: boolean
  /** Error state — shows error card */
  error?: Error | string | null
  /** Whether more items can be loaded */
  hasMore?: boolean
  /** Callback when bottom is reached */
  onLoadMore?: () => void
  /**
   * Refresh callback. When supplied, a Refresh control renders above the list.
   *
   * Documented as "pull-to-refresh" and destructured but never wired, so a
   * consumer passing it got nothing. It is a button rather than a gesture
   * because this component does not own a scroll container — the page scrolls —
   * so it cannot observe an overscroll at the top of its own list, and a
   * gesture would not be keyboard-reachable in any case (§8.2).
   */
  onRefresh?: () => void
  /** Data source indicator */
  dataSource?: DataSource
  /** Empty state content */
  emptyIcon?: React.ReactNode
  emptyTitle?: string
  emptyMessage?: string
  emptyAction?: React.ReactNode
  /** Number of skeleton items to show while loading */
  skeletonCount?: number
  /** Skeleton variant */
  skeletonVariant?: "row" | "compact"
  /** Retry callback for error state */
  onRetry?: () => void
  /** Header content (above the list) */
  header?: React.ReactNode
  className?: string
}

export function NyuchiListView<T>({
  items,
  renderItem,
  loading,
  error,
  hasMore,
  onLoadMore,
  onRefresh,
  dataSource,
  emptyIcon,
  emptyTitle = "Nothing here yet",
  emptyMessage,
  emptyAction,
  skeletonCount = 4,
  skeletonVariant = "row",
  onRetry,
  header,
  className,
}: NyuchiListViewProps<T>) {
  // Intersection observer for infinite scroll
  const sentinelRef = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    if (!hasMore || !onLoadMore || !sentinelRef.current) return
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) onLoadMore()
      },
      { rootMargin: "200px" }
    )
    observer.observe(sentinelRef.current)
    return () => observer.disconnect()
  }, [hasMore, onLoadMore])

  const isEmpty = !loading && !error && items.length === 0

  return (
    <div
      data-slot="nyuchi-list-view"
      data-portal="https://mzizi.dev/components/nyuchi-list-view"
      data-source={dataSource}
      className={cn("flex flex-col", className)}
    >
      {header}

      {onRefresh && (
        <div className="flex justify-end pb-2">
          <button
            type="button"
            onClick={onRefresh}
            disabled={loading}
            className="min-h-12 rounded-full px-3 text-xs font-medium text-muted-foreground transition-colors hover:bg-muted disabled:opacity-50"
          >
            {loading ? "Refreshing…" : "Refresh"}
          </button>
        </div>
      )}

      {/* Loading skeletons */}
      {loading && items.length === 0 && (
        <div className="flex flex-col gap-2">
          {Array.from({ length: skeletonCount }).map((_, i) => (
            <div
              key={i}
              className={cn(
                "animate-pulse rounded-[var(--radius-card,14px)] bg-card ring-1 ring-foreground/10",
                skeletonVariant === "row"
                  ? "flex items-center gap-3 border-l-4 border-l-foreground/[0.06] py-3 pr-4 pl-3"
                  : "aspect-video"
              )}
            >
              {skeletonVariant === "row" && (
                <>
                  <div className="size-12 shrink-0 rounded-[var(--radius-inner,7px)] bg-foreground/[0.06]" />
                  <div className="flex flex-1 flex-col gap-1.5">
                    <div className="h-4 w-2/3 rounded bg-foreground/[0.06]" />
                    <div className="h-3 w-full rounded bg-foreground/[0.06]" />
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Error state */}
      {error && (
        <div className="flex items-center gap-3 rounded-[var(--radius-card,14px)] border-l-4 border-l-[var(--color-terracotta)] bg-card px-4 py-3 ring-1 ring-foreground/10">
          <div className="min-w-0 flex-1">
            <div className="text-sm font-medium text-foreground">Something went wrong</div>
            <div className="mt-0.5 text-xs text-muted-foreground">
              {typeof error === "string" ? error : error.message}
            </div>
          </div>
          {onRetry && (
            <button
              onClick={onRetry}
              className="shrink-0 text-xs font-medium text-[var(--color-primary)]"
            >
              Retry
            </button>
          )}
        </div>
      )}

      {/* Empty state */}
      {isEmpty && (
        <div className="flex flex-col items-center px-6 py-12 text-center">
          {emptyIcon && <div className="mb-4 text-muted-foreground">{emptyIcon}</div>}
          <h3 className="font-serif text-lg font-bold text-foreground">{emptyTitle}</h3>
          {emptyMessage && <p className="mt-1 text-sm text-muted-foreground">{emptyMessage}</p>}
          {emptyAction && <div className="mt-4">{emptyAction}</div>}
        </div>
      )}

      {/* Items */}
      {items.map((item, i) => (
        <React.Fragment key={i}>{renderItem(item, i)}</React.Fragment>
      ))}

      {/* Infinite scroll sentinel */}
      {hasMore && <div ref={sentinelRef} className="h-4" />}

      {/* Loading more indicator */}
      {loading && items.length > 0 && (
        <div className="flex justify-center py-4">
          <div className="size-6 animate-spin rounded-full border-2 border-muted-foreground/20 border-t-[var(--color-primary)]" />
        </div>
      )}
    </div>
  )
}

export type { QueryResult, QueryOptions, NyuchiListViewProps }

n1-tokens/nyuchi-dx.ts:
/**
 * NYUCHI DEVELOPER EXPERIENCE
 *
 * Meta-infrastructure for the design system itself — how components
 * are documented, versioned, contributed, and deprecated.
 *
 * This ensures the design system scales not just as a codebase
 * but as a collaborative process across all Nyuchi teams.
 */

// ─── Component Maturity Levels ─────────────────────────────
// Every component has a maturity status that communicates
// how stable and well-tested it is.

export type ComponentStatus = "alpha" | "beta" | "stable" | "deprecated"

export const statusConfig: Record<
  ComponentStatus,
  {
    label: string
    color: string
    description: string
    canUseInProduction: boolean
  }
> = {
  alpha: {
    label: "Alpha",
    color: "#F87171",
    description: "Experimental. API will change. Do not use in production.",
    canUseInProduction: false,
  },
  beta: {
    label: "Beta",
    color: "#FBBF24",
    description:
      "API stabilizing. Usable in production with caution. Breaking changes possible in minor versions.",
    canUseInProduction: true,
  },
  stable: {
    label: "Stable",
    color: "#4ADE80",
    description: "Production-ready. API frozen. Breaking changes only in major versions.",
    canUseInProduction: true,
  },
  deprecated: {
    label: "Deprecated",
    color: "#6B6B66",
    description: "Scheduled for removal. Migrate to the specified replacement.",
    canUseInProduction: false,
  },
}

// ─── Component Documentation Schema ────────────────────────
// Defines what every component MUST document before reaching
// stable status. Stored in the component_docs table.

export interface ComponentDocumentation {
  /** Component name */
  name: string
  /** Current maturity status */
  status: ComponentStatus
  /** Version when this component was introduced */
  addedInVersion: string

  /** When to use this component (positive guidance) */
  whenToUse: string[]
  /** When NOT to use this component (negative guidance) */
  whenNotToUse: string[]
  /** Common mistakes and how to avoid them */
  commonMistakes: string[]

  /** Accessibility documentation */
  accessibility: {
    /** ARIA roles applied */
    ariaRoles: string[]
    /** Keyboard interactions */
    keyboardInteractions: { key: string; action: string }[]
    /** What screen readers announce */
    screenReaderBehavior: string
    /** Focus management notes */
    focusManagement: string
    /** WCAG criteria met */
    wcagCriteria: string[]
  }

  /** Code examples */
  examples: { title: string; code: string; description: string }[]

  /** Migration guide (for deprecated components) */
  migration?: {
    replacement: string
    guide: string
    codemod?: string
    deadline?: string
  }

  /** Props API documentation */
  props: { name: string; type: string; required: boolean; default?: string; description: string }[]

  /** Related components */
  relatedComponents: string[]

  /** Which Nyuchi apps use this component */
  usedBy: string[]
}

// ─── Deprecation Warning Utility ───────────────────────────
// Use in deprecated components to warn developers at dev time.

export function deprecationWarning(
  componentName: string,
  replacement: string,
  deadline?: string
): void {
  if (process.env.NODE_ENV === "development") {
    console.warn(
      `[Nyuchi Design] ⚠️ <${componentName}> is deprecated. Use <${replacement}> instead.` +
        (deadline ? ` Will be removed after ${deadline}.` : "") +
        ` See: https://mzizi.dev/components/${replacement}`
    )
  }
}

// ─── Contribution Guidelines ───────────────────────────────
// The process for adding new brand components.

export const CONTRIBUTION_PROCESS = {
  steps: [
    {
      step: 1,
      title: "Propose",
      description:
        "Open a Linear issue with the component name, use case, which apps need it, and which platform schema it maps to. Tag it with [design-system].",
    },
    {
      step: 2,
      title: "Design",
      description:
        "Create a mockup showing all variants, states (default, loading, error, empty, disabled), and responsive behavior. Include dark and light mode.",
    },
    {
      step: 3,
      title: "Build",
      description:
        "Implement as a brand component in the appropriate ecosystem app (components/mukoko/, components/bundu/, etc.). Must use design tokens (no hardcoded values), include accessibility (ARIA, keyboard, focus), respect motion preferences, and handle RTL.",
    },
    {
      step: 4,
      title: "Document",
      description:
        "Fill out the ComponentDocumentation schema: when to use, when not to use, accessibility notes, keyboard interactions, examples, props API.",
    },
    {
      step: 5,
      title: "Review",
      description:
        "Submit for design system review. Reviewers check: token usage, accessibility, motion, RTL, responsive behavior, documentation completeness.",
    },
    {
      step: 6,
      title: "Ship",
      description:
        "Insert into nyuchi_design_db via Supabase. Set status to beta. Monitor usage for one release cycle before promoting to stable.",
    },
  ],
  requirements: {
    /** Component must use CSS custom properties from nyuchi-tokens */
    usesTokens: true,
    /** Must include ARIA attributes and keyboard navigation */
    accessible: true,
    /** Must respect prefers-reduced-motion */
    motionSafe: true,
    /** Must work in RTL layouts */
    rtlReady: true,
    /** Must have responsive behavior defined for all breakpoints */
    responsive: true,
    /** Must have brand-matching skeleton variant */
    hasSkeleton: true,
    /** Must handle error state gracefully */
    handlesErrors: true,
    /** Must have component_docs entry */
    documented: true,
  },
} as const

// ─── Usage Analytics Types ─────────────────────────────────
// Track which components are used, by which apps, how often.
// Stored in usage_events table in nyuchi_design_db.

export interface ComponentUsageEvent {
  componentName: string
  appId: string
  variant?: string
  timestamp: string
  context: "production" | "development" | "storybook"
}

// ─── Versioning Strategy ───────────────────────────────────
export const VERSIONING = {
  scheme: "semver",
  deprecationPolicy:
    "Components are deprecated with 2 minor versions of warning before removal in the next major version.",
  breakingChangeProcess:
    "Breaking changes only in major versions. All breaking changes include migration guides and, where possible, automated codemods.",
  currentVersion: "1.0.0",
} as const

export { statusConfig as componentStatusConfig }

n1-tokens/nyuchi-harness-prewire.tsx:
"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

/* ═══════════════════════════════════════════════════════════════
   NYUCHI COMPONENT HARNESS — Zero-Config Infrastructure Wiring

   The vertical spine that connects N3, N4, and N5 to
   infrastructure. Every brand component (N3), safety gate (N4),
   and resilience wrapper (N5) uses the harness for:

   - Observability (scoped logging, render timing, health reporting)
   - Accessibility (LiveRegion auto-mount, announce(), focus ring)
   - Motion (enter animations, reduced-motion, stagger)

   N2 (primitives) does NOT use the harness — raw building blocks.
   N1 (tokens) does NOT use the harness — pure data.

   TWO USAGE PATTERNS:

   1. NyuchiHarness — declarative wrapper for page sections:
      <NyuchiHarness name="events-feed" skeleton={<FeedSkeleton />}>
        <EventsFeed />
      </NyuchiHarness>

   2. useNyuchiHarness — imperative hook for L3/L4/L5 components:
      function NyuchiListingCard(props) {            // N3 Brand
        const { log, motion, announce } = useNyuchiHarness("listing-card")
      }
      function NyuchiPermissionGate(props) {          // N4 Safety
        const { log, motion, announce } = useNyuchiHarness("permission-gate")
      }
      function NyuchiSection(props) {                 // N5 Resilience
        const { log, motion, announce } = useNyuchiHarness("section")
      }

   WHAT THE HARNESS PROVIDES:

   1. OBSERVABILITY — Scoped logger for the component, render timing
      reported to health monitor, errors tracked with structured context

   2. ERROR BOUNDARY — React error boundary with branded fallback
      (mineral-colored error card, retry button, error count tracking)

   3. MOTION — Entry animation on mount using the motion token system,
      respects prefers-reduced-motion automatically

   4. A11Y — Focus ring CSS variables applied, aria-live region for
      dynamic announcements, screen reader text for trust/verification

   5. TOKENS — Verifies CSS custom properties are present (theme
      provider is mounted), warns in dev if tokens are missing

   6. HEALTH — Reports section status (healthy/degraded/error/loading)
      to the global NyuchiHealthMonitor singleton

   7. LOCALE — Provides text direction (RTL/LTR) and string token
      accessor via useLocale
   ═══════════════════════════════════════════════════════════════ */

// ─── SCOPED LOGGER (from observability) ────────────────────
// Each component gets its own logger prefixed with the component name.

interface ScopedLogger {
  debug: (message: string, data?: Record<string, unknown>) => void
  info: (message: string, data?: Record<string, unknown>) => void
  warn: (message: string, data?: Record<string, unknown>) => void
  error: (message: string, error?: Error, data?: Record<string, unknown>) => void
}

function createScopedLogger(componentName: string): ScopedLogger {
  const prefix = `[mzizi:${componentName}]`
  return {
    debug: (msg, data) => console.debug(`${prefix} ${msg}`, data || ""),
    info: (msg, data) => console.info(`${prefix} ${msg}`, data || ""),
    warn: (msg, data) => console.warn(`${prefix} ${msg}`, data || ""),
    error: (msg, err, data) => console.error(`${prefix} ${msg}`, err || "", data || ""),
  }
}

// ─── MOTION CONFIG (from nyuchi-motion) ────────────────────
// Provides the correct duration/easing for the current user preference.

interface MotionConfig {
  /** Whether user prefers reduced motion */
  prefersReduced: boolean
  /** Duration for entry animations (0 if reduced motion) */
  enterDuration: number
  /** Duration for exit animations */
  exitDuration: number
  /** CSS easing for entry */
  enterEasing: string
  /** CSS easing for exit */
  exitEasing: string
  /** Get stagger delay for item at index in a list */
  staggerDelay: (index: number) => number
  /** CSS class for entry animation */
  enterClass: string
}

function getMotionConfig(): MotionConfig {
  const prefersReduced =
    typeof window !== "undefined"
      ? window.matchMedia("(prefers-reduced-motion: reduce)").matches
      : false

  return {
    prefersReduced,
    enterDuration: prefersReduced ? 0 : 200,
    exitDuration: prefersReduced ? 0 : 100,
    enterEasing: prefersReduced ? "linear" : "cubic-bezier(0, 0, 0.2, 1)",
    exitEasing: prefersReduced ? "linear" : "cubic-bezier(0.4, 0, 1, 1)",
    staggerDelay: (index: number) => (prefersReduced ? 0 : Math.min(index, 8) * 50),
    enterClass: prefersReduced ? "" : "nyuchi-animate-in",
  }
}

// ─── ANNOUNCER (from nyuchi-a11y) ──────────────────────────
// Imperative screen reader announcements for dynamic content.

interface Announcer {
  /** Announce a message to screen readers (polite — waits for current speech) */
  announce: (message: string) => void
  /** Announce urgently (assertive — interrupts current speech) */
  announceUrgent: (message: string) => void
  /** The live region element to render (must be in the DOM) */
  LiveRegion: React.ReactNode
}

function useAnnouncer(): Announcer {
  const [message, setMessage] = React.useState("")
  const [politeness, setPoliteness] = React.useState<"polite" | "assertive">("polite")
  const portalRef = React.useRef<HTMLDivElement | null>(null)

  // Auto-mount LiveRegion via Portal — components no longer need to render <LiveRegion />
  React.useEffect(() => {
    if (typeof document === "undefined") return
    let el = document.getElementById("nyuchi-live-region")
    if (!el) {
      el = document.createElement("div")
      el.id = "nyuchi-live-region"
      el.setAttribute("role", "status")
      el.setAttribute("aria-live", "polite")
      el.setAttribute("aria-atomic", "true")
      el.className = "sr-only"
      document.body.appendChild(el)
    }
    portalRef.current = el as HTMLDivElement
    return () => {
      /* keep mounted — shared across components */
    }
  }, [])

  const announce = React.useCallback((msg: string) => {
    setMessage("")
    setPoliteness("polite")
    requestAnimationFrame(() => {
      setMessage(msg)
      if (portalRef.current) {
        portalRef.current.setAttribute("aria-live", "polite")
        portalRef.current.textContent = msg
      }
    })
  }, [])

  const announceUrgent = React.useCallback((msg: string) => {
    setMessage("")
    setPoliteness("assertive")
    requestAnimationFrame(() => {
      setMessage(msg)
      if (portalRef.current) {
        portalRef.current.setAttribute("aria-live", "assertive")
        portalRef.current.textContent = msg
      }
    })
  }, [])

  const LiveRegion = React.useMemo(
    () => (
      <div
        role="status"
        aria-live={politeness}
        aria-atomic="true"
        style={{
          position: "absolute",
          width: 1,
          height: 1,
          margin: -1,
          padding: 0,
          overflow: "hidden",
          clip: "rect(0,0,0,0)",
          whiteSpace: "nowrap",
          border: 0,
        }}
      >
        {message}
      </div>
    ),
    [message, politeness]
  )

  return { announce, announceUrgent, LiveRegion }
}

// ─── HEALTH REPORTER ───────────────────────────────────────
// Reports component health to the global singleton.

type HealthStatus = "healthy" | "degraded" | "error" | "loading"

interface HealthReporter {
  reportHealthy: () => void
  reportDegraded: (reason?: string) => void
  reportError: (error: Error) => void
  reportLoading: () => void
}

function useHealthReporter(componentName: string): HealthReporter {
  // In a full implementation, this writes to the HealthMonitor singleton
  // from nyuchi-resilience. For now, it logs structured health events
  // that the monitor can pick up.
  const log = createScopedLogger(componentName)

  return {
    reportHealthy: () => log.debug("status: healthy"),
    reportDegraded: (reason) => log.warn(`status: degraded${reason ? ` — ${reason}` : ""}`),
    reportError: (error) => log.error("status: error", error),
    reportLoading: () => log.debug("status: loading"),
  }
}

// ─── TOKEN VERIFIER ────────────────────────────────────────
// Dev-only check that CSS custom properties are present.

function useTokenVerifier(componentName: string) {
  React.useEffect(() => {
    if (process.env.NODE_ENV !== "development") return
    if (typeof window === "undefined") return

    const root = document.documentElement
    const style = getComputedStyle(root)

    const requiredTokens = [
      "--color-malachite",
      "--color-cobalt",
      "--color-tanzanite",
      "--color-gold",
      "--color-terracotta",
      "--radius-card",
      "--radius-inner",
      "--radius-pill",
    ]

    const missing = requiredTokens.filter((token) => {
      const value = style.getPropertyValue(token).trim()
      return !value
    })

    if (missing.length > 0) {
      console.warn(
        `[mzizi:${componentName}] Missing CSS tokens: ${missing.join(", ")}. ` +
          `Wrap your app in <NyuchiThemeProvider> to inject design tokens.`
      )
    }
  }, [componentName])
}

// ─── useNyuchiHarness HOOK ──────────────────────────────
// The imperative API for leaf components.
// Use this inside any brand component to get the full infrastructure.

export interface ComponentHarnessResult {
  /** Scoped observability logger */
  log: ScopedLogger
  /** Motion configuration respecting user preferences */
  motion: MotionConfig
  /** Screen reader announcer */
  announce: (message: string) => void
  announceUrgent: (message: string) => void
  /** Health reporter */
  health: HealthReporter
  /** Live region element (render this in the component) */
  LiveRegion: React.ReactNode
  /** Render timing tracker — call at start of render */
  trackRenderStart: () => void
  /** Render timing tracker — call at end of render (useEffect) */
  trackRenderEnd: () => void
  /** Domain-gated observability attributes for root element (data-portal) */
  observabilityAttrs: Record<string, string>
}

// ─── OBSERVABILITY (domain-gated) ────────────────────────────
// Registry backlinks and observability only render on allowed domains.
// This protects privacy: no tracking on unauthorized domains.
// Domains are controlled via the observability_domains table.

export const INTERNAL_DOMAINS = ["nyuchi.com", "mukoko.com", "localhost"]

function isObservabilityAllowedDomain(): boolean {
  if (typeof window === "undefined") return false
  const hostname = window.location.hostname
  return INTERNAL_DOMAINS.some((d) => hostname === d || hostname.endsWith("." + d))
}

function getObservabilityAttrs(componentName: string): Record<string, string> {
  if (!isObservabilityAllowedDomain()) return {}
  return { "data-portal": `https://mzizi.dev/components/${componentName}` }
}

export function useNyuchiHarness(componentName: string): ComponentHarnessResult {
  const log = React.useMemo(() => createScopedLogger(componentName), [componentName])
  const motion = React.useMemo(() => getMotionConfig(), [])
  const { announce, announceUrgent, LiveRegion } = useAnnouncer()
  const health = useHealthReporter(componentName)
  const renderStartRef = React.useRef(0)

  // Token verification (dev only)
  useTokenVerifier(componentName)

  // Report healthy on mount
  React.useEffect(() => {
    health.reportHealthy()
    log.debug("mounted")
    return () => {
      log.debug("unmounted")
    }
    // Mount/unmount only — `health` and `log` are stable for the component's
    // lifetime, and re-running this would re-report health on every render.
    // (This carried an `eslint-disable-line react-hooks/exhaustive-deps`, but
    // the react-hooks plugin is not configured in `eslint.config.mjs`, so the
    // disable named a rule ESLint could not find and errored on it.)
  }, [])

  const trackRenderStart = React.useCallback(() => {
    renderStartRef.current = performance.now()
  }, [])

  const trackRenderEnd = React.useCallback(() => {
    if (renderStartRef.current > 0) {
      const duration = Math.round((performance.now() - renderStartRef.current) * 100) / 100
      if (duration > 16) {
        // Only log slow renders (>1 frame)
        log.warn(`slow render: ${duration}ms`, { duration })
      }
    }
  }, [log])

  const observabilityAttrs = React.useMemo(
    () => getObservabilityAttrs(componentName),
    [componentName]
  )
  return {
    log,
    motion,
    announce,
    announceUrgent,
    health,
    LiveRegion,
    trackRenderStart,
    trackRenderEnd,
    observabilityAttrs,
  }
}

// ─── NyuchiHarness COMPONENT ───────────────────────────────
// The declarative wrapper for page sections.
// Provides error boundary + skeleton + observability + motion.

interface NyuchiHarnessProps {
  /** Unique name for this section (used in logs and health reports) */
  name: string
  /** Content to render */
  children: React.ReactNode
  /** Whether the section is loading */
  loading?: boolean
  /** Custom skeleton for loading state */
  skeleton?: React.ReactNode
  /** Custom fallback for error state */
  fallback?: React.ReactNode
  /** Whether errors should bubble up instead of being caught */
  critical?: boolean
  /** Animate entry */
  animate?: boolean
  className?: string
}

interface HarnessState {
  hasError: boolean
  error: Error | null
  retryCount: number
}

class NyuchiHarnessBoundary extends React.Component<NyuchiHarnessProps, HarnessState> {
  private log: ScopedLogger
  private renderStart = 0

  constructor(props: NyuchiHarnessProps) {
    super(props)
    this.state = { hasError: false, error: null, retryCount: 0 }
    this.log = createScopedLogger(props.name)
  }

  static getDerivedStateFromError(error: Error): Partial<HarnessState> {
    return { hasError: true, error }
  }

  componentDidCatch(error: Error) {
    this.log.error("render crash", error, {
      retryCount: this.state.retryCount,
      componentStack: error.stack?.split("\\n").slice(0, 5),
    })
  }

  componentDidMount() {
    this.trackRender()
    this.log.debug("mounted")
  }

  componentDidUpdate() {
    this.trackRender()
  }

  componentWillUnmount() {
    this.log.debug("unmounted")
  }

  private trackRender() {
    if (this.renderStart > 0) {
      const duration = Math.round((performance.now() - this.renderStart) * 100) / 100
      if (duration > 16) {
        this.log.warn(`slow render: ${duration}ms`)
      }
    }
  }

  private handleRetry = () => {
    this.log.info(`retry attempt ${this.state.retryCount + 1}`)
    this.setState((prev) => ({ hasError: false, error: null, retryCount: prev.retryCount + 1 }))
  }

  render() {
    this.renderStart = performance.now()
    const { name, children, loading, skeleton, fallback, critical, animate, className } = this.props

    // Loading state
    if (loading) {
      return (
        <div
          data-slot="nyuchi-harness"
          data-section={name}
          data-status="loading"
          className={className}
          role="status"
          aria-label={`${name} loading`}
        >
          {skeleton || (
            <div className="animate-pulse rounded-[var(--radius-card,14px)] bg-card p-4 ring-1 ring-foreground/10">
              <div className="h-4 w-2/3 rounded-[var(--radius-inner,7px)] bg-foreground/[0.06]" />
              <div className="mt-2 h-3 w-full rounded-[var(--radius-inner,7px)] bg-foreground/[0.06]" />
              <div className="mt-2 h-3 w-1/2 rounded-[var(--radius-inner,7px)] bg-foreground/[0.06]" />
            </div>
          )}
        </div>
      )
    }

    // Error state
    if (this.state.hasError) {
      if (critical) throw this.state.error

      return (
        <div
          data-slot="nyuchi-harness"
          data-section={name}
          data-status="error"
          data-retry-count={this.state.retryCount}
          className={className}
          role="alert"
          aria-label={`${name} error`}
        >
          {fallback || (
            <div className="flex flex-col items-center rounded-[var(--radius-card,14px)] bg-card px-6 py-6 text-center ring-1 ring-foreground/10">
              <div className="mb-3 flex size-10 items-center justify-center rounded-full bg-[var(--color-terracotta,#D4A574)]/10">
                <span className="text-lg text-[var(--color-terracotta,#D4A574)]">!</span>
              </div>
              <p className="text-sm font-medium text-foreground">{name} could not load</p>
              <p className="mt-1 text-xs text-muted-foreground">
                {this.state.error?.message || "An unexpected error occurred"}
              </p>
              <button
                onClick={this.handleRetry}
                className={cn(
                  "mt-4 flex h-9 items-center gap-2 rounded-full px-4 text-xs font-medium transition-colors",
                  "border border-[var(--color-border,#2A2A2A)] text-foreground hover:bg-foreground/[0.05]"
                )}
              >
                Try Again{this.state.retryCount > 0 ? ` (${this.state.retryCount})` : ""}
              </button>
            </div>
          )}
        </div>
      )
    }

    // Healthy state — render with optional entry animation
    return (
      <div
        data-slot="nyuchi-harness"
        data-section={name}
        data-status="healthy"
        className={cn(animate && "nyuchi-animate-in", className)}
      >
        {children}
      </div>
    )
  }
}

export function NyuchiHarness(props: NyuchiHarnessProps) {
  return <NyuchiHarnessBoundary {...props} />
}

export type { NyuchiHarnessProps, ScopedLogger, MotionConfig, HealthReporter, HealthStatus }

