//! NYUCHI DOCS ENGINE — N10 documentation, Dioxus.
//!
//! The Rust sibling of `nyuchi-docs-engine.tsx`, sharing its contract: the same `data-slot`,
//! the same sidebar/main split, and the same class strings, so a Dioxus app renders markup a
//! React-authored stylesheet already styles.
//!
//! # Two accessibility defects in the TypeScript, fixed here
//!
//! **1. `role="listitem"` on a `<button>` destroys the button.** The `.tsx` puts
//! `role="list"` on a `<nav>` and `role="listitem"` on each `<button>` inside it. An explicit
//! role REPLACES the implicit one, so assistive technology is told these are list items, not
//! buttons — a screen-reader user loses the "button" announcement and the interaction hint on
//! every navigation control in the sidebar. The `listitem` is invalid regardless: its required
//! owner is a `list`, and `<nav role="list">` is a role clash of its own.
//!
//! Here the nav holds a `<ul>` of `<li>`s, each containing a plain `<button>`. The list
//! semantics are real, and the buttons stay buttons.
//!
//! **2. `min-h-[44px]` is below the floor this system publishes.** N10's own
//! `nyuchi-ai-context` states the rule as "Touch targets: 48px minimum", and the sidebar
//! entries — the primary navigation of a documentation portal, on a mobile viewport — are
//! 44. That is Apple's number, not this system's. Raised to `min-h-[48px]`; nothing else about
//! the control changes.
//!
//! **The `.tsx` sibling still has both.**
//!
//! # A hydration hazard not reproduced
//!
//! The `.tsx` renders `new Date(updatedAt).toLocaleDateString()`. That formats against
//! whatever locale and timezone the runtime has, so a server render and a client render can
//! disagree and React reports a hydration mismatch — and the visible date depends on where
//! the process runs rather than who is reading. [`DocPage::updated_at`] is a pre-formatted
//! string, like `ChangelogEntry::date` next door: the host knows the viewer's locale and this
//! component does not.
//!
//! # The node table, a third time in this node
//!
//! `NODE_LABELS` is hardcoded N1–N10 again. Its fallback is at least graceful — an unknown
//! node renders `N{n}` — so the visible damage is smaller than in the changelog renderer, but
//! it is the same literal going stale. [`node_label`] takes the table as data.

use dioxus::prelude::*;

/// One documentation page.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DocPage {
    /// URL slug, unique.
    pub slug: String,
    /// Page title.
    pub title: String,
    /// Grouping for the sidebar. Hyphens render as spaces.
    pub category: String,
    /// Optional finer grouping. Carried for parity with the `.tsx` and the
    /// `documentation_pages` column; the sidebar groups by `category` alone.
    pub subcategory: Option<String>,
    /// Markdown/MDX body. Rendered by the host — see [`DocsEngineProps::render_content`].
    pub content: String,
    /// Short summary.
    pub description: Option<String>,
    /// Search keywords.
    pub keywords: Vec<String>,
    /// Node numbers this page relates to. Mirrors `documentation_pages.related_nodes`.
    pub related_nodes: Vec<u16>,
    /// Related component names.
    pub related_components: Vec<String>,
    /// Version this page documents.
    pub version: Option<String>,
    /// Last-updated, ALREADY FORMATTED by the host. See the module docs.
    pub updated_at: Option<String>,
}

impl DocPage {
    /// A page with only the required fields.
    #[must_use]
    pub fn new(slug: &str, title: &str, category: &str, content: &str) -> Self {
        Self {
            slug: slug.to_owned(),
            title: title.to_owned(),
            category: category.to_owned(),
            subcategory: None,
            content: content.to_owned(),
            description: None,
            keywords: Vec::new(),
            related_nodes: Vec::new(),
            related_components: Vec::new(),
            version: None,
            updated_at: None,
        }
    }

    /// Whether this page matches a search query.
    ///
    /// Title, description and keywords, case-insensitively — the same three fields the `.tsx`
    /// searches, in the same order.
    #[must_use]
    pub fn matches(&self, query: &str) -> bool {
        let q = query.to_lowercase();
        self.title.to_lowercase().contains(&q)
            || self
                .description
                .as_deref()
                .is_some_and(|d| d.to_lowercase().contains(&q))
            || self.keywords.iter().any(|k| k.to_lowercase().contains(&q))
    }
}

/// A node number to its sidebar label.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NodeLabel {
    /// Node number. Uncapped.
    pub number: u16,
    /// Display text, e.g. `N2 Primitives`.
    pub label: String,
}

/// The node labels as they stand. A DEFAULT, not a definition — see the module docs.
#[must_use]
pub fn default_node_labels() -> Vec<NodeLabel> {
    [
        (1, "N1 Tokens"),
        (2, "N2 Primitives"),
        (3, "N3 Brand"),
        (4, "N4 Safety"),
        (5, "N5 Resilience"),
        (6, "N6 Pages"),
        (7, "N7 Shell"),
        (8, "N8 Assurance"),
        (9, "N9 Fundi"),
        (10, "N10 Docs"),
        (11, "N11 Discovery"),
        (12, "N12 Skills"),
    ]
    .into_iter()
    .map(|(number, label)| NodeLabel {
        number,
        label: label.to_owned(),
    })
    .collect()
}

/// A node's label, falling back to `N{n}` exactly as the `.tsx` does.
#[must_use]
pub fn node_label(labels: &[NodeLabel], n: u16) -> String {
    labels
        .iter()
        .find(|l| l.number == n)
        .map_or_else(|| format!("N{n}"), |l| l.label.clone())
}

/// Filter pages by a search query, preserving order.
///
/// An empty or whitespace-only query returns everything, matching the `.tsx` `search.trim()`.
#[must_use]
pub fn filter_pages(pages: &[DocPage], search: &str) -> Vec<DocPage> {
    if search.trim().is_empty() {
        return pages.to_vec();
    }
    pages
        .iter()
        .filter(|p| p.matches(search))
        .cloned()
        .collect()
}

/// Distinct categories, in first-appearance order.
///
/// The `.tsx` uses `[...new Set(...)]`, which preserves insertion order; a `HashSet` here
/// would reorder the sidebar between runs.
#[must_use]
pub fn categories(pages: &[DocPage]) -> Vec<String> {
    let mut seen: Vec<String> = Vec::new();
    for p in pages {
        if !seen.iter().any(|c| c == &p.category) {
            seen.push(p.category.clone());
        }
    }
    seen
}

/// A category slug as the sidebar shows it: hyphens become spaces.
#[must_use]
pub fn category_label(category: &str) -> String {
    category.replace('-', " ")
}

const ROOT: &str = "flex h-screen overflow-hidden bg-background";
const ASIDE: &str = "w-64 shrink-0 overflow-y-auto border-r border-border p-4";
const SEARCH_INPUT: &str = "min-h-[48px] w-full rounded-[var(--radius-md,12px)] border border-border bg-input px-3 py-2 text-sm focus-visible:outline-2 focus-visible:outline-[var(--ring)]";
const CATEGORY_HEADING: &str =
    "mb-1 px-2 text-xs font-medium tracking-wider text-muted-foreground uppercase";
/// The `.tsx` says `min-h-[44px]`. See the module docs.
const NAV_ITEM: &str = "block min-h-[48px] w-full rounded-[var(--radius-sm,7px)] px-2 py-1.5 text-left text-sm transition-colors focus-visible:outline-2 focus-visible:outline-[var(--ring)]";
const NAV_ITEM_CURRENT: &str = "bg-muted font-medium text-foreground";
const NAV_ITEM_IDLE: &str = "text-muted-foreground hover:bg-muted hover:text-foreground";
const MAIN: &str = "flex-1 overflow-y-auto p-8";
const PAGE_TITLE: &str = "font-serif text-3xl font-bold";
const PAGE_DESCRIPTION: &str = "mt-2 text-lg text-muted-foreground";
const RELATED_NODE: &str =
    "rounded-full bg-muted px-2 py-0.5 font-mono text-xs text-muted-foreground";
const PROSE: &str = "prose prose-sm max-w-none text-foreground";
const FALLBACK_CONTENT: &str = "font-sans text-sm leading-relaxed whitespace-pre-wrap";

/// Join a base class string with a consumer's extra classes.
fn join(base: &str, extra: &str) -> String {
    if extra.is_empty() {
        base.to_owned()
    } else {
        format!("{base} {extra}")
    }
}

/// Props for [`DocsEngine`].
#[derive(Props, Clone, PartialEq)]
pub struct DocsEngineProps {
    /// Every page the portal knows about.
    pub pages: Vec<DocPage>,
    /// Slug of the page on screen.
    #[props(default)]
    pub current_slug: Option<String>,
    /// Called when a sidebar entry is chosen.
    #[props(default)]
    pub on_navigate: Option<EventHandler<String>>,
    /// Current search text.
    #[props(default)]
    pub search: String,
    /// Called as the search box changes. Absent hides the search box, as in the `.tsx`.
    #[props(default)]
    pub on_search: Option<EventHandler<String>>,
    /// Render the page body. Absent falls back to preformatted text.
    ///
    /// The host owns markdown/MDX, exactly as in the `.tsx` — this component does layout and
    /// navigation and deliberately ships no renderer.
    #[props(default)]
    pub render_content: Option<Callback<DocPage, Element>>,
    /// Node labels. Empty means [`default_node_labels`].
    #[props(default)]
    pub node_labels: Vec<NodeLabel>,
    /// Extra classes, merged onto the root.
    #[props(default)]
    pub class: String,
    /// Any other root attributes.
    #[props(extends = GlobalAttributes)]
    pub attributes: Vec<Attribute>,
}

/// The documentation portal: sidebar navigation plus a rendered page.
#[component]
pub fn DocsEngine(props: DocsEngineProps) -> Element {
    let current_page = props
        .current_slug
        .as_ref()
        .and_then(|slug| props.pages.iter().find(|p| &p.slug == slug))
        .cloned();

    let filtered = filter_pages(&props.pages, &props.search);
    let cats = categories(&filtered);

    let owned_labels = default_node_labels();
    let labels: &[NodeLabel] = if props.node_labels.is_empty() {
        &owned_labels
    } else {
        &props.node_labels
    };

    let searching = !props.search.trim().is_empty();

    // Read before the `if let` below consumes `current_page`.
    let main_label = current_page
        .as_ref()
        .map_or_else(|| "Documentation".to_owned(), |p| p.title.clone());

    rsx! {
        div {
            "data-slot": "nyuchi-docs-engine",
            "data-portal": "https://mzizi.dev/components/nyuchi-docs-engine",
            class: join(ROOT, &props.class),
            ..props.attributes,

            aside { class: ASIDE, "aria-label": "Documentation navigation",

                if let Some(on_search) = props.on_search {
                    div { class: "mb-4",
                        label { r#for: "docs-search", class: "sr-only", "Search documentation" }
                        input {
                            id: "docs-search",
                            value: "{props.search}",
                            placeholder: "Search docs...",
                            class: SEARCH_INPUT,
                            oninput: move |e| on_search.call(e.value()),
                        }
                    }
                }

                if cats.is_empty() && searching {
                    p { class: "px-2 text-sm text-muted-foreground", "No results for \"{props.search}\"" }
                }

                for cat in cats.iter() {
                    div { key: "{cat}", class: "mb-4",
                        p { class: CATEGORY_HEADING, "{category_label(cat)}" }
                        // A real list of real buttons. The `.tsx` puts role="list" on the
                        // nav and role="listitem" on each button, which takes the button
                        // role away from every control here.
                        nav {
                            ul { class: "contents",
                                for p in filtered.iter().filter(|p| &p.category == cat) {
                                    li { key: "{p.slug}",
                                        {
                                            let is_current = props.current_slug.as_deref() == Some(p.slug.as_str());
                                            let slug = p.slug.clone();
                                            // Hoisted: an rsx format string takes an ident or a
                                            // simple expression, not an `if` block.
                                            let item_class = format!(
                                                "{NAV_ITEM} {}",
                                                if is_current { NAV_ITEM_CURRENT } else { NAV_ITEM_IDLE }
                                            );
                                            let current = if is_current { "page" } else { "false" };
                                            rsx! {
                                                button {
                                                    class: "{item_class}",
                                                    "aria-current": "{current}",
                                                    onclick: move |_| {
                                                        if let Some(nav) = props.on_navigate {
                                                            nav.call(slug.clone());
                                                        }
                                                    },
                                                    "{p.title}"
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            main {
                class: MAIN,
                "aria-label": "{main_label}",

                if let Some(page) = current_page {
                    article { class: "max-w-3xl",
                        header { class: "mb-8 border-b border-border pb-6",
                            h1 { class: PAGE_TITLE, "{page.title}" }

                            if let Some(description) = page.description.as_ref() {
                                p { class: PAGE_DESCRIPTION, "{description}" }
                            }

                            div { class: "mt-4 flex flex-wrap items-center gap-3 text-xs text-muted-foreground",
                                if let Some(version) = page.version.as_ref() {
                                    span { class: "font-mono", "v{version}" }
                                }
                                if let Some(updated) = page.updated_at.as_ref() {
                                    time { "Updated {updated}" }
                                }
                            }

                            if !page.related_nodes.is_empty() {
                                div {
                                    class: "mt-3 flex flex-wrap gap-1.5",
                                    "aria-label": "Related ecosystem nodes",
                                    for n in page.related_nodes.iter().copied() {
                                        {
                                            let label = node_label(labels, n);
                                            rsx! {
                                                span { key: "{n}", class: RELATED_NODE, title: "{label}", "{label}" }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        div { class: PROSE,
                            if let Some(render) = props.render_content {
                                {render.call(page.clone())}
                            } else {
                                pre { class: FALLBACK_CONTENT, "{page.content}" }
                            }
                        }
                    }
                } else {
                    div { class: "flex h-full items-center justify-center",
                        p { class: "text-muted-foreground",
                            if props.pages.is_empty() {
                                "No documentation pages found."
                            } else {
                                "Select a page from the sidebar."
                            }
                        }
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pages() -> Vec<DocPage> {
        let mut a = DocPage::new("intro", "Getting started", "guides", "body");
        a.description = Some("How to begin".to_owned());
        a.keywords = vec!["setup".to_owned(), "install".to_owned()];
        let b = DocPage::new("tokens", "Design tokens", "reference", "body");
        let c = DocPage::new("button", "Button", "reference", "body");
        vec![a, b, c]
    }

    #[test]
    fn an_empty_search_returns_everything() {
        assert_eq!(filter_pages(&pages(), "").len(), 3);
        assert_eq!(filter_pages(&pages(), "   ").len(), 3);
    }

    #[test]
    fn search_covers_title_description_and_keywords() {
        assert_eq!(filter_pages(&pages(), "Button").len(), 1);
        assert_eq!(filter_pages(&pages(), "how to begin").len(), 1);
        assert_eq!(filter_pages(&pages(), "install").len(), 1);
    }

    #[test]
    fn search_is_case_insensitive_in_both_directions() {
        // Query case and source case both fold.
        assert_eq!(filter_pages(&pages(), "BUTTON").len(), 1);
        assert_eq!(filter_pages(&pages(), "getting STARTED").len(), 1);
    }

    #[test]
    fn search_is_substring_not_fuzzy() {
        // The words are present but not contiguous, so it does not match — the `.ts`
        // uses `String.includes`, and this must behave identically or the two targets
        // return different result sets for the same query.
        assert_eq!(filter_pages(&pages(), "getting fast").len(), 0);
        assert_eq!(filter_pages(&pages(), "sartd").len(), 0);
    }

    #[test]
    fn categories_keep_first_appearance_order() {
        assert_eq!(categories(&pages()), vec!["guides", "reference"]);
    }

    #[test]
    fn categories_of_nothing_is_nothing() {
        assert!(categories(&[]).is_empty());
    }

    #[test]
    fn a_category_slug_renders_with_spaces() {
        assert_eq!(
            category_label("getting-started-fast"),
            "getting started fast"
        );
    }

    #[test]
    fn node_labels_fall_back_to_the_bare_number() {
        let labels = default_node_labels();
        assert_eq!(node_label(&labels, 2), "N2 Primitives");
        assert_eq!(node_label(&labels, 99), "N99");
    }

    #[test]
    fn the_default_labels_reach_past_n10() {
        let labels = default_node_labels();
        assert_eq!(node_label(&labels, 11), "N11 Discovery");
        assert_eq!(node_label(&labels, 12), "N12 Skills");
    }

    #[test]
    fn caller_supplied_labels_replace_the_default() {
        let custom = vec![NodeLabel {
            number: 2,
            label: "Second".to_owned(),
        }];
        assert_eq!(node_label(&custom, 2), "Second");
    }

    #[test]
    fn the_nav_item_meets_the_published_touch_floor() {
        // The .tsx ships min-h-[44px]; the system publishes 48px minimum.
        assert!(NAV_ITEM.contains("min-h-[48px]"));
        assert!(!NAV_ITEM.contains("44px"));
    }

    #[test]
    fn the_search_box_meets_it_too() {
        assert!(SEARCH_INPUT.contains("min-h-[48px]"));
    }
}

n10-documentation/nyuchi-docs-engine.tsx:
"use client"
import * as React from "react"
import { cn } from "@/lib/utils"

// NYUCHI DOCS ENGINE — N10: Documentation Outlier
//
// Renders the documentation portal UI. Data comes from the database
// (documentation_pages table) via nyuchi-docs-api.
//
// Architecture note:
//   - DocPage.relatedNodes mirrors documentation_pages.related_nodes (integer[])
//   - DocPage.content is markdown/MDX — render with your MDX processor of choice
//   - This component handles layout and navigation; content rendering is
//     delegated to the renderContent prop so consumers choose their renderer

export interface DocPage {
  slug: string
  title: string
  category: string
  subcategory?: string
  content: string
  description?: string
  keywords?: string[]
  relatedNodes?: number[]
  relatedComponents?: string[]
  version?: string
  updatedAt?: string
}

export interface DocsEngineProps {
  pages: DocPage[]
  currentSlug?: string
  onNavigate?: (slug: string) => void
  search?: string
  onSearch?: (query: string) => void
  // Delegate content rendering so consumers can use their MDX processor
  // Falls back to a plain pre-formatted text display if not provided
  renderContent?: (content: string, page: DocPage) => React.ReactNode
  className?: string
}

// Ecosystem node labels for the relatedNodes display
const NODE_LABELS: Record<number, string> = {
  1: "N1 Tokens",
  2: "N2 Primitives",
  3: "N3 Brand",
  4: "N4 Safety",
  5: "N5 Resilience",
  6: "N6 Pages",
  7: "N7 Shell",
  8: "N8 Assurance",
  9: "N9 Fundi",
  10: "N10 Docs",
}

function DefaultContentRenderer({ content }: { content: string }) {
  // Minimal safe fallback: render as preformatted text
  // Replace with your MDX processor (next-mdx-remote, @mdx-js/react, etc.)
  return <pre className="font-sans text-sm leading-relaxed whitespace-pre-wrap">{content}</pre>
}

export function DocsEngine({
  pages,
  currentSlug,
  onNavigate,
  search = "",
  onSearch,
  renderContent,
  className,
}: DocsEngineProps) {
  const currentPage = pages.find((p) => p.slug === currentSlug)

  // Filter pages by search query across title, description, and keywords
  const filteredPages = search.trim()
    ? pages.filter((p) => {
        const q = search.toLowerCase()
        return (
          p.title.toLowerCase().includes(q) ||
          p.description?.toLowerCase().includes(q) ||
          p.keywords?.some((k) => k.toLowerCase().includes(q))
        )
      })
    : pages

  // Group pages by category for sidebar navigation
  const categories = [...new Set(filteredPages.map((p) => p.category))]

  const handleKeyDown = (e: React.KeyboardEvent, slug: string) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault()
      onNavigate?.(slug)
    }
  }

  return (
    <div
      data-slot="nyuchi-docs-engine"
      data-portal="https://mzizi.dev/components/nyuchi-docs-engine"
      className={cn("flex h-screen overflow-hidden bg-background", className)}
    >
      {/* Sidebar */}
      <aside
        className="w-64 shrink-0 overflow-y-auto border-r border-border p-4"
        aria-label="Documentation navigation"
      >
        {/* Search */}
        {onSearch && (
          <div className="mb-4">
            <label htmlFor="docs-search" className="sr-only">
              Search documentation
            </label>
            <input
              id="docs-search"
              value={search}
              onChange={(e) => onSearch(e.target.value)}
              placeholder="Search docs..."
              className="min-h-[48px] w-full rounded-[var(--radius-md,12px)] border border-border bg-input px-3 py-2 text-sm focus-visible:outline-2 focus-visible:outline-[var(--ring)]"
            />
          </div>
        )}

        {/* Category sections */}
        {categories.length === 0 && search && (
          <p className="px-2 text-sm text-muted-foreground">No results for "{search}"</p>
        )}

        {categories.map((cat) => (
          <div key={cat} className="mb-4">
            <p className="mb-1 px-2 text-xs font-medium tracking-wider text-muted-foreground uppercase">
              {cat.replace(/-/g, " ")}
            </p>
            <nav role="list">
              {filteredPages
                .filter((p) => p.category === cat)
                .map((p) => (
                  <button
                    key={p.slug}
                    role="listitem"
                    onClick={() => onNavigate?.(p.slug)}
                    onKeyDown={(e) => handleKeyDown(e, p.slug)}
                    aria-current={currentSlug === p.slug ? "page" : undefined}
                    className={cn(
                      "block min-h-[44px] w-full rounded-[var(--radius-sm,7px)] px-2 py-1.5 text-left text-sm transition-colors focus-visible:outline-2 focus-visible:outline-[var(--ring)]",
                      currentSlug === p.slug
                        ? "bg-muted font-medium text-foreground"
                        : "text-muted-foreground hover:bg-muted hover:text-foreground"
                    )}
                  >
                    {p.title}
                  </button>
                ))}
            </nav>
          </div>
        ))}
      </aside>

      {/* Main content */}
      <main
        className="flex-1 overflow-y-auto p-8"
        role="main"
        aria-label={currentPage?.title ?? "Documentation"}
      >
        {currentPage ? (
          <article className="max-w-3xl">
            {/* Page header */}
            <header className="mb-8 border-b border-border pb-6">
              <h1 className="font-serif text-3xl font-bold">{currentPage.title}</h1>

              {currentPage.description && (
                <p className="mt-2 text-lg text-muted-foreground">{currentPage.description}</p>
              )}

              {/* Metadata row */}
              <div className="mt-4 flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
                {currentPage.version && <span className="font-mono">v{currentPage.version}</span>}
                {currentPage.updatedAt && (
                  <time>Updated {new Date(currentPage.updatedAt).toLocaleDateString()}</time>
                )}
              </div>

              {/* Related ecosystem nodes */}
              {currentPage.relatedNodes && currentPage.relatedNodes.length > 0 && (
                <div className="mt-3 flex flex-wrap gap-1.5" aria-label="Related ecosystem nodes">
                  {currentPage.relatedNodes.map((n) => (
                    <span
                      key={n}
                      className="rounded-full bg-muted px-2 py-0.5 font-mono text-xs text-muted-foreground"
                      title={NODE_LABELS[n] ?? `N${n}`}
                    >
                      {NODE_LABELS[n] ?? `N${n}`}
                    </span>
                  ))}
                </div>
              )}
            </header>

            {/* Content — delegate to renderContent or fall back to default */}
            <div className="prose prose-sm max-w-none text-foreground">
              {renderContent ? (
                renderContent(currentPage.content, currentPage)
              ) : (
                <DefaultContentRenderer content={currentPage.content} />
              )}
            </div>
          </article>
        ) : (
          <div className="flex h-full items-center justify-center">
            <p className="text-muted-foreground">
              {pages.length === 0
                ? "No documentation pages found."
                : "Select a page from the sidebar."}
            </p>
          </div>
        )}
      </main>
    </div>
  )
}

// `DocsEngineProps` and `DocPage` are already exported at their declarations, so
// re-listing them here was a TS2484 conflict and this file did not compile in any
// consumer that installed it. Only the alias is a genuinely new export.
export type { DocsEngineProps as NyuchiDocsEngineProps }

n11-discovery/nyuchi-seo.rs:
//! Mzizi N11 discovery — "if the machine can't see it, it doesn't exist."
//!
//! The Rust implementation of `nyuchi-seo`: page metadata and Schema.org JSON-LD,
//! for a host that is not Next.js.
//!
//! # What this owns, and what the host owns
//!
//! This builds the metadata and renders it. It does not know what a framework is.
//! The `.ts` sibling returns a Next.js `Metadata` object and lets the App Router
//! render the tags; there is no App Router here, so [`Metadata::to_head_html`]
//! emits the `<meta>`/`<link>` elements and the host puts them in `<head>`. Same
//! division as N8, which builds an OTLP request and lets the host send it.
//!
//! # A security defect in the TypeScript, fixed here
//!
//! `generateSchemaLD` returns `JSON.stringify(...)` and its own doc comment tells
//! you to inject it with `dangerouslySetInnerHTML`. JSON escaping does not escape
//! `<`, so any schema field carrying the six characters `</script` closes the
//! script element early and everything after it is parsed as HTML. A job title, a
//! product name or an article headline is enough — all four templates take
//! caller-supplied strings, and a marketplace listing is user input.
//!
//! [`generate_schema_ld`] escapes `<` as `\u003c` (and `>` as `\u003e`, and `&`
//! as `\u0026`). Those are valid JSON string escapes, so the JSON-LD parses
//! identically while becoming inert inside a script element. This is the standard
//! mitigation and it costs nothing.
//!
//! **The `.ts` sibling still has this defect.** It is not fixed by this file, and
//! it should be — tracked as part of the back-port of Rust-found defects.
//!
//! # Two things the TypeScript does that this deliberately does not
//!
//! **The `product` og:type dance.** The `.ts` sets `openGraph.type` to `website`
//! when the caller asked for `product`, then re-emits the true value through
//! Next's `other` map — because Next's `OpenGraph` union rejects `product`. That
//! is a workaround for one framework's types, not a fact about Open Graph, so
//! here [`OgType::Product`] simply emits `og:type` as `product` once.
//!
//! **`alternates.languages` built from a bare locale list.** Preserved as-is,
//! including that it emits no `x-default` and does not include the current locale
//! — changing either alters what crawlers do with a live site, which is a
//! product decision rather than a porting one.

use core::fmt::Write as _;

/// What kind of thing the page is, for `og:type`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum OgType {
    /// A generic page.
    #[default]
    Website,
    /// A piece of writing.
    Article,
    /// A person or organisation.
    Profile,
    /// Something for sale. A real `og:type` (ogp.me/ns/product).
    Product,
}

impl OgType {
    /// The wire spelling, matching the `.ts` string union.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Website => "website",
            Self::Article => "article",
            Self::Profile => "profile",
            Self::Product => "product",
        }
    }
}

/// How a link should render on X/Twitter.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum TwitterCard {
    /// Small thumbnail beside the text.
    Summary,
    /// Full-bleed image above the text.
    #[default]
    SummaryLargeImage,
    /// An inline player.
    Player,
}

impl TwitterCard {
    /// The wire spelling, matching the `.ts` string union.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Summary => "summary",
            Self::SummaryLargeImage => "summary_large_image",
            Self::Player => "player",
        }
    }
}

/// The site this metadata describes. Matches the `.ts` module constants.
pub const BASE_URL: &str = "https://mukoko.com";
/// Site name, appended to every title.
pub const SITE_NAME: &str = "Mukoko";
/// Open Graph image used when a page supplies none.
pub const DEFAULT_OG_IMAGE: &str = "/og-default.png";

/// Everything a caller says about a page.
#[derive(Debug, Clone, Default)]
pub struct SeoConfig {
    /// Page title, before ` — Mukoko` is appended.
    pub title: String,
    /// Meta description. Omitted entirely when `None`.
    pub description: Option<String>,
    /// Site-root-relative path, e.g. `/jobs/123`. Joined to [`BASE_URL`].
    pub canonical_url: Option<String>,
    /// Open Graph image URL. Falls back to [`DEFAULT_OG_IMAGE`].
    pub og_image: Option<String>,
    /// What kind of thing this page is.
    pub og_type: OgType,
    /// How the link renders on X/Twitter.
    pub twitter_card: TwitterCard,
    /// Ask crawlers not to index or follow.
    pub no_index: bool,
    /// BCP 47 locale of this page.
    pub locale: Option<String>,
    /// Other locales this page exists in, for `alternates.languages`.
    pub alternate_locales: Vec<String>,
}

/// One `hreflang` alternate.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Alternate {
    /// The locale code.
    pub locale: String,
    /// The absolute URL for that locale.
    pub url: String,
}

/// Resolved page metadata: every value decided, nothing defaulted later.
///
/// The equivalent of the `.ts`'s Next `Metadata` return, minus the framework. A
/// host may read the fields directly or call [`Metadata::to_head_html`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Metadata {
    /// `"<title> — Mukoko"`.
    pub title: String,
    /// Meta description, if the caller gave one.
    pub description: Option<String>,
    /// Absolute canonical URL, if the caller gave a path.
    pub canonical: Option<String>,
    /// `hreflang` alternates, in the order the caller listed them.
    pub alternates: Vec<Alternate>,
    /// True when crawlers should be told to stay away.
    pub no_index: bool,
    /// `og:type`, emitted truthfully — see the module docs.
    pub og_type: OgType,
    /// `og:locale`.
    pub locale: String,
    /// The image URL used for both Open Graph and Twitter.
    pub image: String,
    /// Open Graph image width, fixed at 1200 as in the `.ts`.
    pub image_width: u32,
    /// Open Graph image height, fixed at 630 as in the `.ts`.
    pub image_height: u32,
    /// `og:image:alt` — the raw title, not the site-suffixed one.
    pub image_alt: String,
    /// Twitter card style.
    pub twitter_card: TwitterCard,
}

/// Resolve a [`SeoConfig`] into [`Metadata`], applying every default.
///
/// Mirrors the `.ts` `generateMetadata`, including that an empty `og_image`
/// string falls back to the default (the `.ts` uses `||`, not `??`).
#[must_use]
pub fn generate_metadata(config: &SeoConfig) -> Metadata {
    let full_title = format!("{} — {SITE_NAME}", config.title);

    let image = match config.og_image.as_deref() {
        Some(s) if !s.is_empty() => s.to_owned(),
        _ => DEFAULT_OG_IMAGE.to_owned(),
    };

    let canonical_path = config.canonical_url.as_deref().unwrap_or("");
    let canonical = config
        .canonical_url
        .as_deref()
        .filter(|s| !s.is_empty())
        .map(|path| format!("{BASE_URL}{path}"));

    let alternates = config
        .alternate_locales
        .iter()
        .map(|l| Alternate {
            locale: l.clone(),
            url: format!("{BASE_URL}/{l}{canonical_path}"),
        })
        .collect();

    Metadata {
        title: full_title,
        description: config.description.clone(),
        canonical,
        alternates,
        no_index: config.no_index,
        og_type: config.og_type,
        locale: config.locale.clone().unwrap_or_else(|| "en".to_owned()),
        image,
        image_width: 1200,
        image_height: 630,
        image_alt: config.title.clone(),
        twitter_card: config.twitter_card,
    }
}

/// Escape a string for an HTML attribute value.
///
/// Attribute-position escaping, because every use below is inside `content="…"`.
/// `&` first, or the ampersands introduced by the later replacements get escaped
/// a second time.
fn escape_attr(s: &str, out: &mut String) {
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
}

fn meta_name(out: &mut String, name: &str, content: &str) {
    out.push_str("<meta name=\"");
    out.push_str(name);
    out.push_str("\" content=\"");
    escape_attr(content, out);
    out.push_str("\">\n");
}

fn meta_property(out: &mut String, property: &str, content: &str) {
    out.push_str("<meta property=\"");
    out.push_str(property);
    out.push_str("\" content=\"");
    escape_attr(content, out);
    out.push_str("\">\n");
}

impl Metadata {
    /// Render the `<title>`, `<meta>` and `<link>` elements for `<head>`.
    ///
    /// Every caller-supplied value is attribute-escaped. The `.ts` never had to
    /// do this because React escaped for it; a Rust host writing a string into
    /// `<head>` has no such help, so it happens here rather than being left as an
    /// exercise for whoever renders.
    #[must_use]
    pub fn to_head_html(&self) -> String {
        let mut out = String::new();

        out.push_str("<title>");
        escape_attr(&self.title, &mut out);
        out.push_str("</title>\n");

        if let Some(d) = &self.description {
            meta_name(&mut out, "description", d);
        }
        if self.no_index {
            meta_name(&mut out, "robots", "noindex, nofollow");
        }
        if let Some(c) = &self.canonical {
            out.push_str("<link rel=\"canonical\" href=\"");
            escape_attr(c, &mut out);
            out.push_str("\">\n");
        }
        for alt in &self.alternates {
            out.push_str("<link rel=\"alternate\" hreflang=\"");
            escape_attr(&alt.locale, &mut out);
            out.push_str("\" href=\"");
            escape_attr(&alt.url, &mut out);
            out.push_str("\">\n");
        }

        meta_property(&mut out, "og:title", &self.title);
        if let Some(d) = &self.description {
            meta_property(&mut out, "og:description", d);
        }
        if let Some(c) = &self.canonical {
            meta_property(&mut out, "og:url", c);
        }
        meta_property(&mut out, "og:site_name", SITE_NAME);
        meta_property(&mut out, "og:type", self.og_type.as_str());
        meta_property(&mut out, "og:locale", &self.locale);
        meta_property(&mut out, "og:image", &self.image);
        let mut buf = String::new();
        let _ = write!(buf, "{}", self.image_width);
        meta_property(&mut out, "og:image:width", &buf);
        buf.clear();
        let _ = write!(buf, "{}", self.image_height);
        meta_property(&mut out, "og:image:height", &buf);
        meta_property(&mut out, "og:image:alt", &self.image_alt);

        meta_name(&mut out, "twitter:card", self.twitter_card.as_str());
        meta_name(&mut out, "twitter:title", &self.title);
        if let Some(d) = &self.description {
            meta_name(&mut out, "twitter:description", d);
        }
        meta_name(&mut out, "twitter:image", &self.image);

        out
    }
}

// ─── Schema.org ─────────────────────────────────────────────────────────────

/// A JSON value, enough for Schema.org and no more.
///
/// Hand-rolled rather than `serde_json`, for the reason N8's crate states at
/// length: these components are compiled into every consumer, and JSON-LD is a
/// small, fully specified shape.
///
/// `Object` is a `Vec` of pairs, not a map, because Schema.org output is read by
/// people as often as machines and insertion order is worth keeping.
#[derive(Debug, Clone, PartialEq)]
pub enum Json {
    /// A string.
    Str(String),
    /// A number. JSON has one numeric type.
    Num(f64),
    /// A boolean.
    Bool(bool),
    /// An ordered list.
    Arr(Vec<Json>),
    /// An ordered set of key/value pairs.
    Object(Vec<(String, Json)>),
}

impl Json {
    /// Convenience for `Json::Str`.
    #[must_use]
    pub fn s(v: impl Into<String>) -> Self {
        Self::Str(v.into())
    }

    /// Build an object from pairs.
    #[must_use]
    pub fn obj<K: Into<String>>(pairs: impl IntoIterator<Item = (K, Self)>) -> Self {
        Self::Object(pairs.into_iter().map(|(k, v)| (k.into(), v)).collect())
    }

    fn write(&self, out: &mut String) {
        match self {
            Self::Str(s) => write_json_string(s, out),
            Self::Num(n) => {
                // JSON has no NaN or Infinity. Emitting one produces a document
                // no parser accepts, so they become null — the same choice
                // `JSON.stringify` makes, which keeps the two siblings agreeing.
                if n.is_finite() {
                    let _ = write!(out, "{n}");
                } else {
                    out.push_str("null");
                }
            }
            Self::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
            Self::Arr(items) => {
                out.push('[');
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    item.write(out);
                }
                out.push(']');
            }
            Self::Object(pairs) => {
                out.push('{');
                for (i, (k, v)) in pairs.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    write_json_string(k, out);
                    out.push(':');
                    v.write(out);
                }
                out.push('}');
            }
        }
    }
}

/// Write a JSON string literal, escaped so it is also inert inside `<script>`.
///
/// Beyond the escapes JSON requires, `<`, `>` and `&` become `\u003c`, `\u003e`
/// and `\u0026`. All three are valid JSON escapes, so a parser sees the original
/// characters — but the literal text `</script>` can no longer appear in the
/// output, which is what stops a caller-supplied string from closing the script
/// element that carries it. See the module docs.
fn write_json_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            '<' => out.push_str("\\u003c"),
            '>' => out.push_str("\\u003e"),
            '&' => out.push_str("\\u0026"),
            // U+2028 and U+2029 are legal in JSON strings and illegal in
            // JavaScript source. A JSON-LD block is parsed as JSON, but the same
            // string reaching a `<script>` of another type would break it.
            '\u{2028}' => out.push_str("\\u2028"),
            '\u{2029}' => out.push_str("\\u2029"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// One Schema.org node: an `@type` plus its properties.
#[derive(Debug, Clone, PartialEq)]
pub struct SchemaOrg {
    /// The `@type` value, e.g. `JobPosting`.
    pub ty: String,
    /// Everything else, in order.
    pub properties: Vec<(String, Json)>,
}

impl SchemaOrg {
    /// A node of the given type with no properties yet.
    #[must_use]
    pub fn new(ty: impl Into<String>) -> Self {
        Self {
            ty: ty.into(),
            properties: Vec::new(),
        }
    }

    /// Add a property, builder style.
    #[must_use]
    pub fn with(mut self, key: impl Into<String>, value: Json) -> Self {
        self.properties.push((key.into(), value));
        self
    }

    /// Add a property only when the option is `Some`, mirroring the `.ts`
    /// spread-if-present idiom.
    #[must_use]
    pub fn with_opt(self, key: impl Into<String>, value: Option<Json>) -> Self {
        match value {
            Some(v) => self.with(key, v),
            None => self,
        }
    }

    fn to_json(&self, with_context: bool) -> Json {
        let mut pairs: Vec<(String, Json)> = Vec::with_capacity(self.properties.len() + 2);
        if with_context {
            pairs.push(("@context".to_owned(), Json::s("https://schema.org")));
        }
        pairs.push(("@type".to_owned(), Json::s(self.ty.clone())));
        pairs.extend(self.properties.iter().cloned());
        Json::Object(pairs)
    }
}

/// Serialise one or more Schema.org nodes as a JSON-LD document.
///
/// One node yields that node with `@context`. Several yield a single `@context`
/// and an `@graph`.
///
/// # Divergence from the TypeScript
///
/// The `.ts` puts `@context` on the wrapper AND on every member of `@graph`. A
/// `@graph` inherits the enclosing context, so the repeats are redundant — this
/// emits it once, which is the canonical form. No consumer sees a different
/// graph; it is the same document with less in it.
#[must_use]
pub fn generate_schema_ld(schema: &[SchemaOrg]) -> String {
    let mut out = String::new();
    match schema {
        [] => {
            // The `.ts` cannot reach this: its parameter is one node or a
            // non-empty array in practice. An empty slice is expressible here,
            // and an empty JSON-LD block is the only honest answer — a `@graph`
            // of nothing would claim a structure that is not there.
            Json::Object(vec![("@context".to_owned(), Json::s("https://schema.org"))])
                .write(&mut out);
        }
        [only] => only.to_json(true).write(&mut out),
        many => {
            let graph = many.iter().map(|n| n.to_json(false)).collect::<Vec<_>>();
            Json::Object(vec![
                ("@context".to_owned(), Json::s("https://schema.org")),
                ("@graph".to_owned(), Json::Arr(graph)),
            ])
            .write(&mut out);
        }
    }
    out
}

/// A pay range on a [`job_posting`].
#[derive(Debug, Clone, PartialEq)]
pub struct Salary {
    /// Lower bound.
    pub min: f64,
    /// Upper bound.
    pub max: f64,
    /// ISO 4217 code.
    pub currency: String,
}

/// A `JobPosting` node.
#[must_use]
pub fn job_posting(
    title: &str,
    company: &str,
    location: &str,
    description: &str,
    date_posted: &str,
    salary: Option<&Salary>,
) -> SchemaOrg {
    SchemaOrg::new("JobPosting")
        .with("title", Json::s(title))
        .with(
            "hiringOrganization",
            Json::obj([
                ("@type", Json::s("Organization")),
                ("name", Json::s(company)),
            ]),
        )
        .with(
            "jobLocation",
            Json::obj([("@type", Json::s("Place")), ("address", Json::s(location))]),
        )
        .with("description", Json::s(description))
        .with("datePosted", Json::s(date_posted))
        .with_opt(
            "baseSalary",
            salary.map(|s| {
                Json::obj([
                    ("@type", Json::s("MonetaryAmount")),
                    ("currency", Json::s(s.currency.clone())),
                    (
                        "value",
                        Json::obj([
                            ("@type", Json::s("QuantitativeValue")),
                            ("minValue", Json::Num(s.min)),
                            ("maxValue", Json::Num(s.max)),
                            ("unitText", Json::s("MONTH")),
                        ]),
                    ),
                ])
            }),
        )
}

/// An `Article` node.
#[must_use]
pub fn article(title: &str, author: &str, date_published: &str, image: Option<&str>) -> SchemaOrg {
    SchemaOrg::new("Article")
        .with("headline", Json::s(title))
        .with(
            "author",
            Json::obj([("@type", Json::s("Person")), ("name", Json::s(author))]),
        )
        .with("datePublished", Json::s(date_published))
        .with_opt("image", image.map(Json::s))
}

/// An `Event` node.
#[must_use]
pub fn event(
    name: &str,
    start_date: &str,
    end_date: Option<&str>,
    location: &str,
    description: Option<&str>,
) -> SchemaOrg {
    SchemaOrg::new("Event")
        .with("name", Json::s(name))
        .with("startDate", Json::s(start_date))
        .with_opt("endDate", end_date.map(Json::s))
        .with(
            "location",
            Json::obj([("@type", Json::s("Place")), ("name", Json::s(location))]),
        )
        .with_opt("description", description.map(Json::s))
}

/// A `Product` node.
#[must_use]
pub fn product(
    name: &str,
    price: f64,
    currency: &str,
    image: Option<&str>,
    description: Option<&str>,
) -> SchemaOrg {
    SchemaOrg::new("Product")
        .with("name", Json::s(name))
        .with_opt("description", description.map(Json::s))
        .with_opt("image", image.map(Json::s))
        .with(
            "offers",
            Json::obj([
                ("@type", Json::s("Offer")),
                ("price", Json::Num(price)),
                ("priceCurrency", Json::s(currency)),
                ("availability", Json::s("https://schema.org/InStock")),
            ]),
        )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg(title: &str) -> SeoConfig {
        SeoConfig {
            title: title.to_owned(),
            ..SeoConfig::default()
        }
    }

    #[test]
    fn title_is_suffixed_and_alt_text_is_not() {
        let m = generate_metadata(&cfg("Jobs"));
        assert_eq!(m.title, "Jobs — Mukoko");
        assert_eq!(m.image_alt, "Jobs");
    }

    #[test]
    fn defaults_match_the_typescript() {
        let m = generate_metadata(&cfg("x"));
        assert_eq!(m.og_type, OgType::Website);
        assert_eq!(m.twitter_card, TwitterCard::SummaryLargeImage);
        assert_eq!(m.locale, "en");
        assert_eq!(m.image, DEFAULT_OG_IMAGE);
        assert!(!m.no_index);
        assert!(m.canonical.is_none());
    }

    #[test]
    fn empty_og_image_falls_back_like_the_ts_or_operator() {
        let m = generate_metadata(&SeoConfig {
            og_image: Some(String::new()),
            ..cfg("x")
        });
        assert_eq!(m.image, DEFAULT_OG_IMAGE);
    }

    #[test]
    fn canonical_and_alternates_are_absolute() {
        let m = generate_metadata(&SeoConfig {
            canonical_url: Some("/jobs/1".to_owned()),
            alternate_locales: vec!["sn".to_owned(), "nd".to_owned()],
            ..cfg("x")
        });
        assert_eq!(m.canonical.as_deref(), Some("https://mukoko.com/jobs/1"));
        assert_eq!(m.alternates[0].url, "https://mukoko.com/sn/jobs/1");
        assert_eq!(m.alternates[1].url, "https://mukoko.com/nd/jobs/1");
    }

    #[test]
    fn product_emits_its_true_og_type_once() {
        let m = generate_metadata(&SeoConfig {
            og_type: OgType::Product,
            ..cfg("Sofa")
        });
        let html = m.to_head_html();
        assert!(html.contains(r#"<meta property="og:type" content="product">"#));
        assert!(!html.contains(r#"content="website""#));
        assert_eq!(html.matches("og:type").count(), 1);
    }

    #[test]
    fn head_html_escapes_attribute_values() {
        let m = generate_metadata(&cfg(r#"Bolt " & <b>"#));
        let html = m.to_head_html();
        assert!(!html.contains("<b>"));
        assert!(html.contains("&lt;b&gt;"));
        assert!(html.contains("&quot;"));
        assert!(html.contains("&amp;"));
    }

    #[test]
    fn no_index_emits_robots() {
        let m = generate_metadata(&SeoConfig {
            no_index: true,
            ..cfg("x")
        });
        assert!(
            m.to_head_html()
                .contains(r#"name="robots" content="noindex, nofollow""#)
        );
    }

    #[test]
    fn single_node_carries_the_context() {
        let json = generate_schema_ld(&[article("T", "A", "2026-01-01", None)]);
        assert!(json.starts_with(r#"{"@context":"https://schema.org","@type":"Article""#));
        assert!(!json.contains("@graph"));
    }

    #[test]
    fn graph_carries_the_context_exactly_once() {
        let json = generate_schema_ld(&[
            article("T", "A", "2026-01-01", None),
            event("E", "2026-02-01", None, "Harare", None),
        ]);
        assert_eq!(
            json.matches("@context").count(),
            1,
            "the .ts repeats it per member"
        );
        assert!(json.contains("@graph"));
    }

    #[test]
    fn script_closing_sequence_cannot_survive_into_the_document() {
        // The defect this file fixes: a caller-supplied string ending the script
        // element that carries it.
        let json = generate_schema_ld(&[article(
            "Great deal</script><script>alert(1)</script>",
            "A",
            "2026-01-01",
            None,
        )]);
        assert!(!json.contains("</script>"));
        assert!(!json.contains('<'));
        assert!(json.contains("\\u003c/script\\u003e"));
    }

    #[test]
    fn optional_fields_are_omitted_not_nulled() {
        let json = generate_schema_ld(&[product("Sofa", 100.0, "USD", None, None)]);
        assert!(!json.contains("image"));
        assert!(!json.contains("description"));
        assert!(json.contains(r#""price":100"#));
    }

    #[test]
    fn salary_nests_a_quantitative_value() {
        let s = Salary {
            min: 500.0,
            max: 900.0,
            currency: "USD".to_owned(),
        };
        let json = generate_schema_ld(&[job_posting(
            "Dev",
            "Nyuchi",
            "Harare",
            "d",
            "2026-01-01",
            Some(&s),
        )]);
        assert!(json.contains(r#""@type":"MonetaryAmount""#));
        assert!(json.contains(r#""minValue":500"#));
        assert!(json.contains(r#""unitText":"MONTH""#));
    }

    #[test]
    fn non_finite_numbers_become_null_like_json_stringify() {
        let json = generate_schema_ld(&[product("x", f64::NAN, "USD", None, None)]);
        assert!(json.contains(r#""price":null"#));
    }

    #[test]
    fn empty_slice_yields_a_bare_context_not_an_empty_graph() {
        let json = generate_schema_ld(&[]);
        assert_eq!(json, r#"{"@context":"https://schema.org"}"#);
    }
}

