"use client"

import * as React from "react"
import { ThumbsUp, ThumbsDown } from "@/lib/icons"

import { cn } from "@/lib/utils"

type FeedbackValue = "positive" | "negative" | null

function AiFeedback({
  className,
  value,
  onFeedback,
  showTextInput = false,
  onTextFeedback,
  ...props
}: React.ComponentProps<"div"> & {
  value?: FeedbackValue
  onFeedback?: (value: FeedbackValue) => void
  showTextInput?: boolean
  onTextFeedback?: (text: string) => void
}) {
  const [text, setText] = React.useState("")

  const handleFeedback = (type: "positive" | "negative") => {
    onFeedback?.(value === type ? null : type)
  }

  return (
    <div
      data-slot="ai-feedback"
      data-portal="https://mzizi.dev/components/ai-feedback"
      className={cn("flex flex-col gap-2", className)}
      {...props}
    >
      <div className="flex items-center gap-1">
        <button
          onClick={() => handleFeedback("positive")}
          aria-label="Helpful"
          aria-pressed={value === "positive"}
          className={cn(
            "inline-flex size-8 items-center justify-center rounded-[var(--radius-lg,14px)] transition-colors",
            value === "positive"
              ? "bg-mineral-malachite/15 text-mineral-malachite"
              : "text-muted-foreground hover:bg-muted hover:text-foreground"
          )}
        >
          <ThumbsUp className="size-4" />
        </button>
        <button
          onClick={() => handleFeedback("negative")}
          aria-label="Not helpful"
          aria-pressed={value === "negative"}
          className={cn(
            "inline-flex size-8 items-center justify-center rounded-[var(--radius-lg,14px)] transition-colors",
            value === "negative"
