  /** Camera mode */
  mode?: CameraMode
  /** Whether recording is active */
  recording?: boolean
  /** Recording elapsed seconds */
  elapsed?: number
  /** Called when record button pressed */
  onCapture?: () => void
  /** Called when camera flip is pressed */
  onFlip?: () => void
