      </div>
      {(lastDeploy || version) && (
        <div className="mt-3 flex items-center gap-2 text-[10px] text-muted-foreground">
          {version && <span className="font-mono">v{version}</span>}
          {lastDeploy && <span>Deployed {lastDeploy}</span>}
        </div>
      )}
    </div>
  )
}

