"use client"

import * as React from "react"
import { Copy, Check } from "@/lib/icons"

import { cn } from "@/lib/utils"

interface DescriptionItem {
  term: string
  detail: React.ReactNode
  copyable?: boolean
}

function CopyableDetail({ detail }: { detail: React.ReactNode }) {
  const [copied, setCopied] = React.useState(false)

  function handleCopy() {
    const text = typeof detail === "string" ? detail : String(detail)
    navigator.clipboard.writeText(text)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <span className="inline-flex items-center gap-1.5">
      {detail}
      <button
        type="button"
        onClick={handleCopy}
        className="shrink-0 p-0.5 text-muted-foreground transition-colors hover:text-foreground"
        aria-label="Copy value"
      >
        {copied ? (
          <Check className="size-3 text-[var(--status-success,var(--color-malachite,#64FFDA))]" />
        ) : (
          <Copy className="size-3" />
        )}
      </button>
    </span>
  )
}

function DescriptionList({
  items,
  className,
  ...props
}: {
  items: DescriptionItem[]
} & React.ComponentProps<"dl">) {
  return (
