"use client"

import * as React from "react"
import { Plus, Trash2, Eye, EyeOff } from "@/lib/icons"

import { cn } from "@/lib/utils"

interface EnvVariable {
  key: string
  value: string
  secret?: boolean
}

function EnvEditor({
  variables,
  onChange,
  className,
  ...props
}: {
  variables: EnvVariable[]
  onChange: (variables: EnvVariable[]) => void
} & Omit<React.ComponentProps<"div">, "onChange">) {
  const [revealed, setRevealed] = React.useState<Set<number>>(new Set())

  function updateVariable(index: number, field: "key" | "value", val: string) {
    const next = variables.map((v, i) => (i === index ? { ...v, [field]: val } : v))
    onChange(next)
  }

  function removeVariable(index: number) {
    onChange(variables.filter((_, i) => i !== index))
    setRevealed((prev) => {
      const next = new Set<number>()
      prev.forEach((i) => {
        if (i < index) next.add(i)
        else if (i > index) next.add(i - 1)
      })
      return next
    })
  }

  function addVariable() {
    onChange([...variables, { key: "", value: "", secret: false }])
  }

  function toggleReveal(index: number) {
    setRevealed((prev) => {
      const next = new Set(prev)
      if (next.has(index)) {
        next.delete(index)
      } else {
        next.add(index)
      }
      return next
    })
  }

  return (
    <div
      data-slot="env-editor"
      data-portal="https://mzizi.dev/components/env-editor"
      className={cn("flex flex-col gap-2", className)}
      {...props}
    >
      {variables.map((variable, index) => (
        <div key={index} className="flex items-center gap-2">
          <input
            type="text"
            value={variable.key}
            onChange={(e) => updateVariable(index, "key", e.target.value)}
            placeholder="KEY"
            className="h-9 w-40 min-w-0 rounded-[var(--radius-lg,14px)] border border-input bg-input/30 px-3 font-mono text-sm transition-colors outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50"
          />
          <div className="relative flex-1">
            <input
              type={variable.secret && !revealed.has(index) ? "password" : "text"}
              value={variable.value}
              onChange={(e) => updateVariable(index, "value", e.target.value)}
              placeholder="value"
              className="h-9 w-full min-w-0 rounded-[var(--radius-lg,14px)] border border-input bg-input/30 px-3 pr-9 font-mono text-sm transition-colors outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50"
            />
            {variable.secret && (
              <button
                type="button"
                onClick={() => toggleReveal(index)}
                className="absolute top-1/2 right-2 -translate-y-1/2 p-0.5 text-muted-foreground hover:text-foreground"
                aria-label={revealed.has(index) ? "Hide value" : "Reveal value"}
              >
                {revealed.has(index) ? (
                  <EyeOff className="size-3.5" />
                ) : (
                  <Eye className="size-3.5" />
                )}
              </button>
            )}
          </div>
          <button
            type="button"
            onClick={() => removeVariable(index)}
            className="shrink-0 rounded-[var(--radius-md,12px)] p-1.5 text-muted-foreground transition-colors hover:text-destructive"
            aria-label={`Remove ${variable.key || "variable"}`}
          >
            <Trash2 className="size-4" />
          </button>
        </div>
      ))}
      <button
        type="button"
        onClick={addVariable}
        className="flex items-center gap-1.5 self-start rounded-[var(--radius-lg,14px)] px-3 py-1.5 text-sm font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
      >
        <Plus className="size-4" />
        Add variable
      </button>
    </div>
  )
}

export { EnvEditor, type EnvVariable }

