  imageUrl?: string
  rsvpStatus?: RsvpStatus
  attendeeCount?: number
  onRsvp?: (status: "going" | "maybe" | "declined") => void
}

function EventRsvpInline({
  eventTitle,
  date,
  venue,
  imageUrl,
  rsvpStatus,
  attendeeCount,
  onRsvp,
  className,
  ...props
