import * as React from "react"
import {
  FileText,
  FileImage,
  FileVideo,
  FileAudio,
  FileArchive,
  FileCode,
  FileSpreadsheet,
  File,
} from "@/lib/icons"

import { cn } from "@/lib/utils"

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`
}

function getFileIcon(type: string) {
  const t = type.toLowerCase()
  if (t.startsWith("image/") || /\.(png|jpg|jpeg|gif|webp|svg)$/i.test(t)) return FileImage
  if (t.startsWith("video/") || /\.(mp4|mov|avi|webm)$/i.test(t)) return FileVideo
  if (t.startsWith("audio/") || /\.(mp3|wav|ogg|flac)$/i.test(t)) return FileAudio
  if (/\.(zip|rar|7z|tar|gz)$/i.test(t) || t.includes("zip") || t.includes("archive"))
    return FileArchive
  if (
    /\.(js|ts|tsx|jsx|py|rb|go|rs|html|css|json|xml)$/i.test(t) ||
    t.includes("javascript") ||
    t.includes("json")
  )
    return FileCode
  if (/\.(csv|xls|xlsx)$/i.test(t) || t.includes("spreadsheet") || t.includes("csv"))
    return FileSpreadsheet
  if (/\.(pdf|doc|docx|txt|md)$/i.test(t) || t.includes("text") || t.includes("pdf"))
    return FileText
  return File
}

function FilePreview({
  className,
  name,
  size,
  type,
  thumbnail,
  ...props
}: React.ComponentProps<"div"> & {
  name: string
  size: number
  type: string
  thumbnail?: string
}) {
  const Icon = getFileIcon(type)

  return (
    <div
      data-slot="file-preview"
      data-portal="https://mzizi.dev/components/file-preview"
      className={cn(
        "flex items-center gap-3 rounded-[var(--radius-xl,17px)] bg-card px-4 py-3 ring-1 ring-foreground/10",
        className
      )}
      {...props}
    >
      {thumbnail ? (
        <img
          src={thumbnail}
          alt={name}
          className="size-10 shrink-0 rounded-[var(--radius-lg,14px)] object-cover"
        />
      ) : (
        <div className="flex size-10 shrink-0 items-center justify-center rounded-[var(--radius-lg,14px)] bg-muted">
          <Icon className="size-5 text-muted-foreground" />
        </div>
      )}
      <div className="min-w-0 flex-1">
        <p className="truncate text-sm font-medium text-foreground">{name}</p>
        <p className="text-xs text-muted-foreground">{formatFileSize(size)}</p>
      </div>
    </div>
  )
}

export { FilePreview }

n2-primitives/file-upload.tsx:
"use client"

import * as React from "react"
import { Upload, X, FileIcon } from "@/lib/icons"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

interface FileUploadProps {
  /** Accepted file types (e.g., "image/*", ".pdf,.doc") */
  accept?: string
  /** Maximum file size in bytes */
  maxSize?: number
  /** Allow multiple files */
  multiple?: boolean
  /** Called when files are selected or dropped */
  onFilesChange?: (files: File[]) => void
  /** Called when a file is removed */
  onFileRemove?: (file: File) => void
  /** Disable the upload zone */
  disabled?: boolean
  className?: string
}

function formatFileSize(bytes: number): string {
  if (bytes === 0) return "0 B"
  const k = 1024
  const sizes = ["B", "KB", "MB", "GB"]
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`
}

function FileUpload({
  accept,
  maxSize,
  multiple = false,
  onFilesChange,
  onFileRemove,
  disabled = false,
  className,
}: FileUploadProps) {
  const [files, setFiles] = React.useState<File[]>([])
  const [isDragging, setIsDragging] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)

  const validateFiles = (incoming: File[]): File[] => {
    setError(null)
    const valid: File[] = []
    for (const file of incoming) {
      if (maxSize && file.size > maxSize) {
        setError(`${file.name} exceeds ${formatFileSize(maxSize)} limit`)
        continue
      }
      valid.push(file)
    }
    return valid
  }

  const handleFiles = (incoming: File[]) => {
    const validated = validateFiles(incoming)
    if (validated.length === 0) return
    const next = multiple ? [...files, ...validated] : validated.slice(0, 1)
    setFiles(next)
    onFilesChange?.(next)
  }

  const handleRemove = (file: File) => {
    const next = files.filter((f) => f !== file)
    setFiles(next)
    onFileRemove?.(file)
    onFilesChange?.(next)
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    setIsDragging(false)
    if (disabled) return
    const dropped = Array.from(e.dataTransfer.files)
    handleFiles(dropped)
  }

  return (
    <div
      data-slot="file-upload"
      data-portal="https://mzizi.dev/components/file-upload"
      role="group"
      aria-label="File upload"
      className={cn("space-y-3", className)}
    >
      {/* Drop zone */}
      <div
        onDragOver={(e) => {
          e.preventDefault()
          if (!disabled) setIsDragging(true)
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={handleDrop}
        onClick={() => !disabled && inputRef.current?.click()}
        role="button"
        tabIndex={0}
        aria-label={isDragging ? "Drop files here" : "Click to upload or drag and drop"}
        className={cn(
          "flex cursor-pointer flex-col items-center gap-2 rounded-[var(--radius-xl,17px)] border-2 border-dashed p-8 text-center transition-colors",
          isDragging
            ? "border-primary bg-primary/5"
            : "border-border hover:border-primary/50 hover:bg-muted/30",
          disabled && "cursor-not-allowed opacity-50"
        )}
      >
        <div className="flex size-10 items-center justify-center rounded-[var(--radius-lg,14px)] bg-muted">
          <Upload className="size-5 text-muted-foreground" />
        </div>
        <div className="space-y-1">
          <p className="text-sm font-medium">
            {isDragging ? "Drop files here" : "Click to upload or drag and drop"}
          </p>
          <p className="text-xs text-muted-foreground">
            {accept ? `Accepted: ${accept}` : "Any file type"}
            {maxSize && ` · Max ${formatFileSize(maxSize)}`}
          </p>
        </div>
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          multiple={multiple}
          disabled={disabled}
          onChange={(e) => {
            const selected = Array.from(e.target.files ?? [])
            handleFiles(selected)
            e.target.value = ""
          }}
          className="hidden"
        />
      </div>

      {/* Error */}
      {error && <p className="text-xs text-destructive">{error}</p>}

