"use client"

import * as React from "react"
import { MinusIcon, PlusIcon } from "@/lib/icons"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

interface NumberInputProps {
  value?: number
  onChange?: (value: number) => void
  min?: number
  max?: number
  step?: number
  disabled?: boolean
  className?: string
}

function NumberInput({
  value = 0,
  onChange,
  min = -Infinity,
  max = Infinity,
  step = 1,
  disabled = false,
  className,
}: NumberInputProps) {
  function clamp(n: number) {
    return Math.min(max, Math.max(min, n))
  }

  function decrement() {
    onChange?.(clamp(value - step))
  }

  function increment() {
    onChange?.(clamp(value + step))
  }

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    const parsed = parseFloat(e.target.value)
    if (!Number.isNaN(parsed)) {
      onChange?.(clamp(parsed))
    }
  }

  return (
    <div
      data-slot="number-input"
      data-portal="https://mzizi.dev/components/number-input"
      className={cn(
        "inline-flex items-center rounded-full border border-input bg-input/30 transition-colors focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50",
        disabled && "pointer-events-none opacity-50",
        className
      )}
    >
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        disabled={disabled || value <= min}
        onClick={decrement}
        aria-label="Decrease"
        className="rounded-l-full rounded-r-none"
      >
        <MinusIcon />
      </Button>
      <input
        type="text"
        inputMode="numeric"
        value={value}
        onChange={handleChange}
        disabled={disabled}
        aria-label="Number value"
        className="h-8 w-14 border-x border-border bg-transparent text-center text-sm outline-none"
      />
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        disabled={disabled || value >= max}
        onClick={increment}
        aria-label="Increase"
        className="rounded-l-none rounded-r-full"
      >
        <PlusIcon />
      </Button>
    </div>
  )
}

export { NumberInput }
export type { NumberInputProps }

n2-primitives/observability.ts:
/**
 * Observability utilities for the Mzizi design system.
 *
 * Provides structured logging, performance timing, and error tracking
 * with the [mzizi] prefix for grep-ability across all services.
 *
 * Install via: npx shadcn@latest add https://mzizi.dev/api/v1/ui/observability
 */

type LogLevel = "debug" | "info" | "warn" | "error"

interface LogContext {
  /** Module or component name (e.g., "registry", "weather-chart") */
  module?: string
  /** Additional structured data */
  data?: Record<string, unknown>
  /** Error object if applicable */
  error?: Error
  /** Unique identifier for tracing (e.g., request ID, session ID) */
  traceId?: string
}

const LOG_METHODS: Record<LogLevel, (...args: unknown[]) => void> = {
  // eslint-disable-next-line no-console -- logger implementation
  debug: console.debug,
  // eslint-disable-next-line no-console -- logger implementation
  info: console.info,
  warn: console.warn,
  error: console.error,
}

function formatPrefix(level: LogLevel, module?: string): string {
  const tag = module ? `[mzizi:${module}]` : "[mzizi]"
  return `${tag} ${level.toUpperCase()}`
}

/**
 * Structured logger with [mzizi] prefix.
 *
 * @example
 * ```ts
 * import { log } from "@/lib/observability"
 *
 * log.info("Server started", { module: "api", data: { port: 11736 } })
 * log.error("Failed to fetch", { module: "weather", error: new Error("timeout") })
 * log.warn("Cache miss", { module: "registry", traceId: "req-123" })
 * ```
 */
export const log = {
  debug(message: string, ctx?: LogContext) {
    emit("debug", message, ctx)
  },
  info(message: string, ctx?: LogContext) {
    emit("info", message, ctx)
  },
  warn(message: string, ctx?: LogContext) {
    emit("warn", message, ctx)
  },
  error(message: string, ctx?: LogContext) {
    emit("error", message, ctx)
  },
}

function emit(level: LogLevel, message: string, ctx?: LogContext) {
  const prefix = formatPrefix(level, ctx?.module)
  const parts: unknown[] = [`${prefix} ${message}`]

  if (ctx?.traceId) {
    parts.push(`[trace:${ctx.traceId}]`)
  }
  if (ctx?.data) {
    parts.push(ctx.data)
  }
  if (ctx?.error) {
    parts.push(ctx.error)
  }

  LOG_METHODS[level](...parts)
}

/**
 * Measure execution time of a sync or async function.
 *
 * @example
 * ```ts
 * import { measure } from "@/lib/observability"
 *
 * const result = await measure("fetch-weather", async () => {
 *   return await fetch("/api/weather")
 * })
 *
 * // Logs: [mzizi] PERF fetch-weather completed in 142ms
 * ```
 */
export async function measure<T>(
  label: string,
  fn: () => T | Promise<T>,
  ctx?: LogContext
): Promise<T> {
  const start = performance.now()
  try {
    const result = await fn()
    const duration = Math.round(performance.now() - start)
    log.info(`${label} completed in ${duration}ms`, {
      ...ctx,
      module: ctx?.module ?? "perf",
      data: { ...ctx?.data, duration, label },
    })
    return result
  } catch (error) {
    const duration = Math.round(performance.now() - start)
    log.error(`${label} failed after ${duration}ms`, {
      ...ctx,
      module: ctx?.module ?? "perf",
      data: { ...ctx?.data, duration, label },
      error: error instanceof Error ? error : new Error(String(error)),
    })
    throw error
  }
}

/**
 * Track an error with structured context, without throwing.
 *
 * @example
 * ```ts
 * import { trackError } from "@/lib/observability"
 *
 * try {
 *   await riskyOperation()
 * } catch (error) {
 *   trackError(error, { module: "checkout", data: { userId: "123" } })
 * }
 * ```
 */
export function trackError(error: unknown, ctx?: LogContext) {
  const err = error instanceof Error ? error : new Error(String(error))
  log.error(err.message, { ...ctx, error: err })
}

/**
 * Create a scoped logger bound to a specific module.
 *
 * @example
 * ```ts
 * import { createLogger } from "@/lib/observability"
 *
 * const logger = createLogger("registry")
 * logger.info("Component served", { data: { name: "button" } })
 * // Logs: [mzizi:registry] INFO Component served { name: "button" }
 *
 * logger.error("File not found", { error: new Error("ENOENT") })
 * // Logs: [mzizi:registry] ERROR File not found Error: ENOENT
 * ```
 */
export function createLogger(module: string) {
  return {
    debug(message: string, ctx?: Omit<LogContext, "module">) {
      log.debug(message, { ...ctx, module })
    },
    info(message: string, ctx?: Omit<LogContext, "module">) {
      log.info(message, { ...ctx, module })
    },
    warn(message: string, ctx?: Omit<LogContext, "module">) {
      log.warn(message, { ...ctx, module })
    },
    error(message: string, ctx?: Omit<LogContext, "module">) {
      log.error(message, { ...ctx, module })
    },
  }
}

