  /** Called when user unpins */
  onUnpin?: () => void
  /** Can the current user unpin */
  canUnpin?: boolean
}

function PinnedMessage({
  content,
  pinnedBy,
  pinnedAt,
  onNavigate,
  onUnpin,
  canUnpin = false,
