  /** Icon rendered in the top-right corner */
  icon?: React.ComponentType<{ className?: string }>
  className?: string
}

function StatsCard({
  title,
  value,
  description,
  trend,
  trendValue,
  icon: Icon,
  className,
}: StatsCardProps) {
