          )
        )}
        {overflow > 0 && <span className={bubble}>+{overflow}</span>}
      </div>
      {label && (
        <span className="text-[13px] text-muted-foreground" aria-hidden>
          {summary}
        </span>
      )}
    </div>
  )
}

