                <Award className="size-5" style={{ color }} />
              )}
            </div>
            <span className="line-clamp-1 text-[10px] font-medium text-foreground">{b.name}</span>
            {b.rarity && !b.locked && (
              <span className="text-[8px] font-semibold tracking-wider uppercase" style={{ color }}>
                {b.rarity}
              </span>
            )}
          </div>
        )
      })}
    </div>
  )
