  /** Renders the skeleton branch this component already implements. */
  loading?: boolean
  label: string
  origin: string
  destination: string
  mode?: "bus" | "kombi" | "taxi" | "walk" | "mixed"
  estimatedDuration?: string
  nextDeparture?: string
  frequency?: string
  onStart?: () => void
  onClick?: () => void
  className?: string
