  revoked: { label: "Revoked", color: "var(--status-error, #FF5252)", icon: X },
  suspended: { label: "Suspended", color: "var(--status-error, #FF5252)", icon: AlertTriangle },
  pending: { label: "Pending", color: "var(--color-cobalt,#00B0FF)", icon: Clock },
