  const diffColors = {
    beginner: "var(--color-malachite,#64FFDA)",
    intermediate: "var(--color-cobalt,#00B0FF)",
    advanced: "var(--color-tanzanite,#B388FF)",
  }
  return (
    <div
      data-slot="nyuchi-lesson-card"
      style={animStyle}
      role="article"
