          </div>
          <div className="h-1.5 overflow-hidden rounded-full bg-muted">
            <div
              className="h-full rounded-full bg-[var(--color-cobalt,#00B0FF)] transition-all"
              style={{ width: `${Math.min(progress, 100)}%` }}
