n3-brand/nyuchi-verified-badge.tsx:
"use client"

// ── INFRASTRUCTURE HARNESS (auto-wired) ──
// Every brand component participates in observability, motion, a11y,
// and health monitoring via the harness. Zero manual config.

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Users, Phone, ShieldCheck, Award, Ban, Flower2 } from "@/lib/icons"
import { cn } from "@/lib/utils"

/* ═══════════════════════════════════════════════════════════════
   MUKOKO VERIFIED BADGE — Brand Identity Component

   Three-axis trust model (nyuchi_platform_db):

   AXIS 1 — STATUS (identity.person.mit_status)
     Platform lifecycle. Independent of verification.
     pre_verification | living | liveness_pending |
     suspended | presumed_ancestral | verified_ancestral

   AXIS 2 — VERIFICATION TIER (system.verification_tier)
     Identity ladder. How real are you?
     Level 0: Unverified     — no badge
     Level 1: Community      — Terracotta (var(--color-terracotta,#D4A574)) — +0.10
     Level 2: OTP            — Cobalt (var(--tier-otp,var(--color-cobalt,#00B0FF)))     — +0.10 (cumulative 0.20)
     Level 3: Government     — Gold (var(--tier-licensed,var(--color-gold,#FFD740)))       — +0.10 (cumulative 0.30)
     Level 4: Licensed       — Tanzanite (var(--tier-government,var(--color-tanzanite,#B388FF)))  — +0.20 (cumulative 0.50)

   AXIS 3 — TRUST SCORE (computed output)
     trust = sum(tier_increments up to current level) + status_modifier
     Suspended/ancestral = fixed at status modifier (trust frozen)

   The badge renders based on TIER (which mineral check you see)
   but respects STATUS (dimmed if suspended, memorial if ancestral).
   ═══════════════════════════════════════════════════════════════ */

/** Verification tier codes from system.verification_tier.tier_code */
type VerificationTier = "unverified" | "community" | "otp" | "government" | "licensed"

/** Platform status from identity.person.mit_status */
type PlatformStatus =
  | "pre_verification"
  | "living"
  | "liveness_pending"
  | "suspended"
  | "presumed_ancestral"
  | "verified_ancestral"

/** Full tier configuration mapping to system.verification_tier */
const TIER_CONFIG = {
  unverified: {
    level: 0,
    mineral: null,
    label: "Unverified",
    trustIncrement: 0.0,
    cumulativeTrust: 0.0,
    fg: "transparent",
    bg: "transparent",
    fgLight: "transparent",
    bgLight: "transparent",
    icon: null,
  },
  community: {
    level: 1,
    mineral: "Terracotta",
    label: "Community Verified",
    trustIncrement: 0.1,
    cumulativeTrust: 0.1,
    fg: "var(--color-terracotta,#D4A574)",
    bg: "rgba(212,165,116,0.15)",
    fgLight: "var(--color-terracotta-light,#8B4513)",
    bgLight: "rgba(139,69,19,0.12)",
    icon: Users,
  },
  otp: {
    level: 2,
    mineral: "Cobalt",
    label: "Contact Verified",
    trustIncrement: 0.1,
    cumulativeTrust: 0.2,
    fg: "var(--tier-otp,var(--color-cobalt,#00B0FF))",
    bg: "rgba(0,176,255,0.15)",
    fgLight: "var(--color-cobalt-light,#0047AB)",
    bgLight: "rgba(0,71,171,0.12)",
    icon: Phone,
  },
  government: {
    level: 3,
    mineral: "Gold",
    label: "Government Verified",
    trustIncrement: 0.1,
    cumulativeTrust: 0.3,
    fg: "var(--tier-licensed,var(--color-gold,#FFD740))",
    bg: "rgba(255,215,64,0.15)",
    fgLight: "var(--color-gold-light,#5D4037)",
    bgLight: "rgba(93,64,55,0.12)",
    icon: ShieldCheck,
  },
  licensed: {
    level: 4,
    mineral: "Tanzanite",
    label: "Licensed Professional",
    trustIncrement: 0.2,
    cumulativeTrust: 0.5,
    fg: "var(--tier-government,var(--color-tanzanite,#B388FF))",
    bg: "rgba(179,136,255,0.15)",
    fgLight: "var(--color-tanzanite-light,#4B0082)",
    bgLight: "rgba(75,0,130,0.12)",
    icon: Award,
  },
} as const

/** Status overlay configuration from system.platform_status_trust */
const STATUS_OVERLAY = {
  pre_verification: { modifier: 0.0, active: true, overlay: null },
  living: { modifier: 0.0, active: true, overlay: null },
  liveness_pending: { modifier: 0.0, active: true, overlay: null },
  suspended: { modifier: -0.05, active: false, overlay: "suspended" as const },
  presumed_ancestral: { modifier: 0.05, active: false, overlay: "ancestral" as const },
  verified_ancestral: { modifier: 0.05, active: false, overlay: "ancestral" as const },
} as const

const badgeSizeVariants = cva(
  "inline-flex shrink-0 items-center justify-center rounded-full transition-opacity",
  {
    variants: {
      size: {
        sm: "size-3.5" /* Inline with text — next to names */,
        md: "size-[18px]" /* Default — cards, headers */,
        lg: "size-6" /* Profile pages */,
        xl: "size-8" /* Verification detail views */,
      },
    },
    defaultVariants: { size: "md" },
  }
)

const iconSizeMap = { sm: 10, md: 12, lg: 16, xl: 20 } as const

interface NyuchiVerifiedBadgeProps extends VariantProps<typeof badgeSizeVariants> {
  /** Verification tier code (system.verification_tier.tier_code) */
  tier: VerificationTier
  /** Platform status (identity.person.mit_status). Affects badge appearance. */
  status?: PlatformStatus
  /** Show tooltip with tier name on hover */
  showTooltip?: boolean
  /** Render skeleton placeholder while verification status is loading */
  loading?: boolean
  className?: string
}

function NyuchiVerifiedBadge({
  tier,
  status = "living",
  size = "md",
  showTooltip = true,
  loading = false,
  className,
}: NyuchiVerifiedBadgeProps) {
  if (loading)
    return (
      <span
        data-slot="nyuchi-verified-badge"
        data-portal="https://mzizi.dev/components/nyuchi-verified-badge"
        data-loading
        className="inline-flex size-4 animate-pulse rounded-full bg-muted"
      />
    )

  const config = TIER_CONFIG[tier]
  const statusConfig = STATUS_OVERLAY[status]
  const iconSize = iconSizeMap[size || "md"]

  /* Level 0 = no badge */
  if (!config.icon || tier === "unverified") return null

  /* Suspended: show ban overlay instead of tier icon */
  if (statusConfig.overlay === "suspended") {
    return (
      <span
        data-slot="nyuchi-verified-badge"
        data-tier={tier}
        data-status="suspended"
        aria-label="Account Suspended"
        title={showTooltip ? "Account Suspended" : undefined}
        className={cn(badgeSizeVariants({ size }), "opacity-40", className)}
        style={{ backgroundColor: "rgba(107,107,102,0.15)" }}
      >
        <Ban
          width={iconSize}
          height={iconSize}
          strokeWidth={2.5}
          color="var(--status-neutral, #6B6B66)"
        />
      </span>
    )
  }

  /* Ancestral: show memorial flower with dimmed tier color */
  if (statusConfig.overlay === "ancestral") {
    return (
      <span
        data-slot="nyuchi-verified-badge"
        data-tier={tier}
        data-status={status}
        aria-label={`${config.label} — Memorial`}
        title={showTooltip ? `${config.label} — Memorial` : undefined}
        className={cn(badgeSizeVariants({ size }), "opacity-60", className)}
        style={{ backgroundColor: config.bg }}
      >
        <Flower2 width={iconSize} height={iconSize} strokeWidth={2} style={{ color: config.fg }} />
      </span>
    )
  }

  /* Active: show full tier badge */
  const Icon = config.icon
  return (
    <span
      data-slot="nyuchi-verified-badge"
      data-tier={tier}
      data-level={config.level}
      data-trust={config.cumulativeTrust}
      aria-label={config.label}
      title={showTooltip ? `${config.label} · Trust ${config.cumulativeTrust}` : undefined}
      className={cn(badgeSizeVariants({ size }), className)}
      style={{ backgroundColor: config.bg }}
    >
      <Icon width={iconSize} height={iconSize} strokeWidth={2.5} style={{ color: config.fg }} />
    </span>
  )
}

/* ── Utility: compute trust score on the client ──────────────── */
function computeTrustScore(tier: VerificationTier, status: PlatformStatus): number {
  const statusConfig = STATUS_OVERLAY[status]

  // Suspended/ancestral = fixed at modifier only
  if (!statusConfig.active) return statusConfig.modifier

  // Active = cumulative tier score + status modifier
  return TIER_CONFIG[tier].cumulativeTrust + statusConfig.modifier
}

export { NyuchiVerifiedBadge, computeTrustScore, TIER_CONFIG, STATUS_OVERLAY }
export type { NyuchiVerifiedBadgeProps, VerificationTier, PlatformStatus }

n4-safety/ai-safety.tsx:
/**
 * AI safety utilities for the Nyuchi ecosystem.
 *
 * Input validation, rate limiting, and prompt safety — ported from
 * mukoko-weather's production Python guards. Every Nyuchi app that
 * integrates Claude or Shamwari AI must use these utilities.
 *
 * Install via: npx shadcn@latest add https://mzizi.dev/api/v1/ui/ai-safety
 */

import sanitizeHtml from "sanitize-html"
import { createLogger } from "@/lib/observability"

const logger = createLogger("ai-safety")

// ---------------------------------------------------------------------------
// Input Validation
// ---------------------------------------------------------------------------

const SLUG_RE = /^[a-z0-9-]{1,80}$/

/**
 * Validate and sanitize a URL slug.
 *
 * @example
 * ```ts
 * validateSlug("harare-zw")    // { valid: true, sanitized: "harare-zw" }
 * validateSlug("Hello World")  // { valid: false, sanitized: "hello-world" }
 * validateSlug("")             // { valid: false, sanitized: "" }
 * ```
 */
export function validateSlug(input: string): { valid: boolean; sanitized: string } {
  const sanitized = input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9-]/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 80)

  return {
    valid: SLUG_RE.test(input),
    sanitized,
  }
}

/**
 * Validate that a prompt/message does not exceed the maximum length.
 *
 * @param input - The user's input string
 * @param maxLength - Maximum allowed length (default: 2000, from mukoko-weather)
 */
export function validatePromptLength(input: string, maxLength = 2000): boolean {
  return input.length <= maxLength
}

/**
 * Sanitize user input by removing control characters and trimming.
 *
 * @example
 * ```ts
 * sanitizeUserInput("  Hello\x00World\n  ")  // "Hello World"
 * ```
 */
export function sanitizeUserInput(input: string): string {
  return (
    input
      // Remove null bytes and other control chars (keep newlines/tabs)
      // eslint-disable-next-line no-control-regex
      .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, "")
      .trim()
  )
}

/**
 * Validate an array of items against a maximum count.
 * From mukoko-weather: activity arrays capped at 20 items.
 *
 * @example
 * ```ts
 * validateArrayLength(activities, 20)  // true if <= 20 items
 * ```
 */
export function validateArrayLength(arr: unknown[], maxItems = 20): boolean {
  return arr.length <= maxItems
}

/**
 * Truncate a message to the specified max length.
 * From mukoko-weather: chat history messages truncated to 2000 chars.
 */
export function truncateMessage(input: string, maxLength = 2000): string {
  if (input.length <= maxLength) return input
  return input.slice(0, maxLength)
}

/**
 * Validate items against an allowlist.
 * From mukoko-weather: tags validated against get_known_tags() database query.
 *
 * @example
 * ```ts
 * const knownTags = ["farming", "mining", "travel"]
 * validateAllowlist(["farming", "hacking"], knownTags)
 * // { valid: false, invalid: ["hacking"], filtered: ["farming"] }
 * ```
 */
export function validateAllowlist(
  items: string[],
  allowlist: string[]
): { valid: boolean; invalid: string[]; filtered: string[] } {
  const allowSet = new Set(allowlist)
  const filtered = items.filter((item) => allowSet.has(item))
  const invalid = items.filter((item) => !allowSet.has(item))

  return {
    valid: invalid.length === 0,
    invalid,
    filtered,
  }
}

// ---------------------------------------------------------------------------
// Prompt Injection Detection
// ---------------------------------------------------------------------------

const INJECTION_PATTERNS = [
  // System prompt override attempts
  /ignore\s+(all\s+)?(previous|prior|above)\s+(instructions|prompts)/i,
  /you\s+are\s+now\s+(a|an)\s+/i,
  /system\s*:\s*/i,
  /\[\s*system\s*\]/i,
  /new\s+instructions?\s*:/i,
  // Role confusion
  /pretend\s+(to\s+be|you('re| are))/i,
  /act\s+as\s+(if\s+you|a|an)/i,
  /forget\s+(everything|all|your)/i,
  // Data exfiltration
  /reveal\s+(your|the)\s+(system|initial|original)\s+prompt/i,
  /what\s+(are|is)\s+your\s+(instructions|system\s+prompt)/i,
  /repeat\s+(the\s+)?(text|words)\s+above/i,
  // Delimiter injection
  /```\s*system/i,
  /<\/?system>/i,
]

/**
 * Detect potential prompt injection in user input.
 *
 * This is a heuristic check — not a guarantee. Use as one layer in a
 * defense-in-depth strategy alongside input length limits, rate limiting,
 * and system prompt guardrails.
 *
 * @example
 * ```ts
 * import { detectPromptInjection } from "@/lib/ai-safety"
 *
 * const result = detectPromptInjection("Ignore all previous instructions")
 * // { safe: false, flags: ["system_override"] }
 *
 * const clean = detectPromptInjection("What's the weather in Harare?")
 * // { safe: true, flags: [] }
 * ```
 */
export function detectPromptInjection(input: string): {
  safe: boolean
  flags: string[]
} {
  const flags: string[] = []

  for (const pattern of INJECTION_PATTERNS) {
    if (pattern.test(input)) {
      // Categorize the flag
      const source = pattern.source.toLowerCase()
      if (source.includes("ignore") || source.includes("forget") || source.includes("new")) {
        flags.push("system_override")
      } else if (
        source.includes("pretend") ||
        source.includes("act as") ||
        source.includes("you are now")
      ) {
        flags.push("role_confusion")
      } else if (
        source.includes("reveal") ||
        source.includes("repeat") ||
        source.includes("what")
      ) {
        flags.push("data_exfiltration")
      } else if (source.includes("system")) {
        flags.push("delimiter_injection")
      }
    }
  }

  // Deduplicate flags
  const uniqueFlags = [...new Set(flags)]

  if (uniqueFlags.length > 0) {
    logger.warn("Prompt injection detected", {
      data: { flags: uniqueFlags, inputLength: input.length },
    })
  }

  return {
    safe: uniqueFlags.length === 0,
    flags: uniqueFlags,
  }
}

// ---------------------------------------------------------------------------
// Rate Limiting
// ---------------------------------------------------------------------------

interface RateLimitEntry {
  timestamps: number[]
}

export interface RateLimiterConfig {
  /** Maximum number of requests allowed in the window */
  maxRequests: number
  /** Time window in milliseconds */
  windowMs: number
}

/**
 * In-memory sliding window rate limiter.
 *
 * From mukoko-weather production limits:
 * - /api/py/chat: 20 req/hour
 * - /api/py/ai/followup: 30 req/hour
 * - /api/py/explore/search: 15 req/hour
 * - /api/py/reports (submit): 5 req/hour
 *
 * @example
 * ```ts
 * import { RateLimiter } from "@/lib/ai-safety"
 *
 * const limiter = new RateLimiter({ maxRequests: 20, windowMs: 3600_000 })
 *
 * // In API route handler:
 * const ip = request.headers.get("x-forwarded-for") ?? "unknown"
 * const { allowed, remaining, resetMs } = limiter.consume(ip)
 *
 * if (!allowed) {
 *   return Response.json(
 *     { error: "Rate limit exceeded" },
 *     { status: 429, headers: { "Retry-After": String(Math.ceil(resetMs / 1000)) } }
 *   )
 * }
 * ```
 */
export class RateLimiter {
  private entries = new Map<string, RateLimitEntry>()
  private readonly config: RateLimiterConfig
  private cleanupTimer: ReturnType<typeof setInterval> | null = null

  constructor(config: RateLimiterConfig) {
    this.config = config
    // Cleanup stale entries every 5 minutes
    if (typeof setInterval !== "undefined") {
      this.cleanupTimer = setInterval(() => this.cleanup(), 300_000)
    }
  }

  /** Check if a key is within rate limits without consuming a request */
  isAllowed(key: string): boolean {
    const entry = this.entries.get(key)
    if (!entry) return true

    const now = Date.now()
    const cutoff = now - this.config.windowMs
    const recentCount = entry.timestamps.filter((t) => t > cutoff).length
    return recentCount < this.config.maxRequests
  }

  /** Consume a request for the given key */
  consume(key: string): { allowed: boolean; remaining: number; resetMs: number } {
    const now = Date.now()
    const cutoff = now - this.config.windowMs

    let entry = this.entries.get(key)
    if (!entry) {
      entry = { timestamps: [] }
      this.entries.set(key, entry)
    }

    // Prune old timestamps
    entry.timestamps = entry.timestamps.filter((t) => t > cutoff)

    if (entry.timestamps.length >= this.config.maxRequests) {
      const oldestInWindow = entry.timestamps[0]
      const resetMs = oldestInWindow + this.config.windowMs - now
      return { allowed: false, remaining: 0, resetMs: Math.max(0, resetMs) }
    }

    entry.timestamps.push(now)
    const remaining = this.config.maxRequests - entry.timestamps.length
    const resetMs =
      entry.timestamps.length > 0
        ? entry.timestamps[0] + this.config.windowMs - now
        : this.config.windowMs

    return { allowed: true, remaining, resetMs: Math.max(0, resetMs) }
  }

  /** Remove stale entries to prevent memory leaks */
  private cleanup(): void {
    const cutoff = Date.now() - this.config.windowMs
    for (const [key, entry] of this.entries) {
      entry.timestamps = entry.timestamps.filter((t) => t > cutoff)
      if (entry.timestamps.length === 0) {
        this.entries.delete(key)
      }
    }
  }

  /** Dispose of the cleanup timer */
  dispose(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer)
      this.cleanupTimer = null
    }
  }
}

