  onCancel?: () => void
  onSubmit?: () => void
  submitLabel?: string
  submitting?: boolean
  /** Step indicator for multi-step flows */
  currentStep?: number
  totalSteps?: number
  /** Cover/theme picker area */
  coverSlot?: React.ReactNode
  /** Form sections */
  children: React.ReactNode
  className?: string
}

export function NyuchiCreatePage({
  title,
  onCancel,
  onSubmit,
  submitLabel = "Publish",
  submitting = false,
  currentStep,
  totalSteps,
  coverSlot,
  children,
  className,
}: NyuchiCreatePageProps) {
  return (
    <div
      data-slot="nyuchi-create-page"
