"use client"

// ── INFRASTRUCTURE HARNESS (auto-wired) ──────────────────
import { useNyuchiHarness } from "@/lib/harness"

import * as React from "react"
import {
  CloudSunIcon,
  NewspaperIcon,
  CalendarIcon,
  LayoutGridIcon,
  GlobeIcon,
  type LucideIcon,
} from "@/lib/icons"
import { cn } from "@/lib/utils"
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover"
import { Button } from "@/components/ui/button"

/* ═══════════════════════════════════════════════════════════════
   APP SWITCHER — Brand Shell Component (Enterprise)

   The ecosystem navigation hub. Lets users switch between
   ecosystem products (nhimbe, Bush Trade, Shamwari, etc.)

   ✅ L1 TOKENS — Active state uses brand accent tokens
   ✅ L2 MOTION — Grid items stagger on popover open
   ✅ L3 A11Y — Focus ring tokens, ARIA labels, 48px targets
   ✅ L4 OBSERVABILITY — useNyuchiHarness, scoped logging
   ✅ L5 RESILIENCE — Guards against empty app list
   ✅ L7 PLATFORM — data-slot for CSS targeting
   ═══════════════════════════════════════════════════════════════ */

interface AppItem {
  name: string
  icon?: LucideIcon
  href: string
  active?: boolean
  /** Mineral accent color for this app */
  mineral?: "malachite" | "cobalt" | "gold" | "tanzanite" | "terracotta"
}

interface AppSwitcherProps {
  apps?: AppItem[]
  currentApp?: string
  className?: string
}

const DEFAULT_APPS: AppItem[] = [
  { name: "mukoko", icon: LayoutGridIcon, href: "https://mukoko.com", mineral: "malachite" },
  { name: "weather", icon: CloudSunIcon, href: "https://weather.mukoko.com", mineral: "cobalt" },
  { name: "news", icon: NewspaperIcon, href: "https://news.mukoko.com", mineral: "tanzanite" },
  { name: "nhimbe", icon: CalendarIcon, href: "https://events.mukoko.com", mineral: "malachite" },
  { name: "registry", icon: GlobeIcon, href: "https://mzizi.dev", mineral: "gold" },
]

function AppSwitcher({ apps = DEFAULT_APPS, currentApp, className }: AppSwitcherProps) {
  // ── L4: HARNESS — Observability + motion + a11y ──
  const { motion, LiveRegion } = useNyuchiHarness("app-switcher")

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          data-slot="app-switcher"
          data-portal="https://mzizi.dev/components/app-switcher"
          variant="ghost"
          size="icon"
          aria-label="Switch between ecosystem apps"
          className={cn(
            /* L3: A11Y — Min touch target + focus ring tokens */
            "min-h-[48px] min-w-[44px]",
            "focus-visible:outline-[length:var(--focusRing-width,2px)]",
            "focus-visible:outline-[var(--color-primary)]",
            "focus-visible:outline-offset-[var(--focusRing-offset,2px)]",
            className
          )}
        >
          <LayoutGridIcon />
        </Button>
      </PopoverTrigger>

      <PopoverContent className="w-56 rounded-[var(--radius-card,14px)] p-2" align="end">
        {LiveRegion}

        <div className="mb-2 px-2 text-xs font-medium text-muted-foreground">Mukoko Ecosystem</div>

        <div className="grid grid-cols-3 gap-1" role="menu" aria-label="ecosystem apps">
          {/* L5: RESILIENCE — Guard against empty/undefined apps */}
          {(apps ?? []).map((app, index) => {
            const Icon = app.icon ?? GlobeIcon
            const isCurrent = app.name === currentApp

            // ── L2: MOTION — Stagger animation per grid item ──
            const itemStyle = motion.prefersReduced
              ? {}
              : {
                  animation: `nyuchi-fade-slide-up ${motion.enterDuration}ms ${motion.enterEasing} both`,
                  animationDelay: `${motion.staggerDelay(index)}ms`,
                }

            return (
              <a
                key={app.name}
                href={app.href}
                role="menuitem"
                aria-current={isCurrent ? "true" : undefined}
                className={cn(
                  "flex flex-col items-center gap-1.5 p-2.5 text-xs transition-colors",
                  /* L1: TOKENS — Radius + hover using brand tokens */
                  "rounded-[var(--radius-inner,7px)]",
                  "hover:bg-muted",
                  isCurrent &&
                    "bg-[var(--brand-accent,var(--color-primary,#00B0FF))]/10 font-medium",
                  /* L3: A11Y — Min touch target + focus ring */
                  "min-h-[48px]",
                  "focus-visible:outline-[length:var(--focusRing-width,2px)]",
                  "focus-visible:outline-[var(--color-primary)]",
                  "focus-visible:outline-offset-[var(--focusRing-offset,2px)]"
                )}
                style={itemStyle}
              >
                <Icon
                  className="size-5"
                  style={{
                    /* L1: TOKENS — Active icon uses mineral accent */
                    color: isCurrent ? `var(--color-${app.mineral || "malachite"})` : undefined,
                  }}
                />
                <span className="truncate">{app.name}</span>
              </a>
            )
          })}
        </div>
      </PopoverContent>
    </Popover>
  )
}

export { AppSwitcher }
export type { AppSwitcherProps, AppItem }

n7-shell/nyuchi-bottom-nav.rs:
//! NYUCHI BOTTOM NAV — N7 shell, Dioxus.
//!
//! The Rust sibling of `nyuchi-bottom-nav.tsx`: 5-item bottom navigation with an optional
//! center FAB, sharing its contract — same `data-slot`, same active-state detection.

use dioxus::prelude::*;

/// Bottom-nav item. `is_fab` marks the raised center action button.
#[derive(Clone, Debug, PartialEq)]
pub struct BottomNavItem {
    /// Unique identifier.
    pub id: String,
    /// Display label.
    pub label: String,
    /// Route path.
    pub href: String,
    /// Whether this item is the center FAB rather than a link.
    pub is_fab: bool,
}

/// Mirrors the .tsx `isActive`: an explicit `active_id` wins; otherwise `/` matches only
/// exactly, and any other href matches itself or any of its sub-paths.
pub fn is_active(item: &BottomNavItem, active_id: Option<&str>, pathname: &str) -> bool {
    if let Some(id) = active_id {
        return id == item.id;
    }
    if item.href == "/" {
        return pathname == "/";
    }
    pathname == item.href || pathname.starts_with(&format!("{}/", item.href))
}

const FAB: &str = "flex size-[52px] -translate-y-6 items-center justify-center rounded-full \
     bg-[var(--brand-accent,var(--color-primary,#00B0FF))] \
     shadow-[0_4px_20px_var(--brand-accent-glow,rgba(100,255,218,0.3))] \
     transition-transform active:scale-95";

const NAV_ITEM: &str = "relative flex min-w-[56px] flex-col items-center gap-[3px] py-1 \
     text-[10px] font-medium transition-colors";

/// Props for [`NyuchiBottomNav`].
#[derive(Props, Clone, PartialEq)]
pub struct NyuchiBottomNavProps {
    /// The nav items to render, including at most one FAB.
    pub items: Vec<BottomNavItem>,
    /// Override active detection (useful for client-side routing).
    pub active_id: Option<String>,
    /// The current route, used for active detection when `active_id` is absent.
    pub pathname: String,
    /// Fired when the center FAB is pressed.
    #[props(default)]
    pub on_fab_click: EventHandler<()>,
}

/// Fixed bottom navigation bar with an optional raised center FAB.
#[component]
pub fn NyuchiBottomNav(props: NyuchiBottomNavProps) -> Element {
    rsx! {
        nav {
            "data-slot": "nyuchi-bottom-nav",
            "data-portal": "https://mzizi.dev/components/nyuchi-bottom-nav",
            class: "fixed inset-x-0 bottom-0 z-50 flex h-20 items-center justify-around \
                     border-t border-border bg-card/90 backdrop-blur-xl \
                     pb-[env(safe-area-inset-bottom)] md:hidden",
            for item in props.items.iter() {
                if item.is_fab {
                    button {
                        key: "{item.id}",
                        "aria-label": "{item.label}",
                        class: "{FAB}",
                        onclick: move |_| props.on_fab_click.call(()),
                        "+"
                    }
                } else {
                    a {
                        key: "{item.id}",
                        href: "{item.href}",
                        class: "{NAV_ITEM}",
                        if is_active(item, props.active_id.as_deref(), &props.pathname) {
                            span { class: "absolute -top-[9px] h-[2.5px] w-7 rounded-full bg-[var(--brand-accent,var(--color-primary,#00B0FF))]" }
                        }
                        span { "{item.label}" }
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn item(id: &str, href: &str) -> BottomNavItem {
        BottomNavItem {
            id: id.into(),
            label: id.into(),
            href: href.into(),
            is_fab: false,
        }
    }

    #[test]
    fn root_href_matches_only_exactly() {
        let home = item("home", "/");
        assert!(is_active(&home, None, "/"));
        assert!(!is_active(&home, None, "/feed"));
    }

    #[test]
    fn non_root_href_matches_itself_and_sub_paths() {
        let feed = item("feed", "/feed");
        assert!(is_active(&feed, None, "/feed"));
        assert!(is_active(&feed, None, "/feed/123"));
        assert!(!is_active(&feed, None, "/feeds"));
    }

    #[test]
    fn explicit_active_id_overrides_pathname() {
        let feed = item("feed", "/feed");
        assert!(is_active(&feed, Some("feed"), "/somewhere-else"));
        assert!(!is_active(&feed, Some("other"), "/feed"));
    }
}

