"use client"

// ── INFRASTRUCTURE HARNESS (auto-wired) ──
// Every brand component participates in observability, motion, a11y,
// and health monitoring via the harness. Zero manual config.

import * as React from "react"
import { usePathname } from "next/navigation"
import { cn } from "@/lib/utils"
import { Plus } from "@/lib/icons"

/* ═══════════════════════════════════════════════════════════════
   NYUCHI BOTTOM NAV — Brand Shell Component

   5-item bottom navigation with an optional center FAB.
   The center FAB is raised above the bar with a malachite
   background and glow shadow — this is the universal "create"
   entry point across all ecosystem apps.

   Brand identity markers:
   - Active item has top accent bar (2.5px malachite line)
   - 10px labels, Noto Sans
   - FAB rises 24px above the bar with accent glow
   - Blur background with border-top
   ═══════════════════════════════════════════════════════════════ */

export interface BottomNavItem {
  /** Unique identifier */
  id: string
  /** Display label */
  label: string
  /** Route path */
  href: string
  /** Default icon */
  icon: React.ComponentType<{ className?: string }>
  /** Active state icon (optional, falls back to icon) */
  activeIcon?: React.ComponentType<{ className?: string }>
  /** Whether this item is the center FAB */
  isFab?: boolean
  /** FAB click handler (overrides href for FAB items) */
  onFabClick?: () => void
}

interface NyuchiBottomNavProps {
  items: BottomNavItem[]
  /** Override active detection (useful for client-side routing) */
  activeId?: string
  className?: string
}

export function NyuchiBottomNav({ items, activeId, className }: NyuchiBottomNavProps) {
  const pathname = usePathname()

  function isActive(item: BottomNavItem): boolean {
    if (activeId) return activeId === item.id
    if (item.href === "/") return pathname === "/"
    return pathname === item.href || pathname.startsWith(item.href + "/")
  }

  return (
    <nav
      data-slot="nyuchi-bottom-nav"
      data-portal="https://mzizi.dev/components/nyuchi-bottom-nav"
      className={cn(
        "fixed inset-x-0 bottom-0 z-50 flex h-20 items-center justify-around",
        "border-t border-border bg-card/90 backdrop-blur-xl",
        "pb-[env(safe-area-inset-bottom)] md:hidden [&_a]:focus-visible:outline-2 [&_a]:focus-visible:outline-offset-2 [&_a]:focus-visible:outline-primary [&_button]:focus-visible:outline-2 [&_button]:focus-visible:outline-offset-2 [&_button]:focus-visible:outline-primary",
        className
      )}
    >
      {items.map((item) => {
        const active = isActive(item)

        /* ── Center FAB ─────────────────────────────────────── */
        if (item.isFab) {
          return (
            <button
              key={item.id}
              onClick={item.onFabClick}
              aria-label={item.label}
              className={cn(
                "flex size-[52px] -translate-y-6 items-center justify-center rounded-full",
                "bg-[var(--brand-accent,var(--color-primary,#00B0FF))] shadow-[0_4px_20px_var(--brand-accent-glow,rgba(100,255,218,0.3))]",
                "transition-transform active:scale-95"
              )}
            >
              <Plus className="size-[26px] text-background" strokeWidth={2.5} />
            </button>
          )
        }

        /* ── Standard nav item ──────────────────────────────── */
        const Icon = active && item.activeIcon ? item.activeIcon : item.icon
        return (
          <a
            key={item.id}
            href={item.href}
            className={cn(
              "relative flex min-w-[56px] flex-col items-center gap-[3px] py-1",
              "text-[10px] font-medium transition-colors",
              active
                ? "text-[var(--brand-accent,var(--color-primary,#00B0FF))]"
                : "text-muted-foreground"
            )}
          >
            {/* Active top accent bar — brand identity marker */}
            {active && (
              <span className="absolute -top-[9px] h-[2.5px] w-7 rounded-full bg-[var(--brand-accent,var(--color-primary,#00B0FF))]" />
            )}
            <Icon className={cn("size-[21px]", active ? "stroke-[2.2]" : "stroke-[1.8]")} />
            <span>{item.label}</span>
          </a>
        )
      })}
    </nav>
  )
}

n7-shell/nyuchi-command-palette.rs:
//! NYUCHI COMMAND PALETTE — N7 shell, Dioxus.
//!
//! The Rust sibling of `nyuchi-command-palette.tsx`: global search + actions, Cmd+K / Ctrl+K,
//! sharing its contract — same `data-slot`, same node-mineral colour map, same grouping.

use dioxus::prelude::*;

/// A single result/action row. Selection is dispatched by `id` through
/// `NyuchiCommandPaletteProps::on_select` rather than a per-item closure,
/// so the item list stays plain data (Clone/PartialEq, easy to test).
#[derive(Clone, Debug, PartialEq)]
pub struct CommandItem {
    /// Unique identifier, passed back through `on_select`.
    pub id: String,
    /// Display label.
    pub label: String,
    /// Optional secondary text shown under the label.
    pub description: Option<String>,
    /// Result group; items with no category fall under "Results".
    pub category: Option<String>,
    /// Optional keyboard shortcut hint, shown when `node` is absent.
    pub shortcut: Option<String>,
    /// Architecture node (1-12) — renders as a mineral-coloured N-chip.
    pub node: Option<u8>,
}

/// Node -> mineral Tailwind class. Static strings only (never constructed), per the
/// design-system styling rule — Tailwind's content scanner needs the literal class.
pub fn node_mineral_class(node: u8) -> &'static str {
    match node {
        1 => "text-terracotta",
        2 => "text-cobalt",
        3 => "text-tanzanite",
        4 => "text-gold",
        5 => "text-malachite",
        6 => "text-cobalt",
        7 => "text-gold",
        8 => "text-sodalite",
        9 => "text-copper",
        10 => "text-sodalite",
        _ => "text-muted-foreground",
    }
}

/// Groups items by category, first-seen order — matching the .tsx's
/// `acc[cat] ||= []` reduce, whose insertion order a `BTreeMap` would have
/// silently re-sorted alphabetically and changed the on-screen order.
pub fn group_by_category(items: &[CommandItem]) -> Vec<(String, Vec<CommandItem>)> {
    let mut groups: Vec<(String, Vec<CommandItem>)> = Vec::new();
    for item in items {
        let cat = item
            .category
            .clone()
            .unwrap_or_else(|| "Results".to_string());
        match groups.iter_mut().find(|(c, _)| *c == cat) {
            Some((_, list)) => list.push(item.clone()),
            None => groups.push((cat, vec![item.clone()])),
        }
    }
    groups
}

/// Cmd+K / Ctrl+K toggles the palette open or closed.
pub fn should_toggle(key: &str, meta_or_ctrl: bool) -> bool {
    meta_or_ctrl && key == "k"
}

/// Escape closes the palette only while it is open.
pub fn should_close_on_escape(key: &str, open: bool) -> bool {
    open && key == "Escape"
}

/// Props for [`NyuchiCommandPalette`].
#[derive(Props, Clone, PartialEq)]
pub struct NyuchiCommandPaletteProps {
    /// Whether the palette is currently shown.
    pub open: bool,
    /// Search results for the current query.
    pub items: Vec<CommandItem>,
    /// Shown instead of `items` while the query is empty.
    pub recent_items: Vec<CommandItem>,
    /// Placeholder text for the search input.
    #[props(default = "Search or type a command...".to_string())]
    pub placeholder: String,
    /// The current search query, controlled by the host.
    pub query: String,
    /// Whether a search is in flight.
    pub loading: bool,
    /// Fired as the query text changes.
    #[props(default)]
    pub on_query_change: EventHandler<String>,
    /// Fired with an item's `id` when it is chosen.
    #[props(default)]
    pub on_select: EventHandler<String>,
    /// Fired to open or close the palette (backdrop click, selection, Escape).
    #[props(default)]
    pub on_open_change: EventHandler<bool>,
}

/// Global search / command dialog, Cmd+K-style.
#[component]
pub fn NyuchiCommandPalette(props: NyuchiCommandPaletteProps) -> Element {
    if !props.open {
        return rsx! {};
    }
    let grouped = group_by_category(&props.items);

    rsx! {
        div {
            class: "fixed inset-0 z-50 bg-black/50",
            "aria-hidden": "true",
            onclick: move |_| props.on_open_change.call(false),
        }
        div {
            "data-slot": "nyuchi-command-palette",
            "data-portal": "https://mzizi.dev/components/nyuchi-command-palette",
            role: "dialog",
            "aria-label": "Command palette",
            "aria-modal": "true",
            class: "fixed inset-x-4 top-[15%] z-50 mx-auto max-w-lg overflow-hidden rounded-xl border border-border bg-card shadow-2xl",

            div { class: "flex items-center border-b border-border px-4",
                input {
                    value: "{props.query}",
                    placeholder: "{props.placeholder}",
                    "aria-label": "Search commands",
                    class: "flex-1 bg-transparent px-3 py-4 text-sm outline-none placeholder:text-muted-foreground",
                    oninput: move |e| props.on_query_change.call(e.value()),
                }
            }

            div { class: "max-h-[60vh] overflow-y-auto p-2", role: "listbox",
                if props.query.is_empty() && !props.recent_items.is_empty() {
                    div {
                        p { class: "px-2 py-1.5 text-xs font-medium text-muted-foreground", "Recent" }
                        for item in props.recent_items.iter() {
                            button {
                                key: "{item.id}",
                                role: "option",
                                class: "flex min-h-[48px] w-full items-center gap-3 rounded-sm px-3 py-2 text-left text-sm transition-colors hover:bg-muted focus-visible:bg-muted focus-visible:outline-none",
                                onclick: {
                                    let id = item.id.clone();
                                    move |_| { props.on_select.call(id.clone()); props.on_open_change.call(false); }
                                },
                                "{item.label}"
                            }
                        }
                    }
                }
                for (cat, cat_items) in grouped.iter() {
                    div {
                        key: "{cat}",
                        p { class: "px-2 py-1.5 text-xs font-medium text-muted-foreground", "{cat}" }
                        for item in cat_items.iter() {
                            button {
                                key: "{item.id}",
                                role: "option",
                                class: "flex min-h-[48px] w-full items-center justify-between gap-3 rounded-sm px-3 py-2 text-left text-sm transition-colors hover:bg-muted focus-visible:bg-muted focus-visible:outline-none",
                                onclick: {
                                    let id = item.id.clone();
                                    move |_| { props.on_select.call(id.clone()); props.on_open_change.call(false); }
                                },
                                "{item.label}"
                            }
                        }
                    }
                }
                if !props.query.is_empty() && props.items.is_empty() && !props.loading {
                    p { class: "py-8 text-center text-sm text-muted-foreground", "No results found" }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn item(id: &str, category: Option<&str>) -> CommandItem {
        CommandItem {
            id: id.into(),
            label: id.into(),
            description: None,
            category: category.map(str::to_string),
            shortcut: None,
            node: None,
        }
    }

    #[test]
    fn unknown_node_falls_back_to_muted_not_a_wrong_colour() {
        assert_eq!(node_mineral_class(11), "text-muted-foreground");
        assert_eq!(node_mineral_class(1), "text-terracotta");
    }

    #[test]
    fn grouping_preserves_first_seen_category_order() {
        let items = vec![
            item("a", Some("Zebra")),
            item("b", Some("Apple")),
            item("c", Some("Zebra")),
        ];
        let grouped = group_by_category(&items);
        let order: Vec<&str> = grouped.iter().map(|(c, _)| c.as_str()).collect();
        // "Zebra" appeared first in the input, so it must stay first — a BTreeMap
        // would have alphabetized this to Apple, Zebra and silently reordered the UI.
        assert_eq!(order, vec!["Zebra", "Apple"]);
        assert_eq!(grouped[0].1.len(), 2);
    }

    #[test]
    fn uncategorised_items_group_under_results() {
        let items = vec![item("a", None)];
        let grouped = group_by_category(&items);
        assert_eq!(grouped[0].0, "Results");
    }

    #[test]
    fn ctrl_or_meta_k_toggles() {
        assert!(should_toggle("k", true));
        assert!(!should_toggle("k", false));
        assert!(!should_toggle("j", true));
    }

    #[test]
    fn escape_only_closes_while_open() {
        assert!(should_close_on_escape("Escape", true));
        assert!(!should_close_on_escape("Escape", false));
    }
}

n7-shell/nyuchi-command-palette.tsx:
"use client"
import * as React from "react"
import { cn } from "@/lib/utils"
import { useNyuchiHarness } from "@/lib/harness"

/* ═══════════════════════════════════════════════════════════════
   NYUCHI COMMAND PALETTE — Layer 7 App Shell
   Global search + actions. Cmd+K / Ctrl+K.
   ═══════════════════════════════════════════════════════════════ */

interface CommandItem {
  id: string
  label: string
  description?: string
  icon?: React.ReactNode
  category?: string
  shortcut?: string
  /** Architecture node (1–10) — renders as a mineral-coloured N-chip. */
  node?: number
  onSelect: () => void
}

/**
 * Node → mineral colour. Full static class strings (never constructed) so
 * Tailwind keeps them, per the design-system styling rule. Colours resolve
 * from the globals.css `--color-<mineral>` tokens.
 */
const NODE_MINERAL: Record<number, string> = {
  1: "text-terracotta",
  2: "text-cobalt",
  3: "text-tanzanite",
  4: "text-gold",
  5: "text-malachite",
  6: "text-cobalt",
  7: "text-gold",
  8: "text-sodalite",
  9: "text-copper",
  10: "text-sodalite",
}

interface NyuchiCommandPaletteProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  items?: CommandItem[]
  recentItems?: CommandItem[]
  placeholder?: string
  onSearch?: (query: string) => void
  loading?: boolean
  className?: string
}

export function NyuchiCommandPalette({
  open,
  onOpenChange,
  items = [],
  recentItems = [],
  placeholder = "Search or type a command...",
  onSearch,
  loading = false,
  className,
}: NyuchiCommandPaletteProps) {
  useNyuchiHarness("command-palette")
  const [query, setQuery] = React.useState("")
  const inputRef = React.useRef<HTMLInputElement>(null)

  // Keyboard shortcut
  React.useEffect(() => {
    function handleKey(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault()
        onOpenChange(!open)
      }
      if (e.key === "Escape" && open) onOpenChange(false)
    }
    document.addEventListener("keydown", handleKey)
    return () => document.removeEventListener("keydown", handleKey)
  }, [open, onOpenChange])

  React.useEffect(() => {
    if (open) {
      setQuery("")
      inputRef.current?.focus()
    }
  }, [open])
  React.useEffect(() => {
    onSearch?.(query)
  }, [query, onSearch])

  if (!open) return null

  const grouped = items.reduce<Record<string, CommandItem[]>>((acc, item) => {
    const cat = item.category || "Results"
    ;(acc[cat] ||= []).push(item)
    return acc
  }, {})

  return (
    <>
      <div
        className="fixed inset-0 z-50 bg-black/50"
        onClick={() => onOpenChange(false)}
        aria-hidden="true"
      />
      <div
        data-slot="nyuchi-command-palette"
        data-portal="https://mzizi.dev/components/nyuchi-command-palette"
        role="dialog"
        aria-label="Command palette"
        aria-modal="true"
        className={cn(
          "fixed inset-x-4 top-[15%] z-50 mx-auto max-w-lg overflow-hidden rounded-xl border border-border bg-card shadow-2xl",
          className
        )}
      >
        {/* Search input */}
        <div className="flex items-center border-b border-border px-4">
          <svg
            width="16"
            height="16"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            className="shrink-0 text-muted-foreground"
            aria-hidden="true"
          >
            <circle cx="11" cy="11" r="8" />
            <path d="M21 21l-4.3-4.3" />
          </svg>
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder={placeholder}
            className="flex-1 bg-transparent px-3 py-4 text-sm outline-none placeholder:text-muted-foreground"
            aria-label="Search commands"
          />
          {loading && (
            <div className="size-4 animate-spin rounded-full border-2 border-muted border-t-primary" />
          )}
        </div>

        {/* Results */}
        <div className="max-h-[60vh] overflow-y-auto p-2" role="listbox">
          {query.length === 0 && recentItems.length > 0 && (
            <div>
              <p className="px-2 py-1.5 text-xs font-medium text-muted-foreground">Recent</p>
              {recentItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => {
                    item.onSelect()
                    onOpenChange(false)
                  }}
                  role="option"
                  className="flex min-h-[44px] w-full items-center gap-3 rounded-sm px-3 py-2 text-left text-sm transition-colors hover:bg-muted focus-visible:bg-muted focus-visible:outline-none"
                >
                  {item.icon}
                  <span>{item.label}</span>
                </button>
              ))}
            </div>
          )}
          {Object.entries(grouped).map(([cat, catItems]) => (
            <div key={cat}>
              <p className="px-2 py-1.5 text-xs font-medium text-muted-foreground">{cat}</p>
              {catItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => {
                    item.onSelect()
                    onOpenChange(false)
                  }}
                  role="option"
                  className="flex min-h-[44px] w-full items-center justify-between gap-3 rounded-sm px-3 py-2 text-left text-sm transition-colors hover:bg-muted focus-visible:bg-muted focus-visible:outline-none"
                >
                  <div className="flex min-w-0 items-center gap-3">
                    {item.icon}
                    <div className="min-w-0">
                      <p className="truncate">{item.label}</p>
                      {item.description && (
                        <p className="truncate text-xs text-muted-foreground">{item.description}</p>
                      )}
                    </div>
                  </div>
                  {item.node ? (
                    <span
                      className={cn(
                        "shrink-0 rounded-full border border-current px-1.5 py-0.5 font-mono text-[10px] font-semibold",
                        NODE_MINERAL[item.node] ?? "text-muted-foreground"
                      )}
                    >
                      N{item.node}
                    </span>
                  ) : (
                    item.shortcut && (
                      <kbd className="shrink-0 rounded bg-muted px-1.5 py-0.5 font-mono text-[10px] text-muted-foreground">
                        {item.shortcut}
                      </kbd>
                    )
                  )}
                </button>
              ))}
            </div>
          ))}
          {query.length > 0 && items.length === 0 && !loading && (
            <p className="py-8 text-center text-sm text-muted-foreground">No results found</p>
          )}
        </div>

        {/* Keyboard hint bar */}
        <div className="flex items-center gap-4 border-t border-border px-4 py-2 text-[11px] text-muted-foreground">
          <span className="flex items-center gap-1.5">
            <kbd className="rounded border border-border bg-muted px-1.5 py-0.5 font-mono text-[10px]">
              ↑
            </kbd>
            <kbd className="rounded border border-border bg-muted px-1.5 py-0.5 font-mono text-[10px]">
              ↓
            </kbd>
            navigate
          </span>
          <span className="flex items-center gap-1.5">
            <kbd className="rounded border border-border bg-muted px-1.5 py-0.5 font-mono text-[10px]">
              ↵
            </kbd>
            select
          </span>
          <span className="ml-auto flex items-center gap-1.5">
            <kbd className="rounded border border-border bg-muted px-1.5 py-0.5 font-mono text-[10px]">
              esc
            </kbd>
            close
          </span>
        </div>
      </div>
    </>
  )
}

export type { CommandItem, NyuchiCommandPaletteProps }

n7-shell/nyuchi-connectivity-bar.rs:
//! NYUCHI CONNECTIVITY BAR — N7 shell, Dioxus.
//!
//! The Rust sibling of `nyuchi-connectivity-bar.tsx`: a status strip announcing the app's
//! network state, sharing its contract — same `data-slot`, same four states, same colours.
//!
//! # The retry control is below the published touch floor
//!
//! The `.tsx` ships `min-h-[44px]` on the retry button. N10's own `nyuchi-ai-context` states
//! the rule as "Touch targets: 48px minimum" — 44 is Apple's number, not this system's, and
//! this is the fourth component in this build-out with the identical shortfall
//! (`nyuchi-docs-engine`'s sidebar was the first two). Raised to `min-h-[48px]` here; nothing
//! else about the control changes.
//!
//! **The `.tsx` sibling still has this.**
//!
//! # The harness is a parameter, not a dependency
//!
//! The `.tsx` calls `useNyuchiHarness("connectivity-bar")` for `log.warn`. That hook is
//! itself an N3 component (`nyuchi-harness.tsx`) with no Rust port yet, and this component
//! should not block on one existing — nor should porting the harness later require touching
//! every N7 component that logs through it. [`ConnectivityBarProps::on_state_change`] is a
//! plain callback the host wires to whatever logger it has.
//!
//! # Auto-hide is host-owned, not timer-owned
//!
//! The `.tsx` starts a `setTimeout` internally and hides itself when it fires. Reproducing
//! that here would pull a timer dependency that differs by target — `gloo-timers` on wasm,
//! something else natively — into a crate that otherwise has none, to save the host four
//! lines. [`ConnectivityBarProps::visible`] is a plain controlled prop instead: the host
//! decides when the bar shows, exactly as it already decides `state`. `auto_hide_delay_ms`
//! is kept as data the host can act on, not a timer this component runs itself.

use dioxus::prelude::*;

/// Network state this bar reports.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ConnectionState {
    /// Connected. Auto-hides after [`ConnectivityBarProps::auto_hide_delay_ms`] by default.
    #[default]
    Online,
    /// A sync is in flight.
    Syncing,
    /// Serving stale data because the network is unavailable.
    Cached,
    /// No connection at all.
    Offline,
}

impl ConnectionState {
    /// Default label, matching the `.tsx` `STATE_CONFIG`.
    #[must_use]
    pub const fn default_label(self) -> &'static str {
        match self {
            Self::Online => "Connected",
            Self::Syncing => "Syncing...",
            Self::Cached => "Using cached data",
            Self::Offline => "No connection",
        }
    }

    /// CSS colour expression, byte-identical to the `.tsx`.
    #[must_use]
    pub const fn colour(self) -> &'static str {
        match self {
            Self::Online => "var(--connection-online, var(--status-success, #64FFDA))",
            Self::Syncing => "var(--connection-syncing, var(--status-info, #00B0FF))",
            Self::Cached => "var(--connection-cached, var(--status-warning, #FFD740))",
            Self::Offline => "var(--connection-offline, var(--status-error, #FF5252))",
        }
    }

    /// `data-state` value.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Online => "online",
            Self::Syncing => "syncing",
            Self::Cached => "cached",
            Self::Offline => "offline",
        }
    }
}

const ROOT: &str = "flex items-center justify-center gap-2 px-4 py-1.5 text-xs font-medium text-white transition-all";
const SPINNER: &str = "size-3 animate-spin rounded-full border-2 border-white/30 border-t-white";
/// The `.tsx` says `min-h-[44px]`. See the module docs.
const RETRY: &str = "ml-2 min-h-[48px] underline hover:no-underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white";

/// Join a base class string with a consumer's extra classes.
fn join(base: &str, extra: &str) -> String {
    if extra.is_empty() {
        base.to_owned()
    } else {
        format!("{base} {extra}")
    }
}

/// Props for [`ConnectivityBar`].
#[derive(Props, Clone, PartialEq)]
pub struct ConnectivityBarProps {
    /// Current connection state.
    #[props(default)]
    pub state: ConnectionState,
    /// Overrides the state's default label.
    #[props(default)]
    pub message: Option<String>,
    /// Whether the bar is shown right now. The host owns the auto-hide timer — see the
    /// module docs — and flips this after `auto_hide_delay_ms` when it wants the `.tsx`'s
    /// behaviour.
    #[props(default = true)]
    pub visible: bool,
    /// Suggested auto-hide delay in milliseconds, for a host that wants to reproduce the
    /// `.tsx` timing. Not enforced by this component.
    #[props(default = 2000)]
    pub auto_hide_delay_ms: u32,
    /// Called on every non-online state, in place of the `.tsx`'s harness `log.warn`.
    #[props(default)]
    pub on_state_change: Option<EventHandler<ConnectionState>>,
    /// Called when the retry control is pressed. Retry renders only when this is set AND
    /// the state is [`ConnectionState::Offline`], matching the `.tsx`.
    #[props(default)]
    pub on_retry: Option<EventHandler<()>>,
    /// Extra classes, merged onto the root.
    #[props(default)]
    pub class: String,
    /// Any other root attributes.
    #[props(extends = GlobalAttributes)]
    pub attributes: Vec<Attribute>,
}

/// A status strip announcing the app's network state.
#[component]
pub fn ConnectivityBar(props: ConnectivityBarProps) -> Element {
    let state = props.state;

    use_effect(move || {
        if state != ConnectionState::Online {
            if let Some(handler) = props.on_state_change {
                handler.call(state);
            }
        }
    });

    if !props.visible {
        return rsx! {};
    }

    let label = props
        .message
        .clone()
        .unwrap_or_else(|| state.default_label().to_owned());
    let colour = state.colour();
    let style = format!("background-color: {colour};");

    rsx! {
        div {
            "data-slot": "nyuchi-connectivity-bar",
            "data-portal": "https://mzizi.dev/components/nyuchi-connectivity-bar",
            "data-state": state.as_str(),
            role: "status",
            "aria-live": "polite",
            class: join(ROOT, &props.class),
            style: "{style}",
            ..props.attributes,

            if state == ConnectionState::Syncing {
                div { class: SPINNER }
            }
            span { "{label}" }
            if state == ConnectionState::Offline {
                if let Some(on_retry) = props.on_retry {
                    button {
                        class: RETRY,
                        onclick: move |_| on_retry.call(()),
                        "Retry"
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn labels_match_the_typescript() {
        assert_eq!(ConnectionState::Online.default_label(), "Connected");
        assert_eq!(ConnectionState::Syncing.default_label(), "Syncing...");
        assert_eq!(ConnectionState::Cached.default_label(), "Using cached data");
        assert_eq!(ConnectionState::Offline.default_label(), "No connection");
    }

    #[test]
    fn the_retry_control_meets_the_published_touch_floor() {
        assert!(RETRY.contains("min-h-[48px]"));
        assert!(!RETRY.contains("44px"));
    }

    #[test]
    fn data_state_values_are_lowercase_and_distinct() {
        let all = [
            ConnectionState::Online,
            ConnectionState::Syncing,
            ConnectionState::Cached,
            ConnectionState::Offline,
        ];
        let mut seen = std::collections::HashSet::new();
        for s in all {
            assert_eq!(s.as_str(), s.as_str().to_lowercase());
            assert!(seen.insert(s.as_str()));
        }
    }
}

