"use client"

// ── INFRASTRUCTURE HARNESS (auto-wired) ──────────────────
// Layer 4: Observability — scoped logger, render timing, health
// Layer 2: Motion — entry animation, reduced-motion safe
// Layer 3: A11y — LiveRegion for dynamic announcements
import { useNyuchiHarness } from "@/lib/harness"

import * as React from "react"
import { usePathname } from "next/navigation"
import { cn } from "@/lib/utils"
import { NyuchiLogo } from "@/components/brand/nyuchi-logo"
import { MineralStrip } from "@/components/brand/mineral-strip"
import { ThemeToggle } from "@/components/theme-toggle"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  SidebarRail,
  SidebarSeparator,
} from "@/components/ui/sidebar"

/* ═══════════════════════════════════════════════════════════════
   NYUCHI SIDEBAR — Brand Shell Component (Enterprise)

   FULLY WIRED into the Nyuchi 7-layer architecture:

   ✅ L1 TOKENS — CSS custom properties (--color-*, --radius-*)
   ✅ L2 MOTION — Stagger animation for nav items on mount
   ✅ L3 A11Y — ARIA navigation landmark, focus ring tokens
   ✅ L4 OBSERVABILITY — useNyuchiHarness, scoped logging
   ✅ L5 RESILIENCE — Graceful degradation for missing sections
   ✅ L6 I18N — No hardcoded strings, semantic labels
   ✅ L7 PLATFORM — data-slot for CSS targeting
   ═══════════════════════════════════════════════════════════════ */

export interface SidebarItem {
  label: string
  href: string
  icon?: React.ComponentType<{ className?: string }>
  badge?: string | number
  active?: boolean
  children?: SidebarItem[]
}

export interface SidebarSection {
  label?: string
  items: SidebarItem[]
}

interface NyuchiSidebarProps {
  sections: SidebarSection[]
  appName?: string
  header?: React.ReactNode
  footer?: React.ReactNode
  collapsible?: "offcanvas" | "icon" | "none"
  variant?: "sidebar" | "floating" | "inset"
  className?: string
}

export function NyuchiSidebar({
  sections,
  appName,
  header,
  footer,
  collapsible = "icon",
  variant = "sidebar",
  className,
}: NyuchiSidebarProps) {
  const pathname = usePathname()

  // ── L4: HARNESS — Connect to observability + motion + a11y ──
  const { motion, LiveRegion } = useNyuchiHarness("sidebar")

  function isActive(href: string): boolean {
    if (href === "/") return pathname === "/"
    return pathname === href || pathname.startsWith(href + "/")
  }

  // ── L2: MOTION — Stagger delay for nav items ──
  const itemAnimStyle = React.useCallback(
    (index: number) => {
      if (motion.prefersReduced) return {}
      return {
        animation: `nyuchi-fade-slide-up ${motion.enterDuration}ms ${motion.enterEasing} both`,
        animationDelay: `${motion.staggerDelay(index)}ms`,
      }
    },
    [motion]
  )

  return (
    <Sidebar
      data-slot="nyuchi-sidebar"
      data-portal="https://mzizi.dev/components/nyuchi-sidebar"
      collapsible={collapsible}
      variant={variant}
      className={cn(className)}
    >
      {/* L3: A11y — LiveRegion for dynamic announcements */}
      {LiveRegion}

      {/* L1: TOKENS — Mineral accent strip using brand colors */}
      <div className="flex h-1 w-full">
        <MineralStrip className="h-1 w-full flex-row rounded-none" />
      </div>

      <SidebarHeader>
        {header ?? (
          <a
            href="/"
            className={cn(
              "flex items-center gap-2 px-2 py-1.5",
              /* L3: A11y — Focus ring using design tokens */
              "focus-visible:outline-[length:var(--focusRing-width,2px)]",
              "focus-visible:outline-[var(--color-primary)]",
              "focus-visible:outline-offset-[var(--focusRing-offset,2px)]",
              "rounded-[var(--radius-inner,7px)]"
            )}
            aria-label={appName ? `${appName} home` : "Mukoko home"}
          >
            <NyuchiLogo size={22} suffix={appName} />
          </a>
        )}
      </SidebarHeader>

      <SidebarSeparator />

      <SidebarContent>
        {/* L5: RESILIENCE — Guard against empty/undefined sections */}
        {(sections ?? []).map((section, sectionIdx) => (
          <SidebarGroup key={section.label ?? sectionIdx}>
            {section.label && <SidebarGroupLabel>{section.label}</SidebarGroupLabel>}
            <SidebarGroupContent>
              <SidebarMenu role="navigation" aria-label={section.label || "Navigation"}>
                {(section.items ?? []).map((item, itemIdx) => {
                  const active = item.active ?? isActive(item.href)
                  const Icon = item.icon

                  return (
                    <SidebarMenuItem
                      key={item.href}
                      /* L2: MOTION — Stagger animation per item */
                      style={itemAnimStyle(sectionIdx * 10 + itemIdx)}
                    >
                      <SidebarMenuButton
                        asChild
                        isActive={active}
                        tooltip={item.label}
                        className={cn(
                          /* L1: TOKENS — Active state uses brand accent */
                          active &&
                            "bg-[var(--brand-accent,var(--color-primary,#00B0FF))]/10 text-[var(--brand-accent,var(--color-primary,#00B0FF))]",
                          /* L3: A11y — Focus ring tokens + min touch target */
                          "min-h-[48px]",
                          "focus-visible:outline-[length:var(--focusRing-width,2px)]",
                          "focus-visible:outline-[var(--color-primary)]",
                          "focus-visible:outline-offset-[var(--focusRing-offset,2px)]"
                        )}
                      >
                        <a href={item.href} aria-current={active ? "page" : undefined}>
                          {Icon && <Icon className="size-4" />}
                          <span>{item.label}</span>
                        </a>
                      </SidebarMenuButton>

                      {/* L1: TOKENS — Badge uses mineral accent */}
                      {item.badge != null && (
                        <SidebarMenuBadge className="bg-[var(--brand-accent,var(--color-primary,#00B0FF))]/15 font-semibold text-[var(--brand-accent,var(--color-primary,#00B0FF))]">
                          {item.badge}
                        </SidebarMenuBadge>
                      )}

                      {/* L5: RESILIENCE — Guard against undefined children */}
                      {item.children && item.children.length > 0 && (
                        <SidebarMenuSub>
                          {item.children.map((child) => {
                            const childActive = child.active ?? isActive(child.href)
                            return (
                              <SidebarMenuSubItem key={child.href}>
                                <SidebarMenuSubButton
                                  asChild
                                  isActive={childActive}
                                  className={cn(
                                    childActive &&
                                      "text-[var(--brand-accent,var(--color-primary,#00B0FF))]",
                                    "min-h-[48px]",
                                    "focus-visible:outline-[length:var(--focusRing-width,2px)]",
                                    "focus-visible:outline-[var(--color-primary)]"
                                  )}
                                >
                                  <a
                                    href={child.href}
                                    aria-current={childActive ? "page" : undefined}
                                  >
                                    <span>{child.label}</span>
                                  </a>
                                </SidebarMenuSubButton>
                              </SidebarMenuSubItem>
                            )
                          })}
                        </SidebarMenuSub>
                      )}
                    </SidebarMenuItem>
                  )
                })}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}
      </SidebarContent>

      <SidebarFooter>
        {footer ?? (
          <div className="flex items-center justify-between px-2 py-1">
            <ThemeToggle />
            <span className="font-mono text-[10px] text-muted-foreground">v4.0.1</span>
          </div>
        )}
      </SidebarFooter>

      <SidebarRail />
    </Sidebar>
  )
}

n7-shell/nyuchi-theme-provider.rs:
//! NYUCHI THEME PROVIDER — N7 shell, Dioxus.
//!
//! The Rust sibling of `nyuchi-theme-provider.tsx`'s decision logic: which theme wins at
//! startup, and how system preferences resolve to a mode.
//!
//! System-preference detection (`matchMedia`), persistence (`localStorage`), and
//! `document.documentElement` class/attribute wiring are all real-DOM glue with no portable
//! pure logic behind them — the host owns that part and passes in the already-resolved values,
//! the same way this node's other components take a host-controlled `visible` /
//! `prefers_reduced_motion` prop instead of re-implementing browser-only mechanisms in Rust.
//! [`NyuchiThemeProvider`] is accordingly a thin wrapper: it injects the host-generated CSS
//! variables and renders children; [`resolve_initial_theme`] and [`system_preference`] are the
//! parts worth testing.

use dioxus::prelude::*;

/// The resolved theme mode.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ThemeMode {
    /// Light mode.
    Light,
    /// Dark mode.
    Dark,
    /// High-contrast mode, overriding light/dark.
    HighContrast,
}

/// System-preference resolution. Contrast wins over dark, matching the
/// `.tsx`: `contrastMq.matches ? "high-contrast" : darkMq.matches ? "dark" : "light"`.
pub fn system_preference(prefers_high_contrast: bool, prefers_dark: bool) -> ThemeMode {
    if prefers_high_contrast {
        ThemeMode::HighContrast
    } else if prefers_dark {
        ThemeMode::Dark
    } else {
        ThemeMode::Light
    }
}

/// Initial theme priority: a stored (persisted) choice wins outright;
/// otherwise the system preference is used only if the host opted in;
/// otherwise the configured default. Mirrors the `.tsx`'s
/// `useState(() => stored ?? (useSystemPreference ? systemPreference : defaultTheme))`.
pub fn resolve_initial_theme(
    stored: Option<ThemeMode>,
    use_system_preference: bool,
    system_preference: ThemeMode,
    default_theme: ThemeMode,
) -> ThemeMode {
    if let Some(theme) = stored {
        return theme;
    }
    if use_system_preference {
        system_preference
    } else {
        default_theme
    }
}

/// Props for [`NyuchiThemeProvider`].
#[derive(Props, Clone, PartialEq)]
pub struct NyuchiThemeProviderProps {
    /// The resolved theme mode, already decided by the host.
    pub theme: ThemeMode,
    /// The active brand identity.
    pub brand: String,
    /// Host-generated CSS custom properties, injected verbatim as a `<style>` tag.
    pub css_vars: String,
    /// The subtree this provider wraps.
    pub children: Element,
}

/// Injects the host-resolved theme's CSS variables and renders children.
#[component]
pub fn NyuchiThemeProvider(props: NyuchiThemeProviderProps) -> Element {
    rsx! {
        style { dangerous_inner_html: "{props.css_vars}" }
        {props.children.clone()}
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn high_contrast_wins_over_dark() {
        assert_eq!(system_preference(true, true), ThemeMode::HighContrast);
    }

    #[test]
    fn dark_wins_over_light_when_no_contrast() {
        assert_eq!(system_preference(false, true), ThemeMode::Dark);
    }

    #[test]
    fn light_is_the_fallback() {
        assert_eq!(system_preference(false, false), ThemeMode::Light);
    }

    #[test]
    fn stored_choice_wins_over_everything() {
        let resolved = resolve_initial_theme(
            Some(ThemeMode::Light),
            true,
            ThemeMode::Dark,
            ThemeMode::Dark,
        );
        assert_eq!(resolved, ThemeMode::Light);
    }

    #[test]
    fn system_preference_used_when_opted_in_and_nothing_stored() {
        let resolved = resolve_initial_theme(None, true, ThemeMode::HighContrast, ThemeMode::Dark);
        assert_eq!(resolved, ThemeMode::HighContrast);
    }

    #[test]
    fn default_theme_used_when_not_using_system_preference() {
        let resolved = resolve_initial_theme(None, false, ThemeMode::HighContrast, ThemeMode::Dark);
        assert_eq!(resolved, ThemeMode::Dark);
    }
}

n7-shell/nyuchi-theme-provider.tsx:
"use client"

import * as React from "react"
import { generateCSSVariables, type ThemeMode, type BrandId } from "@/lib/tokens"

/* ═══════════════════════════════════════════════════════════════
   MUKOKO THEME PROVIDER

   Wraps the application root and provides:
   1. CSS custom properties generated from the token system
   2. React context for runtime theme/brand switching
   3. System preference detection (prefers-color-scheme, prefers-contrast)
   4. Persistence via localStorage
   5. Class-based theme application for Tailwind dark: prefix
   ═══════════════════════════════════════════════════════════════ */

interface ThemeContextValue {
  theme: ThemeMode
  brand: BrandId
  setTheme: (theme: ThemeMode) => void
  setBrand: (brand: BrandId) => void
  systemPreference: ThemeMode
  /** Whether reduced motion is preferred */
  prefersReducedMotion: boolean
  /** Whether high contrast is preferred */
  prefersHighContrast: boolean
}

const ThemeContext = React.createContext<ThemeContextValue | null>(null)

export function useTheme() {
  const ctx = React.useContext(ThemeContext)
  if (!ctx) throw new Error("useTheme must be used within NyuchiThemeProvider")
  return ctx
}

interface NyuchiThemeProviderProps {
  children: React.ReactNode
  /** Default theme mode */
  defaultTheme?: ThemeMode
  /** Brand identity (changes primary accent color) */
  brand?: BrandId
  /** Use system preference for initial theme */
  useSystemPreference?: boolean
  /** Storage key for persisting theme choice */
  storageKey?: string
}

export function NyuchiThemeProvider({
  children,
  defaultTheme = "dark",
  brand: initialBrand = "mukoko",
  useSystemPreference = true,
  storageKey = "nyuchi-theme",
}: NyuchiThemeProviderProps) {
  /* Detect system preferences */
  const [systemPreference, setSystemPreference] = React.useState<ThemeMode>("dark")
  const [prefersReducedMotion, setPrefersReducedMotion] = React.useState(false)
  const [prefersHighContrast, setPrefersHighContrast] = React.useState(false)

  React.useEffect(() => {
    const darkMq = window.matchMedia("(prefers-color-scheme: dark)")
    const contrastMq = window.matchMedia("(prefers-contrast: more)")
    const motionMq = window.matchMedia("(prefers-reduced-motion: reduce)")

    setSystemPreference(contrastMq.matches ? "high-contrast" : darkMq.matches ? "dark" : "light")
    setPrefersHighContrast(contrastMq.matches)
    setPrefersReducedMotion(motionMq.matches)

    const onDark = (e: MediaQueryListEvent) => setSystemPreference(e.matches ? "dark" : "light")
    const onContrast = (e: MediaQueryListEvent) => {
      setPrefersHighContrast(e.matches)
      if (e.matches) setSystemPreference("high-contrast")
    }
    const onMotion = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches)

    darkMq.addEventListener("change", onDark)
    contrastMq.addEventListener("change", onContrast)
    motionMq.addEventListener("change", onMotion)
    return () => {
      darkMq.removeEventListener("change", onDark)
      contrastMq.removeEventListener("change", onContrast)
      motionMq.removeEventListener("change", onMotion)
    }
  }, [])

  /* Theme state with persistence */
  const [theme, setThemeState] = React.useState<ThemeMode>(() => {
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem(storageKey) as ThemeMode | null
      if (stored) return stored
    }
    return useSystemPreference ? systemPreference : defaultTheme
  })
  const [brand, setBrand] = React.useState<BrandId>(initialBrand)

  const setTheme = React.useCallback(
    (t: ThemeMode) => {
      setThemeState(t)
      if (typeof window !== "undefined") localStorage.setItem(storageKey, t)
    },
    [storageKey]
  )

  /* Generate and inject CSS variables */
  const cssVars = React.useMemo(() => generateCSSVariables(theme, brand), [theme, brand])

  /* Apply dark/light class for Tailwind */
  React.useEffect(() => {
    const root = document.documentElement
    root.classList.remove("light", "dark")
    root.classList.add(theme === "light" ? "light" : "dark")
    root.setAttribute("data-theme", theme)
    root.setAttribute("data-brand", brand)
    if (prefersReducedMotion) root.setAttribute("data-reduced-motion", "true")
    else root.removeAttribute("data-reduced-motion")
  }, [theme, brand, prefersReducedMotion])

  const value: ThemeContextValue = {
    theme,
    brand,
    setTheme,
    setBrand,
    systemPreference,
    prefersReducedMotion,
    prefersHighContrast,
  }

  return (
    <ThemeContext.Provider value={value}>
      <style dangerouslySetInnerHTML={{ __html: cssVars }} />
      {children}
    </ThemeContext.Provider>
  )
}

n7-shell/nyuchi-toast-provider.rs:
//! NYUCHI TOAST PROVIDER — N7 shell, Dioxus.
//!
//! The Rust sibling of `nyuchi-toast-provider.tsx`: a toast queue with position and cap,
//! sharing its contract — same `data-slot`, same position/type class maps.
//!
//! # `max_visible == 0` is a `.tsx` edge case
//!
//! The `.tsx` caps the queue with `[...prev.slice(-(maxVisible - 1)), item]`. At
//! `maxVisible === 0` that becomes `prev.slice(-(-1))`, i.e. `prev.slice(1)` — which drops only
//! the oldest existing toast and still appends the new one, so a "cap of zero" would still show
//! one toast. [`push_toast`] treats `max_visible == 0` as "show none" instead.
//!
//! **The `.tsx` sibling still has this.**
//!
//! Toast IDs are the caller's responsibility here rather than generated internally
//! (`Date.now().toString(36) + Math.random()...` in the `.tsx`) — pushing ID generation to the
//! host keeps the queue logic pure and deterministic to test.

use dioxus::prelude::*;

/// Visual/semantic category of a toast.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ToastKind {
    /// No particular semantic category.
    Default,
    /// A positive/confirming outcome.
    Success,
    /// A failure.
    Error,
    /// A caution.
    Warning,
    /// A neutral notice.
    Info,
}

/// Where the toast stack is anchored on screen.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ToastPosition {
    /// Anchored to the top-right corner.
    TopRight,
    /// Anchored to top-center.
    TopCenter,
    /// Anchored to the bottom-right corner, above the bottom nav.
    BottomRight,
    /// Anchored to bottom-center, above the bottom nav.
    BottomCenter,
}

/// Tailwind position classes for a [`ToastPosition`].
pub fn position_class(position: ToastPosition) -> &'static str {
    match position {
        ToastPosition::TopRight => "top-4 right-4",
        ToastPosition::TopCenter => "top-4 left-1/2 -translate-x-1/2",
        ToastPosition::BottomRight => "bottom-20 right-4",
        ToastPosition::BottomCenter => "bottom-20 left-1/2 -translate-x-1/2",
    }
}

/// Tailwind accent classes for a [`ToastKind`].
pub fn type_style_class(kind: ToastKind) -> &'static str {
    match kind {
        ToastKind::Default => "border-border",
        ToastKind::Success => "border-l-4 border-l-[var(--status-success,#64FFDA)]",
        ToastKind::Error => "border-l-4 border-l-[var(--status-error,#FF5252)]",
        ToastKind::Warning => "border-l-4 border-l-[var(--status-warning,#FFD740)]",
        ToastKind::Info => "border-l-4 border-l-[var(--status-info,#00B0FF)]",
    }
}

/// A single toast in the queue.
#[derive(Clone, Debug, PartialEq)]
pub struct ToastItem {
    /// Unique identifier, supplied by the caller.
    pub id: String,
    /// Visual/semantic category.
    pub kind: ToastKind,
    /// Headline text.
    pub title: String,
    /// Optional body text.
    pub message: Option<String>,
    /// Whether the user can dismiss this toast manually.
    pub dismissible: bool,
}

/// Appends a new toast, keeping the queue capped at `max_visible` — see the module docs for how
/// this differs from the `.tsx` at `max_visible == 0`.
pub fn push_toast(existing: &[ToastItem], item: ToastItem, max_visible: usize) -> Vec<ToastItem> {
    if max_visible == 0 {
        return Vec::new();
    }
    let keep = max_visible.saturating_sub(1);
    let start = existing.len().saturating_sub(keep);
    let mut next: Vec<ToastItem> = existing[start..].to_vec();
    next.push(item);
    next
}

/// Removes a toast by id.
pub fn dismiss(existing: &[ToastItem], id: &str) -> Vec<ToastItem> {
    existing.iter().filter(|t| t.id != id).cloned().collect()
}

/// Props for [`NyuchiToastProvider`].
#[derive(Props, Clone, PartialEq)]
pub struct NyuchiToastProviderProps {
    /// Where the toast stack is anchored.
    #[props(default = ToastPosition::BottomRight)]
    pub position: ToastPosition,
    /// The current toast queue, controlled by the host.
    pub toasts: Vec<ToastItem>,
    /// Fired with a toast's `id` when it is dismissed.
    #[props(default)]
    pub on_dismiss: EventHandler<String>,
    /// The subtree this provider wraps.
    pub children: Element,
}

/// Renders children plus a positioned toast stack.
#[component]
pub fn NyuchiToastProvider(props: NyuchiToastProviderProps) -> Element {
    rsx! {
        {props.children.clone()}
        div {
            "data-slot": "nyuchi-toast-provider",
            "data-portal": "https://mzizi.dev/components/nyuchi-toast-provider",
            "aria-live": "polite",
            "aria-atomic": "false",
            class: "pointer-events-none fixed z-50 flex w-full max-w-sm flex-col gap-2 {position_class(props.position)}",
            for toast in props.toasts.iter() {
                div {
                    key: "{toast.id}",
                    role: "alert",
                    class: "pointer-events-auto rounded-[var(--radius-lg,14px)] border bg-card p-4 shadow-lg {type_style_class(toast.kind)}",
                    div { class: "flex items-start justify-between gap-2",
                        div { class: "min-w-0",
                            p { class: "text-sm font-medium", "{toast.title}" }
                            if let Some(message) = &toast.message {
                                p { class: "mt-0.5 text-xs text-muted-foreground", "{message}" }
                            }
                        }
                        if toast.dismissible {
                            button {
                                "aria-label": "Dismiss",
                                class: "flex min-h-[48px] min-w-[48px] shrink-0 items-center justify-center text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary",
                                onclick: {
                                    let id = toast.id.clone();
                                    move |_| props.on_dismiss.call(id.clone())
                                },
                                "\u{2715}"
                            }
                        }
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn toast(id: &str) -> ToastItem {
        ToastItem {
            id: id.into(),
            kind: ToastKind::Default,
            title: id.into(),
            message: None,
            dismissible: true,
        }
    }

    #[test]
    fn queue_is_capped_at_max_visible() {
        let existing = vec![toast("a"), toast("b"), toast("c")];
        let next = push_toast(&existing, toast("d"), 3);
        assert_eq!(next.len(), 3);
        assert_eq!(
            next.iter().map(|t| t.id.as_str()).collect::<Vec<_>>(),
            vec!["b", "c", "d"]
        );
    }

    #[test]
    fn queue_grows_until_the_cap_is_reached() {
        let existing = vec![toast("a")];
        let next = push_toast(&existing, toast("b"), 3);
        assert_eq!(
            next.iter().map(|t| t.id.as_str()).collect::<Vec<_>>(),
            vec!["a", "b"]
        );
    }

    #[test]
    fn max_visible_zero_shows_nothing() {
        // The .tsx's `prev.slice(-(maxVisible - 1))` degrades to
        // `slice(1)` when maxVisible is 0 — it drops the oldest toast and
        // still appends the new one, so "cap of zero" would still show
        // one toast. Fixed here to show none.
        let existing = vec![toast("a")];
        let next = push_toast(&existing, toast("b"), 0);
        assert!(next.is_empty());
    }

    #[test]
    fn dismiss_removes_only_the_matching_id() {
        let existing = vec![toast("a"), toast("b")];
        let next = dismiss(&existing, "a");
        assert_eq!(
            next.iter().map(|t| t.id.as_str()).collect::<Vec<_>>(),
            vec!["b"]
        );
    }
}

n7-shell/nyuchi-toast-provider.tsx:
"use client"
import * as React from "react"
import { cn } from "@/lib/utils"
import { useNyuchiHarness } from "@/lib/harness"

interface ToastItem {
  id: string
  type?: "default" | "success" | "error" | "warning" | "info"
  title: string
  message?: string
  duration?: number
  action?: { label: string; onClick: () => void }
  dismissible?: boolean
}

interface NyuchiToastProviderProps {
  position?: "top-right" | "top-center" | "bottom-right" | "bottom-center"
  maxVisible?: number
  defaultDuration?: number
  children: React.ReactNode
}

const ToastContext = React.createContext<{
  addToast: (toast: Omit<ToastItem, "id">) => void
  removeToast: (id: string) => void
} | null>(null)

export function useToast() {
  const ctx = React.useContext(ToastContext)
  if (!ctx) throw new Error("useToast must be used within NyuchiToastProvider")
  return ctx
}

const POSITION_CLASSES = {
  "top-right": "top-4 right-4",
  "top-center": "top-4 left-1/2 -translate-x-1/2",
  "bottom-right": "bottom-20 right-4",
  "bottom-center": "bottom-20 left-1/2 -translate-x-1/2",
}

const TYPE_STYLES: Record<string, string> = {
  default: "border-border",
  success: "border-l-4 border-l-[var(--status-success,#64FFDA)]",
  error: "border-l-4 border-l-[var(--status-error,#FF5252)]",
  warning: "border-l-4 border-l-[var(--status-warning,#FFD740)]",
  info: "border-l-4 border-l-[var(--status-info,#00B0FF)]",
}

export function NyuchiToastProvider({
  position = "bottom-right",
  maxVisible = 3,
  defaultDuration = 5000,
  children,
}: NyuchiToastProviderProps) {
  const { log } = useNyuchiHarness("toast-provider")
  const [toasts, setToasts] = React.useState<ToastItem[]>([])

  const addToast = React.useCallback(
    (toast: Omit<ToastItem, "id">) => {
      const id = Date.now().toString(36) + Math.random().toString(36).slice(2)
      const item: ToastItem = {
        id,
        duration: defaultDuration,
        dismissible: true,
        type: "default",
        ...toast,
      }
      setToasts((prev) => [...prev.slice(-(maxVisible - 1)), item])
      log.info(`toast: ${item.type} — ${item.title}`)
      if (item.duration && item.duration > 0) {
        setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), item.duration)
      }
    },
    [defaultDuration, maxVisible, log]
  )

  const removeToast = React.useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id))
  }, [])

  return (
    <ToastContext.Provider value={{ addToast, removeToast }}>
      {children}
      <div
        data-slot="nyuchi-toast-provider"
        data-portal="https://mzizi.dev/components/nyuchi-toast-provider"
        aria-live="polite"
        aria-atomic="false"
        className={cn(
          "pointer-events-none fixed z-50 flex w-full max-w-sm flex-col gap-2",
          POSITION_CLASSES[position]
        )}
      >
        {toasts.map((toast) => (
          <div
            key={toast.id}
            role="alert"
            className={cn(
              "pointer-events-auto rounded-[var(--radius-lg,14px)] border bg-card p-4 shadow-lg",
              TYPE_STYLES[toast.type || "default"]
            )}
          >
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <p className="text-sm font-medium">{toast.title}</p>
                {toast.message && (
                  <p className="mt-0.5 text-xs text-muted-foreground">{toast.message}</p>
                )}
              </div>
              {toast.dismissible && (
                <button
                  onClick={() => removeToast(toast.id)}
                  aria-label="Dismiss"
                  className="flex min-h-[44px] min-w-[44px] shrink-0 items-center justify-center text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
                >
                  <svg
                    width="14"
                    height="14"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    aria-hidden="true"
                  >
                    <path d="M18 6L6 18M6 6l12 12" />
                  </svg>
                </button>
              )}
            </div>
            {toast.action && (
              <button
                onClick={toast.action.onClick}
                className="mt-2 text-xs font-medium text-primary hover:underline"
              >
                {toast.action.label}
              </button>
            )}
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  )
}

export type { ToastItem, NyuchiToastProviderProps }

n7-shell/nyuchi-update-prompt.rs:
//! NYUCHI UPDATE PROMPT — N7 shell, Dioxus.
//!
//! The Rust sibling of `nyuchi-update-prompt.tsx`: a bottom-sheet asking the user to refresh
//! for a new version, sharing its contract — same `data-slot`, same critical/optional split.
//!
//! # The harness's motion preference is a parameter, not a dependency
//!
//! The `.tsx` reads `motion.prefersReduced` and `motion.enterDuration`/`enterEasing` from
//! `useNyuchiHarness`, which is an N3 component (`nyuchi-harness.tsx`) with no Rust port yet.
//! [`UpdatePromptProps::prefers_reduced_motion`] takes the one bit this component actually
//! branches on directly; a host with the full harness passes its `motion.prefersReduced`
//! through, and a host without one can pass `false` and get the entrance animation.

use dioxus::prelude::*;

const ROOT: &str = "fixed right-4 bottom-20 left-4 z-50 mx-auto max-w-sm rounded-[var(--radius-xl,17px)] border border-border bg-card p-4 shadow-2xl";
const UPDATE_BUTTON: &str = "min-h-[48px] flex-1 rounded-full bg-primary text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary";
const DISMISS_BUTTON: &str = "min-h-[48px] rounded-full bg-muted px-4 text-sm font-medium text-foreground transition-colors hover:bg-muted/80";

/// Join a base class string with a consumer's extra classes.
fn join(base: &str, extra: &str) -> String {
    if extra.is_empty() {
        base.to_owned()
    } else {
        format!("{base} {extra}")
    }
}

/// The body copy, matching the `.tsx` exactly including its conditional phrasing.
#[must_use]
pub fn body_text(version: Option<&str>, is_critical: bool) -> String {
    let lead = version.map_or_else(
        || "A new version is ready.".to_owned(),
        |v| format!("Version {v} is ready."),
    );
    let tail = if is_critical {
        "This update is required to continue."
    } else {
        "Refresh to get the latest improvements."
    };
    format!("{lead} {tail}")
}

/// The animation inline style, matching the `.tsx`'s `motion.prefersReduced` branch.
///
/// Empty when motion is reduced, matching the `.tsx`'s `{}`.
#[must_use]
pub fn entrance_style(prefers_reduced_motion: bool, duration_ms: u32, easing: &str) -> String {
    if prefers_reduced_motion {
        String::new()
    } else {
        format!("animation: nyuchi-fade-slide-up {duration_ms}ms {easing} both;")
    }
}

/// Props for [`UpdatePrompt`].
#[derive(Props, Clone, PartialEq)]
pub struct UpdatePromptProps {
    /// Whether the prompt is shown.
    #[props(default = false)]
    pub visible: bool,
    /// Version being offered.
    #[props(default)]
    pub version: Option<String>,
    /// Whether declining is not an option — hides the dismiss button.
    #[props(default = false)]
    pub is_critical: bool,
    /// Called when the user chooses to update.
    #[props(default)]
    pub on_update: Option<EventHandler<()>>,
    /// Called when the user dismisses. Ignored when `is_critical` is true, matching the
    /// `.tsx`'s `{!isCritical && onDismiss && ...}`.
    #[props(default)]
    pub on_dismiss: Option<EventHandler<()>>,
    /// See the module docs.
    #[props(default = false)]
    pub prefers_reduced_motion: bool,
    /// Entrance animation duration in ms, when motion is not reduced.
    #[props(default = 220)]
    pub enter_duration_ms: u32,
    /// Entrance animation easing, when motion is not reduced.
    #[props(default = "ease-out".to_owned())]
    pub enter_easing: String,
    /// Extra classes, merged onto the root.
    #[props(default)]
    pub class: String,
    /// Any other root attributes.
    #[props(extends = GlobalAttributes)]
    pub attributes: Vec<Attribute>,
}

/// A bottom-sheet prompting the user to refresh for a new version.
#[component]
pub fn UpdatePrompt(props: UpdatePromptProps) -> Element {
    if !props.visible {
        return rsx! {};
    }

    let heading = if props.is_critical {
        "Critical update required"
    } else {
        "Update available"
    };
    let body = body_text(props.version.as_deref(), props.is_critical);
    let style = entrance_style(
        props.prefers_reduced_motion,
        props.enter_duration_ms,
        &props.enter_easing,
    );
    let show_dismiss = !props.is_critical && props.on_dismiss.is_some();

    rsx! {
        div {
            "data-slot": "nyuchi-update-prompt",
            "data-portal": "https://mzizi.dev/components/nyuchi-update-prompt",
            role: "alertdialog",
            "aria-label": "Update available",
            style: "{style}",
            class: join(ROOT, &props.class),
            ..props.attributes,

            p { class: "text-sm font-semibold", "{heading}" }
            p { class: "mt-1 text-xs text-muted-foreground", "{body}" }
            div { class: "mt-3 flex gap-2",
                button {
                    class: UPDATE_BUTTON,
                    onclick: move |_| {
                        if let Some(h) = props.on_update { h.call(()) }
                    },
                    "Update"
                }
                if show_dismiss {
                    button {
                        class: DISMISS_BUTTON,
                        onclick: move |_| {
                            if let Some(h) = props.on_dismiss { h.call(()) }
                        },
                        "Later"
                    }
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn body_text_with_version_and_critical() {
        assert_eq!(
            body_text(Some("4.2.0"), true),
            "Version 4.2.0 is ready. This update is required to continue."
        );
    }

    #[test]
    fn body_text_without_version_and_optional() {
        assert_eq!(
            body_text(None, false),
            "A new version is ready. Refresh to get the latest improvements."
        );
    }

    #[test]
    fn reduced_motion_produces_no_animation_style() {
        assert_eq!(entrance_style(true, 220, "ease-out"), "");
    }

    #[test]
    fn full_motion_names_the_fade_slide_up_keyframe() {
        let style = entrance_style(false, 300, "ease-in-out");
        assert!(style.contains("nyuchi-fade-slide-up"));
        assert!(style.contains("300ms"));
        assert!(style.contains("ease-in-out"));
    }

    #[test]
    fn the_update_button_meets_the_touch_floor() {
        assert!(UPDATE_BUTTON.contains("min-h-[48px]"));
        assert!(DISMISS_BUTTON.contains("min-h-[48px]"));
    }
}

n7-shell/nyuchi-update-prompt.tsx:
"use client"
import * as React from "react"
import { cn } from "@/lib/utils"
import { useNyuchiHarness } from "@/lib/harness"

interface NyuchiUpdatePromptProps {
  visible?: boolean
  version?: string
  isCritical?: boolean
  onUpdate?: () => void
  onDismiss?: () => void
  className?: string
}

export function NyuchiUpdatePrompt({
  visible = false,
  version,
  isCritical = false,
  onUpdate,
  onDismiss,
  className,
}: NyuchiUpdatePromptProps) {
  const { log, motion } = useNyuchiHarness("update-prompt")
  const animStyle = React.useMemo(
    () =>
      motion.prefersReduced
        ? {}
        : {
            animation: `nyuchi-fade-slide-up ${motion.enterDuration}ms ${motion.enterEasing} both`,
          },
    [motion]
  )

  React.useEffect(() => {
    if (visible) log.info(`update_prompt: v${version} critical=${isCritical}`)
  }, [visible, version, isCritical, log])

  if (!visible) return null

  return (
    <div
      data-slot="nyuchi-update-prompt"
      data-portal="https://mzizi.dev/components/nyuchi-update-prompt"
      role="alertdialog"
      aria-label="Update available"
      style={animStyle}
      className={cn(
        "fixed right-4 bottom-20 left-4 z-50 mx-auto max-w-sm rounded-[var(--radius-xl,17px)] border border-border bg-card p-4 shadow-2xl",
        className
      )}
    >
      <p className="text-sm font-semibold">
        {isCritical ? "Critical update required" : "Update available"}
      </p>
      <p className="mt-1 text-xs text-muted-foreground">
        {version ? `Version ${version} is ready.` : "A new version is ready."}{" "}
        {isCritical
          ? "This update is required to continue."
          : "Refresh to get the latest improvements."}
      </p>
      <div className="mt-3 flex gap-2">
        <button
          onClick={onUpdate}
          className="min-h-[48px] flex-1 rounded-full bg-primary text-sm font-medium text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
        >
          Update
        </button>
        {!isCritical && onDismiss && (
          <button
            onClick={onDismiss}
            className="min-h-[48px] rounded-full bg-muted px-4 text-sm font-medium text-foreground transition-colors hover:bg-muted/80"
          >
            Later
          </button>
        )}
      </div>
    </div>
  )
}

export type { NyuchiUpdatePromptProps }

n8-assurance/mzizi-a11y-audit.rs:
//! Mzizi N8 assurance — runtime accessibility rules.
//!
//! The Rust implementation of `mzizi-a11y-audit`. The rules, the levels, the
//! selector and the score; not the DOM walk. The host observes the page and hands
//! over a list of [`ObservedNode`] in document order, which is the only step that
//! needs a browser.
//!
//! Document order matters and is part of the contract: [`Rule::HeadingOrder`]
//! reads it. Hand nodes over in the order `querySelectorAll("*")` yields them, not
//! sorted or filtered.
//!
//! # Four defects in the TypeScript, fixed here
//!
//! **1. One element could report at most ONE violation.** The `.ts` chains its
//! rules with `else if`, so an `<img>` with no alt is never checked for anything
//! else, and a `<button>` with no accessible name is never checked for touch
//! target size. The rules are independent facts about an element; chaining them
//! means the *first* finding hides the rest, and a button with no name is exactly
//! the button most likely to also be too small. Every rule is evaluated here.
//!
//! **2. A conformant button never counted as a pass.** Falling into the
//! touch-target branch and finding nothing wrong incremented nothing — `passes++`
//! lived only in the branches an interactive element could not reach. So a page
//! of correct buttons scored *lower* than a page of `<div>`s, and the one number
//! anybody looks at moved the wrong way as accessibility improved. An element
//! passes here when it produced no violations, which is the only definition that
//! cannot invert.
//!
//! **3. The heading-order rule was a comment.** `// Rule: Headings should be in
//! order` sat above a branch that matched `H1`–`H6` and then did nothing but count
//! a pass. A stated rule that evaluates nothing reads as coverage on a dashboard
//! and is worse than an absent one. Implemented — see [`Rule::HeadingOrder`].
//!
//! **4. The touch-target rule measured the wrong box.** `getBoundingClientRect()`
//! is the *visual* box, and Mzizi's control scale is deliberately dense — `h-8` /
//! `h-9` / `h-10`, so 32-40px (CLAUDE.md §8.2). Measuring the visual box therefore
//! flagged every correctly-built Mzizi control as a moderate violation: the design
//! system failed its own audit universally, which is the fastest way to teach
//! everyone to ignore a rule. §8.2 says a dense control earns its hit area through
//! surrounding spacing or padding beyond the visual box, so the hit area is what
//! the rule is about. The host supplies [`ObservedNode::hit_box`] and is expected
//! to include that padding.
//!
//! # Two things recorded rather than changed
//!
//! **`<a>` is held to a size but not to a name.** `button-name` covers `<button>`
//! and `role="button"`; `touch-target` additionally covers `<a>`. So a link with
//! no accessible name passes. That is a coverage gap in the rule set, not a defect
//! in this port, and adding a `link-name` rule would silently change what every
//! existing consumer's score means. Left as it is, said out loud.
//!
//! **The node guess can only ever answer 2, 3 or 6.** `guessNodeFromSlot` is a
//! string heuristic over the slot name, so a violation in an N7 shell component is
//! labelled N6 and routed to the wrong owner — and N1, N4, N5 and N8-N12 are
//! unreachable answers. The registry knows the real node, so [`resolve_node`]
//! prefers a lookup the host supplies and falls back to the heuristic only when
//! there is no entry. The heuristic is kept because a consumer auditing their own
//! app has no Mzizi registry to consult.

use std::collections::{BTreeMap, BTreeSet};

/// How much an accessibility violation matters.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum A11yLevel {
    /// Cosmetic or advisory.
    Minor,
    /// Degrades the experience for assistive technology.
    Moderate,
    /// Blocks a common task.
    Serious,
    /// Makes the element unusable.
    Critical,
}

impl A11yLevel {
    /// The wire spelling, matching the `.ts` string union.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Critical => "critical",
            Self::Serious => "serious",
            Self::Moderate => "moderate",
            Self::Minor => "minor",
        }
    }
}

/// Which rule produced a finding.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Rule {
    /// An image with no `alt` attribute at all.
    ImgAlt,
    /// A button with no accessible name.
    ButtonName,
    /// An interactive control whose hit area is below the floor.
    TouchTarget,
    /// A heading that skips a level.
    HeadingOrder,
}

impl Rule {
    /// The wire spelling, matching the `.ts` `rule` strings.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::ImgAlt => "img-alt",
            Self::ButtonName => "button-name",
            Self::TouchTarget => "touch-target",
            Self::HeadingOrder => "heading-order",
        }
    }

    /// Every rule this core evaluates.
    #[must_use]
    pub fn all() -> BTreeSet<Self> {
        [
            Self::ImgAlt,
            Self::ButtonName,
            Self::TouchTarget,
            Self::HeadingOrder,
        ]
        .into_iter()
        .collect()
    }
}

/// The measured hit area of a control, in CSS pixels.
///
/// This is the *interactive* area — the visual box plus any padding that extends
/// what a finger can land on — not `getBoundingClientRect()` on the painted
/// element. See the module docs, defect 4.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HitBox {
    /// Width in CSS pixels.
    pub width: f64,
    /// Height in CSS pixels.
    pub height: f64,
}

/// One element as the host observed it.
///
/// Every field is a plain value rather than a live DOM reference, which is what
/// lets the rules run in a Worker, in CI against server-rendered HTML, or in a
/// test. It also sidesteps a real crash in the `.ts`: `el.className` is an
/// `SVGAnimatedString` on SVG elements, so `.split(" ")` throws on any SVG element
/// that reaches the selector builder.
///
/// `PartialEq` without `Eq`, because [`HitBox`] holds `f64` and floats have no
/// total equality — the same reason [`f64::NAN`] is not equal to itself.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ObservedNode {
    /// Uppercase tag name, e.g. `BUTTON`.
    pub tag_name: String,
    /// The `id`, when present.
    pub id: Option<String>,
    /// The first class, when present.
    pub first_class: Option<String>,
    /// The `data-slot` value.
    pub data_slot: Option<String>,
    /// The `data-portal` backlink.
    pub data_portal: Option<String>,
    /// The `alt` attribute. `Some("")` is a decorative image and passes; `None`
    /// means the attribute is absent, which does not.
    pub alt: Option<String>,
    /// The `aria-label`.
    pub aria_label: Option<String>,
    /// The `aria-labelledby`.
    pub aria_labelledby: Option<String>,
    /// The `role`.
    pub role: Option<String>,
    /// Rendered text content.
    pub text: Option<String>,
    /// Whether the element occupies space. The `.ts` uses `offsetHeight > 0`,
    /// which reports true for `visibility: hidden` and `opacity: 0` — so a hidden
    /// control is still audited. Named `visible` because that is what the rule
    /// wants; supplying the honest answer is the host's job.
    pub visible: bool,
    /// The interactive area, when the host could measure it.
    pub hit_box: Option<HitBox>,
}

impl ObservedNode {
    /// Whether this element is a button for the purposes of [`Rule::ButtonName`].
    #[must_use]
    pub fn is_button(&self) -> bool {
        self.tag_name.eq_ignore_ascii_case("button") || self.role.as_deref() == Some("button")
    }

    /// Whether this element is a touch target for [`Rule::TouchTarget`].
    #[must_use]
    pub fn is_touch_target(&self) -> bool {
        self.is_button() || self.tag_name.eq_ignore_ascii_case("a")
    }

    /// The name a screen reader would announce, if any.
    ///
    /// `role` is NOT a name. `mzizi-conformity-check.ts` treats it as one
    /// (`aria-label || role`), which makes its own rule unfireable for exactly the
    /// `role="button"` elements it was widened to cover; this is the correct
    /// definition and the two now agree.
    #[must_use]
    pub fn accessible_name(&self) -> Option<&str> {
        [
            self.aria_label.as_deref(),
            self.aria_labelledby.as_deref(),
            self.text.as_deref(),
        ]
        .into_iter()
        .flatten()
        .map(str::trim)
        .find(|name| !name.is_empty())
    }

    /// The heading level, for `H1`-`H6`.
    #[must_use]
    pub fn heading_level(&self) -> Option<u8> {
        let bytes = self.tag_name.as_bytes();
        match bytes {
            [h, d] if h.eq_ignore_ascii_case(&b'H') && d.is_ascii_digit() => {
                let level = d - b'0';
                (1..=6).contains(&level).then_some(level)
            }
            _ => None,
        }
    }
}

/// One finding.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct A11yViolation {
    /// Which rule.
    pub rule: Rule,
    /// How much it matters.
    pub level: A11yLevel,
    /// What is wrong, in words.
    pub message: String,
    /// The element's tag.
    pub element: String,
    /// A selector that finds it again.
    pub selector: String,
    /// Which helix node owns the component, when known.
    pub node: Option<u32>,
    /// The `data-slot` value, when present.
    pub component_name: Option<String>,
    /// Where the component's documentation is.
    pub portal_url: Option<String>,
    /// How to fix it.
    pub fix: String,
}

/// What a whole page scored.
#[derive(Debug, Clone, PartialEq)]
pub struct A11yAuditResult {
    /// The URL audited.
    pub url: String,
    /// How many elements were observed.
    pub total_elements: usize,
    /// Every finding.
    pub violations: Vec<A11yViolation>,
    /// How many elements produced no finding.
    pub passes: usize,
    /// Percentage passing, 0-100.
    pub score: u32,
}

/// The touch-target floor the `.ts` uses, and the Apple HIG figure.
///
/// Material's is 48dp. This is a floor on the HIT AREA, not on the painted
/// control — see the module docs, defect 4.
pub const DEFAULT_TOUCH_TARGET_MIN_PX: f64 = 44.0;

/// What to check and how strictly.
#[derive(Debug, Clone, PartialEq)]
pub struct A11yConfig {
    /// Which rules to run. Empty means none, which is not the same as [`None`].
    pub rules: Option<BTreeSet<Rule>>,
    /// The hit-area floor in CSS pixels.
    pub touch_target_min_px: f64,
}

impl Default for A11yConfig {
    fn default() -> Self {
        Self {
            rules: None,
            touch_target_min_px: DEFAULT_TOUCH_TARGET_MIN_PX,
        }
    }
}

impl A11yConfig {
    /// Whether a rule is enabled. Absent configuration means every rule.
    #[must_use]
    pub fn runs(&self, rule: Rule) -> bool {
        self.rules.as_ref().is_none_or(|set| set.contains(&rule))
    }
}

/// Whether a string is usable bare after `#` in a selector.
fn is_plain_ident(value: &str) -> bool {
    let mut chars = value.chars();
    match chars.next() {
        Some(first) if first.is_ascii_alphabetic() || first == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

/// Escape a value for a double-quoted attribute selector.
fn escape_attr(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

/// A selector that finds this element again.
///
/// The `.ts` interpolates the id and the slot raw, so an id containing a quote,
/// a space or a leading digit produces a selector that does not parse — and the
/// selector's only job is to let a human or an agent locate the element. Quoted
/// attribute form is used whenever the bare form would not survive.
#[must_use]
pub fn css_selector(node: &ObservedNode) -> String {
    if let Some(id) = node.id.as_deref().filter(|s| !s.is_empty()) {
        return if is_plain_ident(id) {
            format!("#{id}")
        } else {
            format!("[id=\"{}\"]", escape_attr(id))
        };
    }
    if let Some(slot) = node.data_slot.as_deref().filter(|s| !s.is_empty()) {
        return format!("[data-slot=\"{}\"]", escape_attr(slot));
    }
    let tag = node.tag_name.to_ascii_lowercase();
    match node.first_class.as_deref().filter(|s| !s.is_empty()) {
        Some(class) if is_plain_ident(class) => format!("{tag}.{class}"),
        Some(class) => format!("{tag}[class~=\"{}\"]", escape_attr(class)),
        None => tag,
    }
}

/// The heuristic the `.ts` uses to guess a node from a slot name.
///
/// It can only ever answer 2, 3 or 6, so it is a guess and named like one. Prefer
/// [`resolve_node`], which asks the registry first.
#[must_use]
pub fn guess_node_from_slot(slot: &str) -> Option<u32> {
    if slot.is_empty() {
        return None;
    }
    if slot.starts_with("nyuchi-") && !slot.contains("page") {
        return Some(3);
    }
    if slot.contains("page") || slot.contains("layout") {
        return Some(6);
    }
    Some(2)
}

/// Which node owns the component in this slot.
///
/// The registry lookup wins; the heuristic is the fallback for a consumer
/// auditing their own app, who has no Mzizi registry to consult.
#[must_use]
pub fn resolve_node(slot: Option<&str>, registry: &BTreeMap<String, u32>) -> Option<u32> {
    let slot = slot?;
    registry
        .get(slot)
        .copied()
        .or_else(|| guess_node_from_slot(slot))
}

/// Build a violation carrying the element's identity.
fn violation(
    node: &ObservedNode,
    helix_node: Option<u32>,
    rule: Rule,
    level: A11yLevel,
    message: String,
    fix: &str,
) -> A11yViolation {
    A11yViolation {
        rule,
        level,
        message,
        element: node.tag_name.clone(),
        selector: css_selector(node),
        node: helix_node,
        component_name: node.data_slot.clone().filter(|s| !s.is_empty()),
        portal_url: node.data_portal.clone().filter(|s| !s.is_empty()),
        fix: fix.to_owned(),
    }
}

/// Check one element against every enabled rule.
///
/// `previous_heading` is the level of the last heading seen before this element,
/// which is why the caller iterates in document order. Returns every violation,
/// never just the first.
#[must_use]
pub fn check_node(
    node: &ObservedNode,
    previous_heading: Option<u8>,
    config: &A11yConfig,
    registry: &BTreeMap<String, u32>,
) -> Vec<A11yViolation> {
    let mut found = Vec::new();
    let helix_node = resolve_node(node.data_slot.as_deref(), registry);

    if config.runs(Rule::ImgAlt) && node.tag_name.eq_ignore_ascii_case("img") && node.alt.is_none()
    {
        found.push(violation(
            node,
            helix_node,
            Rule::ImgAlt,
            A11yLevel::Critical,
            "Image missing alt text".to_owned(),
            "Add alt=\"\" for decorative or alt=\"description\" for informative",
        ));
    }

    if config.runs(Rule::ButtonName) && node.is_button() && node.accessible_name().is_none() {
        found.push(violation(
            node,
            helix_node,
            Rule::ButtonName,
            A11yLevel::Critical,
            "Button missing accessible name".to_owned(),
            "Add aria-label, aria-labelledby, or visible text",
        ));
    }

    if config.runs(Rule::TouchTarget)
        && node.is_touch_target()
        && node.visible
        && let Some(hit) = node.hit_box
        && (hit.height < config.touch_target_min_px || hit.width < config.touch_target_min_px)
    {
        let min = config.touch_target_min_px.round();
        found.push(violation(
            node,
            helix_node,
            Rule::TouchTarget,
            A11yLevel::Moderate,
            format!(
                "Touch target too small ({}×{}px, min {min}×{min})",
                hit.width.round(),
                hit.height.round()
            ),
            "Extend the interactive area with padding or surrounding spacing",
        ));
    }

    // A heading may not skip a level going DOWN the document — h2 after h4 is a
    // section ending, not a gap. The first heading on a page is compared against
    // level 0, so an h3 with no h1 or h2 above it is a skip.
    if config.runs(Rule::HeadingOrder)
        && let Some(level) = node.heading_level()
    {
        let previous = previous_heading.unwrap_or(0);
        if level > previous + 1 {
            found.push(violation(
                node,
                helix_node,
                Rule::HeadingOrder,
                A11yLevel::Moderate,
                format!("Heading level skipped (h{previous} → h{level})"),
                "Use the next heading level down, or restructure the section",
            ));
        }
    }

    found
}

/// Audit a page.
///
/// `nodes` must be in document order — [`Rule::HeadingOrder`] depends on it.
///
/// An element PASSES when it produced no violation. The `.ts` counts passes in
/// branches an interactive element cannot reach, so a correct button scored as
/// neither a pass nor a violation and the page score fell as accessibility rose.
#[must_use]
pub fn audit(
    url: impl Into<String>,
    nodes: &[ObservedNode],
    config: &A11yConfig,
    registry: &BTreeMap<String, u32>,
) -> A11yAuditResult {
    let mut violations = Vec::new();
    let mut passes = 0usize;
    let mut previous_heading: Option<u8> = None;

    for node in nodes {
        let found = check_node(node, previous_heading, config, registry);
        if found.is_empty() {
            passes += 1;
        }
        violations.extend(found);
        if let Some(level) = node.heading_level() {
            previous_heading = Some(level);
        }
    }

    let total = nodes.len();
    A11yAuditResult {
        url: url.into(),
        total_elements: total,
        violations,
        passes,
        // A page with no elements is not failing anything, which is different from
        // being untested — `total_elements` says which.
        score: if total == 0 {
            100
        } else {
            ((passes as f64 / total as f64) * 100.0).round() as u32
        },
    }
}

/// The worst level present, for a single go/no-go answer.
#[must_use]
pub fn worst_level(violations: &[A11yViolation]) -> Option<A11yLevel> {
    violations.iter().map(|v| v.level).max()
}

/// Whether a result clears a score threshold.
#[must_use]
pub fn meets_threshold(result: &A11yAuditResult, threshold: u32) -> bool {
    result.score >= threshold
}

